INSERT INTO `accommodations` (`id`, `language_short_name`, `owner_id`, `country_id`, `city_id`, `name`, `folder_name`, `size`, `price`, `guest_number`, `bedroom`, `bed`, `bathroom`, `description`) VALUES
(1, 'hu', 3, 23, 67, 'Hangulatos lakás Prága szívében ', 'praga_hangulatos_lakas', 60, 65, 4, 1, 2, 1, 'Ez a kényelmes apartman Prága szívében minden igényt kielégít. A tágas szobák napfényesek, a bútorzat modern és stílusos. Ideális hely pároknak és családoknak egyaránt. A város főbb látnivalói és éttermei néhány perc sétára találhatók. Tökéletes választás a kikapcsolódásra és városnézésre.'),
(2, 'hu', 14, 23, 67, 'Hangulatos stúdió erkélyrel', 'praga_hangulatos_studio', 45, 91, 2, 1, 1, 1, 'Modern stúdió erkélyrel, ideális rövid városi tartózkodáshoz. A világos, otthonos belső tér minden kényelmet biztosít. Közel a közlekedéshez és a helyi éttermekhez. Tökéletes pároknak vagy üzleti utazóknak. Élvezze a város nyüzsgését a saját privát erkélyéről!'),
(3, 'hu', 50, 23, 67, 'Hangulatos lakás a központban', 'praga_kozponti_lakas', 50, 88, 3, 1, 1, 2, 'Napos, otthonos lakás Prága központjában. A lakás modern bútorokkal van felszerelve, és minden alapfelszereltséget biztosít a kényelmes tartózkodáshoz. A környék tele van látnivalókkal, kávézókkal és éttermekkel. Kiváló közlekedési lehetőségek, ideális bármilyen utazásra. Élvezze a városi élet minden pillanatát ebben a hangulatos lakásban.'),
(4, 'hu', 22, 7, 19, 'Charmantes Studio zentral', 'charmantes_studio', 45, 88, 2, 1, 1, 1, 'Stílusos, csendes stúdió Bécsben, minden szükséges felszereléssel. A modern belső terek kellemes légkört biztosítanak a pihenéshez. Ideális pároknak és rövid városi tartózkodásokhoz. A város nevezetességei és éttermei könnyen elérhetők. Tökéletes kiindulópont Bécs felfedezéséhez.'),
(5, 'hu', 12, 7, 19, 'Menő bécsi lakás', 'meno_becsi_lakas', 45, 82, 2, 1, 1, 1, 'Fiatalos, kényelmes lakás Bécs központjában, ideális városnézéshez. A világos és praktikus bútorozás minden igényt kielégít. Közel a tömegközlekedéshez és helyi éttermekhez. Nyugodt környék és kényelmes pihenés biztosított. Tökéletes választás baráti társaságoknak vagy pároknak.'),
(6, 'hu', 65, 3, 8, 'Pulz Apartman', 'pulz_apartman', 50, 41, 4, 1, 3, 1, 'Felújított apartman Szegeden, közel a belvároshoz és piachoz. Tágas és világos szobák, modern berendezés. Ideális családoknak és rövid tartózkodásokhoz. A környék tele van éttermekkel és kulturális látnivalókkal. Kényelmes és otthonos hangulat várja a vendégeket.'),
(7, 'hu', 4, 3, 7, 'Belváros, Budapest Szabadság Rezidencia ', 'budapest_szabadsag_rezidencia', 60, 54, 2, 1, 1, 1, 'Modern lakás Budapest belvárosában, kiváló elhelyezkedéssel. A lakás világos, jól felszerelt, ideális pároknak vagy üzleti utazóknak. A környék tele van éttermekkel, kávézókkal és látnivalókkal. Kényelmes hozzáférés a tömegközlekedéshez. Tökéletes választás városnézéshez és pihenéshez.'),
(8, 'hu', 3, 3, 7, 'Belvárosi apartman', 'belvarosi_apart', 45, 74, 4, 2, 2, 1, 'Kényelmes apartman Budapest szívében, otthonos hangulattal. A modern bútorok és a praktikus elrendezés minden igényt kielégít. Ideális családoknak vagy baráti társaságoknak. A közeli éttermek, boltok és látnivalók könnyen elérhetők. Tökéletes hely a városi élményekhez és a pihenéshez.'),
(9, 'hu', 4, 3, 7, 'Modern stúdió', 'modern_studio', 40, 68, 2, 1, 1, 1, 'Világos, modern stúdió Budapest központjában. Kényelmes bútorok, praktikus elrendezés és minden szükséges felszerelés. Ideális pároknak vagy üzleti utazóknak. A város nevezetességei és éttermei sétatávolságra találhatók. Tökéletes kombinációja a kényelemnek és a városi életnek.'),
(10, 'hu', 5, 3, 9, 'Panorámás lakás', 'panorama_lakas', 70, 84, 6, 3, 4, 2, 'Tágas lakás gyönyörű kilátással, ideális családoknak. A modern berendezés és kényelmes bútorok minden igényt kielégítenek. Közel a város központjához és látnivalóihoz. A környék csendes, nyugodt pihenést biztosít. Élvezze a panorámás kilátást a nap minden szakában.'),
(13, 'hu', 8, 7, 19, 'Bécsi belvárosi lakás', 'becsi_belvarosi', 60, 89, 5, 2, 3, 2, 'Elegáns lakás Bécs belvárosában, közel a látnivalókhoz. A tágas és világos belső tér ideális családoknak és pároknak. Modern bútorok és minden szükséges felszerelés. Sétatávolságra éttermek és kávézók. Kényelmes kiindulópont a város felfedezéséhez.'),
(14, 'hu', 9, 7, 19, 'Kompakt stúdió', 'kompakt_studio', 30, 55, 2, 1, 1, 1, 'Kompakt stúdió Bécsben, ideális rövid tartózkodásokhoz. A praktikus elrendezés és világos belső tér minden igényt kielégít. Közel a város főbb nevezetességeihez és közlekedéshez. Tökéletes pároknak vagy egyéni utazóknak. Kényelmes és otthonos hangulat várja a vendégeket.'),
(15, 'hu', 10, 5, 14, 'Tengerparti apartman', 'tengerparti_ap', 75, 100, 6, 3, 4, 2, 'Tengerparti apartman közvetlenül a strand mellett. Világos és tágas belső tér, modern bútorokkal. Ideális családoknak vagy baráti társaságoknak. A környék tele van éttermekkel és kikapcsolódási lehetőségekkel. Élvezze a nyári napfényes pihenést a part közelében.'),
(16, 'hu', 11, 5, 13, 'Városi stúdió', 'varosi_studio', 42, 66, 2, 1, 1, 1, 'Modern városi stúdió Madrid központjában. Világos és praktikus, minden szükséges felszereléssel. Ideális pároknak és üzleti utazóknak. Közel a főbb látnivalókhoz és közlekedési csomópontokhoz. Kényelmes és stílusos tartózkodás a városban.'),
(17, 'hu', 12, 4, 10, 'Romantikus lakás', 'romantikus_lakas', 48, 76, 4, 2, 2, 1, 'Romantikus lakás Párizsban, kiváló elhelyezkedéssel. A belső terek elegánsak, stílusosak és otthonosak. Ideális pároknak romantikus kiruccanáshoz. A környék tele van éttermekkel, kávézókkal és látnivalókkal. Élvezze a párizsi hangulat minden pillanatát.'),
(18, 'hu', 13, 4, 11, 'Erkélyes apartman', 'erkelyes_apart', 55, 82, 5, 2, 3, 2, 'Világos erkélyes apartman Párizsban. Modern bútorok és kényelmes elrendezés minden igényt kielégít. Ideális családoknak és baráti társaságoknak. Közel a város főbb nevezetességeihez. Élvezze a friss levegőt és a város látványát a privát erkélyről.'),
(19, 'hu', 14, 6, 16, 'Fiatalos stúdió', 'fiatalos_studio', 28, 63, 2, 1, 1, 1, 'Fiatalos stúdió Berlinben, modern felszereltséggel. Ideális pároknak és üzleti utazóknak. Világos és otthonos belső tér biztosítja a kényelmet. Közel a közlekedéshez és a helyi látnivalókhoz. Tökéletes rövid tartózkodásokhoz.'),
(20, 'hu', 3, 6, 17, 'Családi lakás', 'csaladi_lakas', 80, 95, 6, 3, 4, 2, 'Tágas családi lakás Berlinben. Modern bútorok és jól felszerelt konyha. Ideális nagyobb családoknak. Közel a város nevezetességeihez és parkjaihoz. Kényelmes, otthonos hely a pihenéshez és kikapcsolódáshoz.'),
(21, 'hu', 4, 18, 52, 'Tengerre néző apartman', 'tengerre_nez', 65, 87, 4, 2, 2, 1, 'Tengerre néző apartman, nyugodt környezetben. Tágas és világos belső tér, minden kényelmi felszereléssel. Ideális pároknak és családoknak. Közel a strandhoz és éttermekhez. Élvezze a nyugodt tengerparti pihenést.'),
(23, 'hu', 6, 21, 61, 'Hegyi apartman', 'hegyi_apartman', 72, 74, 6, 3, 4, 2, 'Hegyi apartman, természetközeli pihenéshez. Tágas és világos, modern bútorokkal. Ideális családoknak és baráti társaságoknak. A környék tele van kirándulási lehetőségekkel és látnivalókkal. Kényelmes és otthonos hely a kikapcsolódásra.'),
(24, 'hu', 7, 19, 55, 'Skandináv stúdió', 'skandinav_studio', 38, 68, 2, 1, 1, 1, 'Skandináv stúdió, letisztult dizájnnal. Modern felszereltség, kényelmes elrendezés. Ideális pároknak és üzleti utazóknak. Közel a város nevezetességeihez és éttermeihez. Praktikus és stílusos választás rövid tartózkodáshoz.'),
(25, 'hu', 8, 12, 34, 'Luxus lakosztály', 'luxus_lakosztaly', 120, 145, 8, 4, 5, 3, 'Luxus lakosztály New Yorkban, prémium felszereltséggel. Tágas és elegáns belső tér, kényelmes bútorokkal. Ideális családoknak és baráti társaságoknak. Közel a város látnivalóihoz. Élvezze a prémium pihenést a metropolisz szívében.'),
(26, 'hu', 9, 12, 36, 'Városi stúdió', 'varosi_studio', 34, 71, 2, 1, 1, 1, 'Városi stúdió New Yorkban, ideális üzleti utazóknak. Világos és modern belső tér, praktikus felszereltséggel. Közel a közlekedéshez és a város nevezetességeihez. Kényelmes és otthonos hely rövid tartózkodáshoz.'),
(27, 'hu', 10, 2, 4, 'Mediterrán apartman', 'mediterran_apart', 60, 82, 4, 2, 3, 2, 'Mediterrán apartman Rómában, hangulatos belső térrel. Tágas és világos, modern bútorokkal. Ideális családoknak és pároknak. Közel a város nevezetességeihez és éttermekhez. Élvezze az olasz életstílust kényelmes környezetben.'),
(28, 'hu', 11, 2, 5, 'Belvárosi lakás', 'belvarosi_lakas', 45, 76, 4, 2, 2, 1, 'Belvárosi lakás Milánóban, kényelmes és otthonos. Világos belső tér, jól felszerelt. Ideális pároknak és családoknak. Közel a város főbb látnivalóihoz és közlekedéshez. Tökéletes kiindulópont Milánó felfedezéséhez.'),
(29, 'hu', 12, 8, 22, 'Történelmi lakás', 'tortenelmi_lakas', 55, 68, 5, 2, 3, 2, 'Történelmi hangulatú görög lakás. Klasszikus berendezés, világos és tágas. Ideális családoknak és baráti társaságoknak. Közel a helyi látnivalókhoz és éttermekhez. Élvezze a tradicionális görög környezetet kényelmesen.'),
(30, 'hu', 13, 8, 23, 'Modern stúdió', 'modern_studio', 30, 55, 2, 1, 1, 1, 'Modern stúdió Görögországban, praktikus és kényelmes. Világos belső tér minden igényt kielégít. Ideális pároknak és rövid tartózkodáshoz. Közel a helyi látnivalókhoz és éttermekhez. Tökéletes választás a kikapcsolódásra.'),
(31, 'hu', 14, 3, 211, 'Hagymatikum közelében', 'hagymatikum_kozel', 50, 66, 4, 2, 2, 1, 'Kényelmes lakás Makón, közel a Hagymatikum fürdőhöz. Tágas és világos, modern bútorokkal. Ideális családoknak és pároknak. A környék tele van éttermekkel és látnivalókkal. Tökéletes hely a pihenésre és kikapcsolódásra.'),
(32, 'hu', 1, 23, 67, 'Prágai Panorama Lakás', 'pragai_panorama_lakas', 65, 95, 4, 2, 3, 2, 'Tágas és napfényes lakás Prága szívében. Modern bútorok, kényelmes ágyak és teljes felszereltség várja a vendégeket. Közel a híres látnivalókhoz, éttermekhez és kávézókhoz. Ideális családoknak és pároknak. Élvezze a városi élet minden pillanatát a panorámás ablakokból.'),
(33, 'hu', 2, 23, 68, 'Brnoi Stílus Apartman', 'brnoi_stilus_apart', 55, 88, 3, 1, 2, 1, 'Hangulatos és stílusos apartman Brno központjában. Világos terek, modern bútorok és kényelmes ágyak várják a vendégeket. Ideális pároknak és kis családoknak. Közel éttermekhez és közlekedési csomópontokhoz. Tökéletes választás városnézéshez és pihenéshez.'),
(34, 'hu', 3, 23, 69, 'České Budějovice Luxus Lakás', 'ceske_budejovice_luxus', 60, 90, 4, 2, 2, 1, 'Elegáns, modern lakás České Budějovice belvárosában. Tágas nappali, jól felszerelt konyha és kényelmes hálószoba. Ideális családoknak vagy baráti társaságoknak. Közel a város főbb nevezetességeihez. Élvezze a cseh városi élet minden pillanatát.'),
(35, 'hu', 4, 3, 7, 'Budapesti Luxus Lakás', 'budapesti_luxus_lakas', 80, 110, 6, 3, 4, 2, 'Tágas, modern lakás Budapest belvárosában. Elegáns bútorok, teljesen felszerelt konyha és kényelmes hálószobák. Ideális családoknak és baráti társaságoknak. Közel a látnivalókhoz és éttermekhez. Élvezze a főváros nyüzsgő életét minden pillanatban.'),
(36, 'hu', 5, 3, 8, 'Szegedi Belvárosi Apartman', 'szeged_belvarosi_apart', 70, 50, 5, 2, 3, 2, 'Világos és kényelmes apartman Szeged belvárosában. Modern bútorok és praktikus elrendezés. Közel piacokhoz, éttermekhez és kulturális helyszínekhez. Ideális családoknak és barátoknak. Tökéletes hely a pihenésre és városi élményekhez.'),
(37, 'hu', 6, 3, 9, 'Debreceni Panorama Lakás', 'debreceni_panorama_lakas', 65, 55, 4, 2, 3, 2, 'Tágas, modern lakás Debrecen központjában. Világos nappali és kényelmes hálószobák. Teljes felszereltség, ideális családoknak és pároknak. Sétatávolságra éttermekhez és bevásárlási lehetőségekhez. Élvezze a debreceni városi élet minden pillanatát.'),
(38, 'hu', 7, 2, 4, 'Római Elegancia Lakás', 'romai_elegancia_lakas', 75, 120, 5, 2, 3, 2, 'Elegáns, világos lakás Róma központjában. Modern berendezés, kényelmes ágyak, teljes felszereltség. Ideális pároknak vagy családoknak. Közel a történelmi látnivalókhoz. Tökéletes választás a romantikus városi sétákhoz.'),
(39, 'hu', 8, 2, 5, 'Milánói Stílus Apartman', 'milanoi_stilus_apart', 60, 100, 4, 2, 2, 1, 'Modern, elegáns lakás Milánó szívében. Világos és tágas nappali, kényelmes hálószobák. Ideális üzleti utazóknak vagy pároknak. Közel a közlekedéshez és a divatnevezetességekhez. Élvezze Milánó vibráló hangulatát.'),
(40, 'hu', 9, 2, 6, 'Nápolyi Tengerparti Lakás', 'napolyi_tengerparti', 70, 95, 5, 2, 3, 2, 'Világos és tágas apartman Nápoly tengerparti részén. Modern bútorok, teljes felszereltség, ideális családoknak. Közel éttermekhez és strandokhoz. Élvezze a napfényt és a tengeri panorámát minden nap.'),
(41, 'hu', 10, 6, 16, 'Berlin Modern Lakás', 'berlin_modern_lakas', 50, 80, 3, 1, 2, 1, 'Fiatalos, világos apartman Berlin központjában. Kényelmes ágyak és praktikus bútorok. Ideális pároknak vagy üzleti utazóknak. Közel tömegközlekedéshez és éttermekhez. Tökéletes városi pihenéshez.'),
(42, 'hu', 11, 6, 17, 'München Luxus Lakás', 'munchen_luxus_lakas', 60, 105, 4, 2, 3, 2, 'Elegáns, tágas lakás München szívében. Modern bútorok és jól felszerelt konyha. Ideális családoknak és barátoknak. Közel a főbb nevezetességekhez. Élvezze a bajor város hangulatát.'),
(43, 'hu', 12, 6, 18, 'Kölni Stílus Apartman', 'kolni_stilus_apart', 55, 90, 3, 1, 2, 1, 'Világos és modern lakás Köln belvárosában. Kényelmes ágyak és teljes felszereltség. Ideális pároknak és kis családoknak. Közel a látnivalókhoz és éttermekhez. Tökéletes választás rövid városi tartózkodáshoz.'),
(44, 'hu', 13, 7, 19, 'Bécsi Elegancia Lakás', 'becsi_elegancia_lakas', 65, 95, 4, 2, 3, 2, 'Tágas, elegáns lakás Bécs központjában. Modern bútorok és kényelmes ágyak. Ideális pároknak és üzleti utazóknak. Közel a látnivalókhoz, éttermekhez és kávézókhoz. Élvezze a bécsi élet minden pillanatát.'),
(45, 'hu', 14, 7, 20, 'Linzi Panorama Apartman', 'linzi_panorama_apart', 60, 85, 4, 2, 2, 1, 'Világos, modern apartman Linz belvárosában. Kényelmes bútorok, teljes felszereltség. Ideális családoknak és pároknak. Közel éttermekhez és kulturális látnivalókhoz. Élvezze a városi élet minden pillanatát.'),
(46, 'hu', 15, 7, 21, 'Salzburg Történelmi Lakás', 'salzburg_tortenelmi_lakas', 55, 90, 4, 2, 2, 1, 'Stílusos lakás Salzburg történelmi belvárosában. Világos nappali, kényelmes ágyak és jól felszerelt konyha. Ideális pároknak és kis családoknak. Sétatávolságra a főbb látnivalóktól. Élvezze a történelmi város hangulatát.'),
(47, 'hu', 16, 8, 22, 'Athéni Panorama Lakás', 'atheni_panorama_lakas', 60, 95, 4, 2, 3, 2, 'Tágas és világos lakás Athén szívében. Modern bútorok, kényelmes ágyak. Ideális pároknak és családoknak. Közel az ókori látnivalókhoz és éttermekhez. Élvezze a mediterrán élet minden pillanatát.'),
(48, 'hu', 17, 8, 23, 'Szaloniki Modern Lakás', 'szaloniki_modern_lakas', 55, 90, 4, 2, 2, 1, 'Világos, modern lakás Szalonikiben. Kényelmes ágyak, teljes felszereltség. Ideális pároknak és kis családoknak. Közel a város látnivalóihoz és éttermekhez. Élvezze a görög életstílust minden pillanatban.'),
(49, 'hu', 18, 8, 24, 'Rodoszi Tengerparti Lakás', 'rodoszi_tengerparti', 65, 100, 5, 2, 3, 2, 'Tágas apartman Rodosz szigetén, közel a tengerparthoz. Modern bútorok és kényelmes ágyak. Ideális családoknak és baráti társaságoknak. Közel éttermekhez és látnivalókhoz. Élvezze a napsütést és a tengerparti pihenést.'),
(50, 'hu', 19, 5, 13, 'Madrid Elegáns Apartman', 'madrid_elegans_apart', 60, 95, 4, 2, 2, 1, 'Világos, stílusos lakás Madrid központjában. Modern bútorok és kényelmes ágyak. Ideális pároknak és családoknak. Közel a város főbb látnivalóihoz és éttermekhez. Élvezze a spanyol városi élet minden pillanatát.'),
(51, 'hu', 20, 5, 14, 'Barcelona Tengerparti Lakás', 'barcelona_tengerparti', 65, 105, 5, 2, 3, 2, 'Tágas apartman Barcelona központjában, közel a tengerparthoz. Modern bútorok és teljes felszereltség. Ideális családoknak és barátoknak. Közel látnivalókhoz és éttermekhez. Élvezze a katalán városi életet és a tengerparti pihenést.'),
(52, 'hu', 21, 5, 15, 'Sevilla Romantikus Lakás', 'sevilla_romantikus_lakas', 55, 90, 4, 2, 2, 1, 'Stílusos, világos apartman Sevilla történelmi részén. Kényelmes bútorok és jól felszerelt konyha. Ideális pároknak és kis családoknak. Közel a város főbb nevezetességeihez és éttermekhez. Élvezze a spanyol hangulatot minden pillanatban.'),
(53, 'hu', 22, 1, 1, 'Tokió Modern Lakás', 'tokio_modern_lakas', 60, 110, 4, 2, 3, 2, 'Tágas, világos lakás Tokió központjában. Modern bútorok, kényelmes ágyak. Ideális pároknak és üzleti utazóknak. Közel éttermekhez, bevásárlóközpontokhoz és látnivalókhoz. Élvezze a japán nagyvárosi élet minden pillanatát.'),
(55, 'hu', 24, 1, 3, 'Szapporói Tengerparti Lakás', 'szapporoi_tengerparti', 60, 100, 4, 2, 3, 2, 'Tágas, világos lakás Szapporo városában. Modern bútorok és kényelmes ágyak. Ideális családoknak és barátoknak. Közel éttermekhez és látnivalókhoz. Élvezze a japán városi és természetközeli élményeket.'),
