INSERT INTO `experiences` (`id`, `language_short_name`, `country_id`, `city_id`, `name`, `folder_name`, `price`, `description`) VALUES
(1, 'hu', 3, 211, 'Hagymatikum Gyógyfürdő élmény', 'hagymatikum_furdo', 65, 'Fedezze fel Makó egyik legismertebb turisztikai vonzerejét, a Hagymatikum Gyógyfürdőt. A különleges Makovecz‑stílusú épület önmagában is különleges látványt nyújt. A gyógyvizes medencék és wellness részlegek egész napos kikapcsolódást kínálnak minden korosztálynak. Élvezze a wellness szolgáltatásokat, szaunaparkot és gyógyvizes fürdőket egyaránt. Tökéletes választás családoknak, pároknak és baráti társaságoknak egyaránt.'),
(2, 'hu', 23, 67, 'Prágai óvárosi városnézés', 'praga_ovaros', 45, 'Fedezze fel Prága történelmi óvárosát egy részletes séta során, ahol a macskaköves utcák és történelmi épületek mesélnek a város múltjáról. Látogassa meg az Óvárosi teret, az Orloj asztronómiai órát és a közeli falusias sikátorokat. Az élmény során helyi történeteket és legendákat ismerhet meg. Prága különleges hangulatát a kávézók és bábjátékosok teszik feledhetetlenné. A nap végén egy helyi étteremben kóstolja meg a cseh konyha specialitásait.'),
(3, 'hu', 23, 67, 'Prágai vár és Szent Vitus székesegyház', 'praga_var', 55, 'Látogassa meg Prága legismertebb történelmi komplexumát, ahol több évszázad eseményeit ismerheti meg. A Szent Vitus székesegyház impozáns gótikus építészete és részletes díszítése lenyűgöző. Sétáljon végig a vár falain, és csodálja meg a panorámát a városra. A környéken múzeumok és parkok is megtalálhatók. Az élmény különösen fotóbarát helyszínekkel gazdagítja a városnézést.'),
(4, 'hu', 23, 67, 'Vltava hajókirándulás', 'vltava_hajo', 55, 'Ugorjon fel egy folyami hajóra és élvezze a Vltava folyó látványát Prágában. A Károly híd, a városi panoráma és a parti épületek egészen új perspektívából tárulnak fel. A fedélzeti idegenvezetés érdekes történeteket mesél a városról. A naplemente különösen romantikus a fedélzetről. Érdemes vacsorával kombinálni az élményt egy teljes napos programért.'),
(5, 'hu', 7, 19, 'Bécsi klasszikus zenei est', 'becs_zene', 60, 'Merüljön el Bécs világhírű zenei életében egy klasszikus koncert során, ahol Mozart, Strauss és más nagy művészek művei csendülnek fel. A történelmi koncertterem csodás akusztikája és díszítése emlékezetes élményt nyújt. A koncert előtt sétáljon a környék bájos utcáin. A város kávéházaiban élvezheti a helyi süteményeket és kávékat. Ideális program kultúra és zene kedvelőknek.'),
(6, 'hu', 7, 19, 'Schönbrunni kastély és kert', 'schonbrunn', 50, 'Fedezze fel a Schönbrunni kastély pompás termeit, amelyek az osztrák császári család egykori rezidenciáját idézik. A barokk stílusú kertek és parkok tökéletes helyet adnak egy pihentető sétához. Látogassa meg a kastély állatkertjét is, amely Európa egyik legrégebbi. A panoráma a kertből csodás kilátást nyújt Bécsre. A program tartalmaz fotószüneteket és idegenvezetést is.'),
(7, 'hu', 7, 20, 'Linz Duna-parti séta', 'linz_duna', 30, 'Vegyen részt egy kellemes sétán a Duna partján Linz városában, ahol a modern és történelmi építészet találkozik. A Duna partja mentén kávézók és kilátópontok várják a látogatókat. A folyóparti sétány ideális piknikezéshez vagy pihenéshez. A város művészeti negyedét is érdemes felkeresni. A séta során megismerheti Linz kultúráját és hangulatát.'),
(8, 'hu', 3, 7, 'Budapesti Parlament túra', 'parlament', 40, 'Ismerje meg Budapest ikonikus Parlament épületét egy izgalmas vezetett túra során. A neogótikus stílus belső termei lenyűgöznek minden látogatót. Megtekintheti a koronázási ékszereket és ritka történelmi relikviákat. A túra során sok érdekességet tudhat meg Magyarország történelméről. Ajánlott előfoglalással érkezni a nagy érdeklődés miatt.'),
(9, 'hu', 3, 7, 'Duna esti hajózás', 'duna_hajo', 55, 'Élje át Budapest varázslatos esti panorámáját egy dunai hajókiránduláson keresztül. A kivilágított Lánchíd, Parlament és Budai Vár pazar látványt nyújtanak. A fedélzeten étel és ital is elérhető. A program romantikus hangulatot kínál pároknak vagy baráti társaságoknak egyaránt. Kiváló fotóhelyszínek minden irányban.'),
(10, 'hu', 3, 7, 'Budai Várnegyed séta', 'budai_var', 40, 'Sétáljon végig a történelmi Budai Várnegyed utcáin, ahol a középkori falak és várfalak mesélnek a múlt századokról. A kilátás a városra és a Dunára egyedülálló. A nevezetességek között található a Halászbástya és Mátyás temploma. A környék tele van múzeumokkal és hangulatos kávézókkal. Ideális kulturális és pihentető napra.'),
(11, 'hu', 3, 8, 'Szegedi belvárosi séta', 'szeged_seta', 30, 'Fedezze fel Szeged napfényes belvárosát, híres szecessziós épületeit és tágas tereit. A Dóm tér látványos katedrálisa különleges fotótémát kínál. A séta során felfedezheti a helyi kávézókat, parkokat és kulturális helyszíneket. A város gasztronómiája is megér egy próbát helyi specialitásokkal. A nyugodt utcák ideálisak egy kellemes délutáni programhoz.'),
(12, 'hu', 3, 9, 'Debreceni Nagytemplom látogatás', 'debrecen_nagytemplom', 25, 'Ismerje meg Debrecen történelmi ékességét, a Nagytemplomot, amely a város szimbóluma. A hatalmas épület belső tere lenyűgöző és gazdag vallási örökséget hordoz. A templom környéke ideális sétára és pihenésre. Fedezze fel a helyi kulturális negyedet és kávézókat. A város más nevezetességekkel is várja a látogatókat.'),
(13, 'hu', 4, 10, 'Eiffel‑torony látogatás', 'eiffel_torony', 55, 'Látogassa meg Párizs ikonikus Eiffel‑toronyját és élvezze a panorámát a városra minden szinten. A torony története több mint 130 éves és világszerte ismert. A közeli Champ de Mars park ideális piknikezéshez. A torony környezetében számos kávézó és étterem várja a látogatókat. A kilátóponton történő naplemente különösen lenyűgöző élmény.'),
(14, 'hu', 4, 10, 'Szajna parti romantikus séta', 'szajna_seta', 35, 'Élvezze a Szajna folyó menti sétát Párizs szívében, ahol hídak és történelmi épületek sorakoznak. Kávézók és kis butikok tarkítják az útvonalat. A séta során megállhat a Louvre vagy a Notre‑Dame közelében. Ideális romantikus program egy napvégi vacsorával kombinálva. A hely varázsa minden évszakban érezhető.'),
(15, 'hu', 6, 16, 'Berlin történelmi városnézés', 'berlin_tortenelem', 45, 'Fedezze fel Berlin történelmi központját, amely a modern és a múlt emlékeit egyaránt bemutatja. A Brandenburgi kapu, a berlini fal maradványai és a Reichstag épülete mind jelentős látnivalók. A város számos múzeuma és parkja egész napos programot biztosít. A helyi gasztronómia Berlin egyéni jellegét tükrözi. Ideális városlátogatás családoknak és barátoknak egyaránt.'),
(16, 'hu', 6, 17, 'München sörkultúra túra', 'munchen_sor', 50, 'Ismerje meg München híres sörkultúráját egy tradicionális sörfőzde látogatással és kóstolóval. A bajor sörök világhírűek, és az autentikus hangulatot a helyi sörkertek adják. A túra során szakértő vezető mesél a sörfőzés történetéről és hagyományairól. A város történelmi terein és parkjain keresztül sétálva még több látványosságot fedezhet fel. Kiváló élmény baráti társaságoknak vagy sörkedvelőknek.'),
(17, 'hu', 2, 4, 'Római Colosseum felfedezés', 'colosseum', 60, 'Fedezze fel az ókori Róma egyik legismertebb történelmi emlékét, a Colosseumot. A hatalmas amfiteátrum gladiátorjátékainak emlékét idézi fel. A vezetett túra során a részletes történetek még mélyebbé teszik az élményt. A közeli Forum Romanum és Palatinus domb is felfedezésre vár. Ideális program történelem iránt érdeklődőknek.'),
(18, 'hu', 2, 5, 'Milánói divatnegyed séta', 'milano_divat', 45, 'Fedezze fel Milánó világmárkák által uralt divatnegyedét, ahol a legújabb trendeket követő üzletek sorakoznak. A séta során a Dóm tér és az elegáns bevásárlóutcák is útba esnek. A helyi kávézók és designer üzletek kiváló programot kínálnak vásárlóknak és látogatóknak. A város kulturális és történelmi helyszínei egyaránt elérhetők gyalogosan vagy tömegközlekedéssel. A divat és történelem különleges keveréke minden látogatót lenyűgöz.'),
(19, 'hu', 8, 22, 'Athéni Akropolisz látogatás', 'athen_akropolisz', 55, 'Látogassa meg Athén ókori dombját, ahol az Akropolisz áll, és csodálja meg a Parthenón lenyűgöző maradványait. A helyszín több évezredes történelmet hordoz, és a városra nyíló panoráma sehol máshol nem hasonlítható. A görög mitológia nagyszerű történeteivel teli túra különösen izgalmas. A környék tele van múzeumokkal és kültéri piacokkal, ahol helyi finomságokat kóstolhat. Az élmény egész napos programot kínál művészet és történelem szerelmeseinek.'),
(20, 'hu', 8, 24, 'Rodoszi tengerparti pihenés', 'rodosz_part', 50, 'Élvezze Rodosz szigetén a homokos tengerpartok pihentető hangulatát és a kristálytiszta vizet. A strandok ideálisak úszásra, napozásra és vízi sportokra. A környéken bárok és éttermek kínálnak mediterrán ízeket és hűsítő italokat. A naplemente látványa a tenger felett felejthetetlen élmény. Ez a program tökéletes választás nyári pihenésre vágyóknak.'),
(21, 'hu', 19, 55, 'Stockholmi óvárosi séta', 'stockholm_ovaros', 45, 'Fedezze fel Stockholm történelmi óvárosát, Gamla Stant, ahol szűk utcák, színes házak és hangulatos teraszok várják. A város gazdag történelmének megismerése során múzeumok és látogatói központok is szerepelnek a programban. A parti kilátás és a skandináv stílusú kávézók különleges hangulatot adnak az élménynek. Séta közben érdemes helyi kézműves termékeket és specialitásokat kóstolni. Stockholm kulturális és természeti értékeket egyaránt kínál látogatói számára.'),
(22, 'hu', 19, 56, 'Malmö modern városnézés', 'malmo_modern', 35, 'Ismerje meg Malmö modern arcát, ahol a városfenntartó és dizájn megoldások egyedi hangulatot teremtenek. A város zöld parkjai és innovative városi terei ideálisak sétához. A helyi utcai művészetek és kávéházak hangulata különleges élményt nyújt. A város a tengerpart közelségével és kikötőivel kombinálja a fiatalos életérzést. Ideális többnapos városnézéshez vagy pihentető programhoz.'),
(23, 'hu', 20, 58, 'Oslo fjord túra', 'oslo_fjord', 60, 'Látogassa meg Oslo híres fjordját és élvezze a norvég természet közelségét a városi környezetben. Hajókiránduláson keresztül fedezheti fel a fjord nyújtotta panorámát és különleges öblöket. A fjord menti túrák során vízre néző kávézók és éttermek is várják a látogatókat. A levegő tisztasága és a hegyvidéki kilátás felejthetetlen élményt kínál. Az egész napos program alkalmas természet és városi élet kombinálására.'),
(24, 'hu', 21, 61, 'Helsinki design városnézés', 'helsinki_design', 40, 'Fedezze fel Helsinki modern designkultúráját, amely világhírű az építészet és kreatív terek terén. A város letisztult épületei, galériái és múzeumai inspiráló élményt nyújtanak. Séta közben látogassa meg a helyi dizájnboltokat és kávézókat. A tengerparti sétányok és parkok nyugodt hangulatot biztosítanak a pihenéshez. Helsinkiben a kultúra és a természet harmonikusan egyesül. '),
(25, 'hu', 22, 64, 'Varsói történelmi központ', 'varso_ovaros', 35, 'Fedezze fel Varsó történelmi belvárosát, ahol újjáépített óvárosi terek és kávézók várják a látogatókat. A város gazdag történelméről rengeteg információ található helyi múzeumokban. Séta közben fedezze fel a királyi palotát és a városfal maradványait. A lengyel konyha ízei és helyi borai remekül kiegészítik a programot. Ideális kombinált városnézéshez és pihenéshez.'),
(26, 'hu', 7, 19, 'Bécsi Prater vidámpark élmény', 'becsi_prater', 55, 'A Bécsi Prater vidámpark egy legendás szórakoztató terület Bécsben, ahol minden korosztály talál kedvére való attrakciót. A park ikonikus óriáskereke, a Riesenrad különleges panorámát nyújt a városra, melyet nem érdemes kihagyni. A vidámparkban számos hullámvasút, játék és étterem várja a látogatókat egész napos szórakozással. A hely története több mint egy évszázados, így nemcsak szórakozás, hanem történelmi élmény is. Ideális családoknak és baráti társaságoknak egyaránt, napközbeni vagy esti programnak is.'),
(27, 'hu', 7, 19, 'Bécsi karácsonyi vásár', 'becsi_karacsonyi_vasar', 45, 'Ha Bécsben jársz november végétől decemberig, ne hagyd ki a híres karácsonyi vásárokat, ahol több tucat kézműves stand vár tradicionális ajándékokkal és finomságokkal. A Rathausplatzon megrendezett vásárban helyi ételeket, forralt bort és ünnepi kézműves termékeket kóstolhatsz. A hangulatot élő zene, fények és családi programok teszik felejthetetlenné. A vásárok a város több pontján is megtalálhatók, így könnyen beilleszthetők egy szélesebb városnéző napba. A karácsonyi forgatag Bécs kulturális tradíciójának egyik csúcspontja. '),
(28, 'hu', 23, 67, 'Prágai Károly híd esti séta', 'praga_karoly_hid', 40, 'Sétálj át a történelmi Károly hídon, amely a 14. században épült és ma Prága egyik legismertebb nevezetessége. A híd felett idegenvezetés nélkül is gyönyörű kilátás nyílik a Vltava folyóra, valamint a város látképére naplementekor különösen lenyűgöző. A híd mentén utcai művészek és hangszeres zenészek adnak autentikus prágai hangulatot. A környék szűk utcái és hangulatos kávézói remek kiegészítők egy esti programhoz. Ez a séta tökéletes kezdete lehet Prága történelmi felfedezésének. '),
(29, 'hu', 23, 67, 'Prágai Nemzeti Színház estje', 'praga_nemzeti_szinhaz', 60, 'Élvezd a klasszikus cseh kultúrát a prágai Nemzeti Színház egyik előadásán, ahol opera, balett vagy dráma várja a közönséget. A történelmi épület díszes belső terei és kiváló akusztikája egyaránt hozzájárulnak az élményhez. A helyi művészek és vendégfellépők előadásai nemcsak helyiek, hanem látogatók számára is felejthetetlen élményt nyújtanak. A program egyaránt szól a művészetek iránt elkötelezetteknek és azoknak, akik új kulturális élményekre vágynak. Foglalj jegyet előre a legjobb helyekre. '),
(30, 'hu', 23, 67, 'Prágai sörkóstoló túra', 'praga_sorkostolo', 45, 'Fedezd fel a prágai sörkultúrát egy vezetett sörkóstoló túra során, ahol több helyi sörözőt is meglátogatsz. Csehország híres kiváló söréről és ez a túra lehetőséget ad megkóstolni többféle stílust egy estére egybefűzve. Az idegenvezetők mesélnek a sörfőzés történetéről és a helyi tradíciókról. A részvétel baráti társaságoknak vagy egyedi gasztroprogramnak is kiváló. A séta mellett helyi falatokat is ajánlott kóstolni. '),
(31, 'hu', 7, 19, 'Bécsi művészeti galériák', 'becsi_muveszet', 50, 'Bécs gazdag múzeumi és galériás kultúrával rendelkezik, ahol a klasszikus és modern művészetek találkoznak. Látogass el a város híres múzeumaiba, ahol többek között festmények, szobrok és kiállítások várják a látogatókat. A Kunsthistorisches és Albertina gyűjtemények kifejezetten izgalmasak a művészetek iránt érdeklődők számára. A galériák között sétálva megismerheted a Habsburg uralkodók műgyűjteményét is. A program egész napos kulturális kiegészítője lehet egy városnézésnek. '),
(32, 'hu', 3, 7, 'Széchenyi termálfürdő és wellness', 'budapest_szechenyi', 50, 'Tapasztald meg Budapest híres termálfürdőjének, a Széchenyi Fürdőnek a pihentető élményét, amely Európa egyik legnagyobb gyógyfürdő komplexuma. A neo‑barokk épület gyógyvizes medencéi és wellness szolgáltatásai egész napos pihenést kínálnak. A fürdőben szaunák, gőzfürdők és masszázs szolgáltatások is elérhetők. A hely különleges hangulatát a helyiek és a turisták egyaránt szeretik. A fürdőzés után érdemes egy tradicionális magyar éttermet is kipróbálni a környéken. '),
(33, 'hu', 3, 7, 'Budapesti városnéző biciklitúra', 'budapest_bicikli', 35, 'Fedezd fel Budapest nevezetességeit két keréken egy vezetett biciklitúra során. Az útvonal magában foglalja a Parlamentet, a Budai Várat, a Duna partot és több ikonikus helyszínt. A túra során helyi történeteket és érdekességeket is hallhatsz a város múltjáról. A bicikli lehetőséget ad arra, hogy több látnivalót fedezz fel rövidebb idő alatt. Kényelmes tempó, ideális kezdőknek és városi felfedezőknek egyaránt. '),
(34, 'hu', 3, 7, 'Budapesti gasztro piac kóstoló', 'budapest_gasztro_piac', 30, 'Látogasd meg Budapest híres Nagy Vásárcsarnokát, ahol a helyi termékek, sajtok és élelmiszerek kavalkádja vár. A piac tetején már éttermek is találhatók, ahol tradicionális magyar ételeket kóstolhatsz. Ismerd meg a helyi konyhaművészetet, valamint a tradicionális magyar ízeket. A piac környékén sétálva további helyi éttermeket és kávézókat fedezhetsz fel. Ideális gasztro élmény egy városnéző nap után. '),
(35, 'hu', 6, 16, 'Berlin Múzeum-sziget nap', 'berlin_museum_sziget', 60, 'Berlin híres Múzeum‑szigete világhírű gyűjteményekkel vár minden művészet és történelem iránt érdeklődőt. Több ikonikus múzeumot foglal magában, amelyekben műkincsek és történeti kiállítások találhatók. A helyszín egy UNESCO világarvasi terület része, így a látogatás akár egész napos program is lehet. A gyűjtemények között ókori és modern alkotások is megtalálhatók. A környék kávézóival és parkjaival együtt kiváló kulturális élmény vár. '),
(36, 'hu', 6, 16, 'Berlin street art séta', 'berlin_street_art', 40, 'Fedezd fel Berlin alternatív arcát egy vezetett street art sétán keresztül, ahol a város híres falfestményeit és graffiti kultúráját ismerheted meg. A túra során helyi művészek munkáin keresztül bepillantást nyerhetsz a kortárs berlini kultúrába. A séta olyan kerületeket is érint, ahol a kreatív közösségek és kávézók találhatók. A program interaktív és inspiráló élmény minden művészet iránt érdeklődő számára. A túra után érdemes helyi kávézóban pihenni. '),
(37, 'hu', 2, 4, 'Római Fórum és Palatinus', 'roma_forum', 50, 'Látogasd meg Róma ókori világának szívét, ahol a Fórum és a Palatinus domb maradványai várják a látogatókat. Ezek a helyszínek az ókori Róma politikai és társadalmi életének központjai voltak. A séták során megismerheted az ókori építészet és kultúra lenyűgöző részleteit. A helyszín panorámás kilátást is kínál a városra. Történelmi és kulturális élmény egyben. '),
(38, 'hu', 2, 6, 'Nápolyi tengerpart esti program', 'napoly_tengerpart', 45, 'Élvezd Nápoly tengerpartjának esti hangulatát, ahol éttermek, bárok és sétányok várnak a látogatókat. A tengerpart menti sétány különleges mediterrán hangulatot ad a városnézéshez. A naplemente látványa a Vezúv felé lenyűgöző. A környék tele van gelato bárokkal és helyi pizzériákkal, amelyek autentikus pizzát kínálnak. Ez az élmény ideális romantikus vacsora vagy baráti est programnak. '),
(39, 'hu', 2, 5, 'Milánó divatnap', 'milano_divatnap', 50, 'Látogasd meg Milánó híres divatnegyedét, ahol a világ márkái és elegáns üzletek sorakoznak egymás mellett. Ez az élmény lehetőséget kínál arra, hogy betekintést nyerj a világ divatkultúrájába. A Dóm tér és a Galleria Vittorio Emanuele II közelsége kiegészíti a programot ikonikus építészeti látványokkal. A séta után egy olasz kávézó ideális hely a pihenéshez. Ez a nap tökéletes program divatszeretőknek és stílusos városnézőknek. '),
(40, 'hu', 8, 22, 'Athén ókori kikötő és agora', 'athen_agora', 50, 'Fedezd fel Athén ókori kikötőjét és az agorát, ahol az ókor életének központjai zajlottak. A helyszín tele van történelmi romokkal, és életre kelti a görög mitológia történeteit. Az agora közösségi tere mindig pezsgő volt az üzlettel és beszélgetéssel. Ma múzeumok és kiállítások egészítik ki az élményt. A program ideális történelem iránt érdeklődőknek. '),
(41, 'hu', 8, 24, 'Rodosz óvárosi séta', 'rodosz_ovaros', 45, 'Fedezze fel Rodosz óvárosát, mely UNESCO világhagyaték része történelmi falakkal, keskeny utcákkal és gazdag múzeumi kiállításokkal. A séta során a középkori utcakép és a lovagvár maradványai különleges hangulatot adnak. A környező parkok és kávézók ideálisak pihenéshez. A helyi piacok különleges helyi termékeket kínálnak. Ez az élmény remek kombinációja a történelemnek és a pihenésnek. '),
(42, 'hu', 19, 55, 'Stockholm vízi túra', 'stockholm_vizi', 50, 'Látogasd meg Stockholm híres vízi útjait hajóval, ahol a város különleges szigetei és épületei a vízről is lenyűgöző látványt nyújtanak. A hajóút során a történelmi és modern részletek együtt alkotnak felejthetetlen panorámát. A túra ideális családoknak és barátoknak egyaránt. A kikötők mentén éttermek és kávézók kínálnak helyi finomságokat. A vízi kaland egy egész napos programhoz is kiváló kiegészítő. '),
(43, 'hu', 19, 56, 'Malmö design séta', 'malmo_design', 40, 'Fedezd fel Malmö modern építészetét és design negyedét, ahol a város letisztult stílusú terekkel és kreatív terekkel vár. A séta során kortárs művészeti létesítmények és üzletek is találhatók. A városi parkok és terek ideális helyet kínálnak egy pihentető naphoz. A helyi kávézók különleges ízeket kínálnak. Ez az élmény kombinálja a kreativitást és városnézést. '),
(44, 'hu', 20, 58, 'Oslo fjord naplemente túra', 'oslo_naplemente', 60, 'Fedezd fel Oslo híres fjordját egy hajókirándulással naplemente idején, ahol a táj és a tenger találkozása különleges hangulatot ad a túrának. A fjord mentén a norvég természet csodálatos látványa tárul fel, miközben a város panorámája is kivehető. A program ideális romantikus esti programnak vagy családi kirándulásnak. A fedélzeten kávé és helyi harapnivalók is fogyaszthatók. Ez egy izgalmas kombinációja a természeti és városi élményeknek. '),
(45, 'hu', 21, 61, 'Helsinki múzeumi nap', 'helsinki_muzeum', 40, 'Látogasd meg Helsinki művészeti és történelmi múzeumait, ahol a finn kultúra és történelem gazdag gyűjteménye várja a látogatókat. A múzeumok közel vannak egymáshoz, így könnyen teljes napot tölthetsz velük. A kiállítások interaktív elemeket és helytörténeti részleteket is tartalmaznak. A múzeumi nap kiegészíthető egy tengerparti sétával vagy helyi kávézók meglátogatásával. Ideális program rossz idő esetén is. '),
(46, 'hu', 22, 64, 'Varsói történelmi múzeum', 'varso_tortenelem', 35, 'Látogasd meg Varsó történelmi múzeumát, ahol a lengyel főváros és környékének gazdag történetét ismerheted meg. A kiállítások részletesen bemutatják a város fejlődését a középkortól napjainkig. A múzeum belső tere modern és interaktív. A környéken sétálva könnyen meglátogathatók további történelmi helyszínek. A program ideális történelem iránt érdeklődők számára. '),
(47, 'hu', 3, 7, 'Budapesti Lánchíd esti séta', 'budapest_lanchid', 30, 'Sétálj át a világhírű Széchenyi Lánchídon, amely a Duna két partját, Budát és Pestet köti össze. Ez az egyik legismertebb budapesti ikon, amely este különösen hangulatos a kivilágított várossal és folyóparttal. A híd története az 1840‑es évekre nyúlik vissza, és ma a város szimbólumaként is szolgál. Sétálj végig rajta, miközben csodálod a város panorámáját és a város fő látványosságait. A környék tele van éttermekkel és kávézókkal egy kellemes esti programhoz. '),
(48, 'hu', 3, 7, 'Budai Vár és Királyi Palota', 'budai_var_palota', 55, 'Látogass el a történelmi Budai Várba, ahol a Királyi Palota és a várnegyed gazdag történelmi emlékeket kínál. A komplexum részét képezi a Magyar Nemzeti Galéria és a Budapesti Történeti Múzeum is. A vár teraszairól csodás kilátás nyílik a Dunára és Pest városrészére. A helyszín UNESCO világörökségi része, így kulturális és történelmi élmény egyaránt. Fedezd fel a középkori és barokk kori építészetet, valamint sétálj a vár falai mentén. '),
(49, 'hu', 3, 7, 'Szent István‑bazilika & kilátó', 'budapest_bazilika', 40, 'Ismerd meg Budapest harmadik legnagyobb templomát, a Szent István‑bazilikát, amely egyben az egyik legszebb neoklasszikus épület is. A bazilika belsejében megtekinthető Magyarország első királyának, Szent Istvánnak a jobb keze is. A torony kilátójából 360°‑os panoráma nyílik a városra, különösen naplementekor látványos. A templom rendszeresen ad organikus koncerteket, amelyek hangulatát érdemes átélni. Ez a helyszín történelmi és spirituális élményt egyaránt kínál. :contentReference[oaicite:1]{index=1}'),
(50, 'hu', 3, 7, 'Memento Park szabadtéri múzeum', 'budapest_memento_park', 35, 'Fedezd fel Budapest egyik egyedi múzeumát, a Memento Parkot, ahol a kommunizmus idején állított szobrok és emlékművek várnak szabadtéri kiállítással. A park egy történelmi időszakot idéz meg, amikor a szocialista rendszer emlékeit gyűjtötték itt össze. Látogasd meg az impozáns Lenin‑ és Marx‑szobrokat is, amelyek a múlt erejét és a demokrácia jelentőségét emelik ki. A hely interaktív módon mutatja be az elmúlt korszak társadalmi történetét. Ideális program történelem iránt érdeklődők számára. :contentReference[oaicite:2]{index=2}'),
(51, 'hu', 3, 7, 'Gellért‑hegyi barlang & kilátás', 'budapest_gellert-barlang', 30, 'Látogasd meg a Gellért‑hegy barlangját, amely egy természetes barlangrendszer a város egyik legszebb panorámájú pontján. A barlang történelme egy hermita legendájához kötődik, ahol a természet gyógyító erejét is megismerheted. A hegy tetejéről csodás kilátás nyílik a Duna folyóra és a városra. A barlang mellett a Gellért fürdő és a hegy környéke is remek pihenési lehetőséget kínál. A kirándulás kombinálja a természetet, történelmet és városi panorámát. :contentReference[oaicite:3]{index=3}'),
(52, 'hu', 3, 8, 'Szegedi Dóm tér koncert & séta', 'szeged_dom_esti', 25, 'Látogass el a szegedi Dóm térre egy esti sétára és koncertre, ahol a város híres főtere különleges hangulatot kínál. A monumentális katedrális és a környék építészete egyedülálló látványt nyújt. Sokszor rendeznek klasszikus és könnyűzenei esteket a téren vagy a közelben található színpadokon. A program során élvezheted a város építészeti szépségét és a helyi kulturális életet. A tér mentén hangulatos kávézók és éttermek is várnak. '),
(53, 'hu', 3, 9, 'Debreceni Nagyerdei Élménypark', 'debrecen_nagyerdei', 30, 'Fedezd fel Debrecen zöld szívét, a Nagyerdőt, ahol szabadtéri programok és élménypark is várja a látogatókat. A parkban sétálva rengeteg pihenőhely és kulturális esemény kínálkozik. Gyermekbarát játékok és sportlehetőségek teszik különlegessé a helyet. A Nagyerdőben gyakran rendeznek zenei eseményeket és kulturális vásárokat is. Ideális hely családi vagy baráti kikapcsolódásra. '),
(54, 'hu', 4, 10, 'Louvre esti séta & kiállítás', 'parizs_louvre_esti', 55, 'Sétálj végig a világhírű Louvre Múzeum környezetében Párizsban, ahol a múzeum épülete és kertjei már önmagukban műalkotások. A világ egyik legnagyobb és leggazdagabb művészeti gyűjteménye itt található, mely festmények és szobrok sokaságát foglalja magában. Az esti kivilágítás különleges hangulatot ad a környéknek. A környező kávézók és teraszok ideális helyszínt kínálnak pihenéshez. A séta történelmi és kulturális élményt nyújt egyaránt. '),
(55, 'hu', 4, 10, 'Montmartre művészeti séta', 'parizs_montmartre', 45, 'Fedezd fel Montmartre dombjának művészeti negyedét, ahol festőművészek, galériák és hangulatos utcák várják a látogatót. A hely különleges bohém atmoszférát áraszt, és a Sacré‑Cœur bazilika panorámát nyújt Párizsra. Éttermek, kávézók és kis butikok teszik teljessé az élményt. A séta során megismerheted a város művészeti történelmét és jelenlegi kreatív életét. Ideális napközbeni vagy esti programnak. '),
(56, 'hu', 6, 16, 'Berlin Brandenburgi kapu esti fotózás', 'berlin_brandenburg', 35, 'Látogasd meg Berlin híres Brandenburgi kapuját egy esti séta során, amikor a kivilágított emlékmű különösen impozáns látványt nyújt. Ez a kapu a város egyik legismertebb szimbóluma, amely a német történelem fontos pontjait idézi fel. A környéken számos étterem és bár is található, ahol kikapcsolódhatsz. A fotózás mellett hallhatsz történeteket is a hely történelméről egy vezetett sétán. Berlin dinamikus hangulata minden időszakban érezhető. '),
(57, 'hu', 6, 16, 'Berlin panoráma kilátó', 'berlin_panorama_kilato', 40, 'Fedezd fel Berlin legjobb panorámáját egy modern kilátóteraszról, ahonnan egész városra ráláthatsz. A kilátó arról híres, hogy naplemente idején egészen különleges fényeket ad a város látképének. A program kombinálja a városnézést és fotózást, miközben megismerheted Berlin sokszínű építészetét. A kilátó környéke üzletekkel és kávézókkal is várja a látogatókat. Ideális fiataloknak és családoknak egyaránt. '),
(58, 'hu', 2, 4, 'Római Pantheon látogatás', 'roma_pantheon', 40, 'Látogasd meg Rómában a Pantheont, az ókori római építészet egyik legjobban megőrzött művét. Az épület kupolája különleges akusztikát és fényhatásokat kínál. A belső térben több történelmi síremlék is található. A Pantheon az építészeti kiválóság és az ókori kultúra emlékműve. A környék éttermei és kávézói teszik teljessé a látogatást. '),
(59, 'hu', 2, 6, 'Nápoly & Vezúv panoráma túra', 'napoly_vezuv', 50, 'Fedezd fel Nápoly városát és környékét egy panorámás túrán keresztül, ahol a híres Vezúv tűzhányóra is kilátást kapsz. A környék mediterrán hangulata és a tengerpart közelsége teszi különlegessé a programot. A túra során látogass el történelmi helyszínekhez és kilátóponthoz is. A Vezúv környéki kilátás különösen naplementekor lenyűgöző. A nap túrával és tengerparti pihenéssel egészíthető ki. '),
(60, 'hu', 2, 5, 'Milánói dóm templom', 'milano_dom', 45, 'Látogasd meg Milánó egyik legismertebb nevezetességét, a milánói dómot, amely egy hatalmas gótikus stílusú katedrális. A tetőteraszra felmenve fantasztikus kilátás nyílik a városra és a környező tájakra. A templom belső díszítése és szobrai egyaránt lenyűgözők. A környéken rengeteg kávézó és kis üzlet várja a látogatókat. Ez az élmény mind történelmi, mind kulturális szempontból emlékezetes. '),
(61, 'hu', 8, 22, 'Athéni ókori múzeum', 'athen_muzeum', 45, 'Látogasd meg Athén egyik legismertebb múzeumát, ahol az ókori görög kultúra gazdag tárgyi emlékei várják. A kiállított tárgyak részletesen bemutatják az ókor mindennapi életét és művészetét. A múzeum közelében éttermek és kávézók találhatók, így a látogatás könnyen kombinálható egy hosszabb sétával is. Ideális program művelődni vágyóknak. '),
(62, 'hu', 8, 24, 'Rodoszi vízi sport nap', 'rodosz_vizi_sport', 50, 'Élvezd Rodosz szigetén a vízi sportok kínálta izgalmakat, ahol jet ski, szörf és egyéb vizes programok várnak. A kristálytiszta tenger és a part közelsége ideális feltételeket biztosít minden korosztálynak. A program során helyi oktatók segítenek a biztonságos részvételben. A vízi sportok után pihenhetsz a parton, vagy egy helyi taverna teraszán. Ez a nap aktív pihenést kínál a tengerparti élményhez. '),
(63, 'hu', 19, 55, 'Stockholmi múzeum túra', 'stockholm_muzeum', 50, 'Fedezd fel Stockholm kulturális életét egy múzeumi és galéria túrán keresztül, ahol modern és klasszikus művészetek is várnak. A város múzeumai széles gyűjteményeket tartalmaznak több stílusban is. A túra során lehetőséged nyílik interaktív és történelmi kiállítások megtekintésére. A program ideális kültéri sétával is kombinálható. A város part menti közelsége különleges hangulatot ad az egész napos programnak. '),
(64, 'hu', 19, 56, 'Malmö éjszakai városnézés', 'malmo_ejszakai', 35, 'Fedezd fel Malmö éjszakai életét és városnézését egy esti sétán keresztül, ahol a város modern épületei, fények és kávézók különleges hangulatot kínálnak. Az éjszakai séta során a város főtere és parkjai kivilágítva még varázslatosabbak. Találj helyi éttermeket ebben a hangulatban. Ez egy kellemes esti program a városi kultúra felfedezésére. '),
(65, 'hu', 20, 58, 'Oslo Opera & fjord panoráma', 'oslo_opera_fjord', 60, 'Látogasd meg az Oslo ikonikus Operaházát, amely modern építészetével lenyűgöz és egyben panorámás kilátást kínál a fjordra. A tetőtérre felmenve csodás kilátás nyílik a fjord és a város felett. A program során sétálj a vízparti sétányok mentén is. Az opera előtti területek tökéletesek egy piknikezéshez vagy naplemente élményhez. Ez az élmény kombinálja a modern építészetet és a természeti panorámát. '),
(66, 'hu', 21, 61, 'Helsinki tengerparti séta', 'helsinki_tengerpart', 40, 'Fedezd fel Helsinki tengerparti sétányait, ahol a tengeri levegő és parkosított sétautak ideális feltételeket kínálnak a pihenéshez és a látványhoz. A vízparti sétány mentén kis éttermek és kávézók találhatók, ahol helyi specialitásokat kóstolhatsz. Ez egy kellemes napközbeni program, amely ötvözi a természetet és a városi élményt. '),
(67, 'hu', 22, 64, 'Varsói gasztro & városnézés', 'varso_gasztro', 35, 'Fedezd fel Varsó történelmi központját egy gasztro és városnéző programmal, ahol helyi éttermek, ételkóstolók és séták váltják egymást. A város történelmi tereit és parkjait is érintheted. A program során megismerheted a lengyel konyha különlegességeit és a helyi piacokat. Ez az élmény ideális kombinációja a kulináris és városi felfedezésnek. '),
(68, 'hu', 19, 55, 'Stockholmi Gamla Stan óvárosi séta', 'stockholm_gamla_stan', 45, 'Fedezd fel Stockholm történelmi óvárosát, Gamla Stan‑t, ahol kanyargó, macskaköves utcák és régi épületek találkoznak a modern városi élettel. A terület a 13. század óta játszik központi szerepet a svéd főváros építészetében és történetében, és számos ikonikus épületet foglal magába, mint a Nobel Múzeum és a Királyi Palota. Sétálj végig a Stortorget főtéren, nézd meg a régi árkádos házakat, majd kóstolj helyi svéd specialitásokat a hangulatos kávézók egyikében. Ez az élmény kombinálja a történelmet, kultúrát és a városi hangulatot egyaránt. :contentReference[oaicite:1]{index=1}'),
(69, 'hu', 19, 55, 'Stockholmi modern múzeum túra', 'stockholm_modern_muzeum', 50, 'Látogasd meg Stockholm izgalmas modern múzeumait, ahol kortárs művészeti és technikai kiállítások várnak. A város kulturális kínálata számos gyűjteményből áll, melyek között történeti, modern és interaktív kiállítások is szerepelnek. A múzeumok közötti séta jól kombinálható egy kikötői panorámaúttal vagy városi gasztro kóstolóval. Ez a program ideális városi kulturális kaland mindenkinek. '),
(70, 'hu', 19, 56, 'Malmö múzeumi és történelmi kastély látogatás', 'malmo_muzeum_kastely', 40, 'Fedezd fel Malmö kulturális oldalát a Malmö Múzeumban, amelynek kiállításai a város technikai, történelmi és természeti örökségét mutatják be. A múzeum fő helyszíne a történelmi Malmö Castle komplexum, ahol többek között a régészeti és maritime gyűjtemények is megtalálhatók. A kiállítások mellett sétálj a parkosított kastélykertben és ismerkedj a város történelmével. Malmö izgalmas kombinációja a múlt és jelen kultúrájának. :contentReference[oaicite:2]{index=2}'),
(71, 'hu', 20, 58, 'Oslo fjordparti esti séta', 'oslo_fjordparti_seta', 45, 'Élvezd az Oslo fjord menti sétány nyugodt hangulatát, ahol a tengerpart és a modern városi élet találkozik. A sétány ideális hely egy romantikus estére vagy baráti társasággal eltöltött programra, miközben a város panorámája és a víz közelsége különleges légkört ad a városi kalandnak. A környéken számos étterem és kávézó vár helyi specialitásokkal. Ez a program ötvözi a természeti szépséget és a városi élményt. '),
(72, 'hu', 20, 58, 'Oslo skandináv gasztro túra', 'oslo_gasztro', 50, 'Merülj el az oslói gasztrokultúrában egy helyi ízeket bemutató városi túra során. Kóstold meg a norvég specialitásokat, friss halételeket és tradicionális fogásokat a fjord parti éttermekben. A gasztro túra során helyi piacokat és modernebb bisztrókat is meglátogatsz. Ez a program különleges kombinációja a kulináris élménynek és a városi felfedezésnek. '),
(73, 'hu', 21, 61, 'Helsinki design séta', 'helsinki_design_seta', 40, 'Helsinki az északi design és modern építészet fellegvára, melyet érdemes gyalogosan felfedezni. A város különleges épületei és sztenderd tervezési példái megmutatják a skandináv kreativitást. A séták során megismerheted a helyi design múzeumokat, galériákat és butikokat. Ez a kulturális élmény ötvözi a kreativitást, városi parkokat és tengerparti panorámát is. '),
(74, 'hu', 21, 61, 'Helsinki naplemente hajókirándulás', 'helsinki_hajo', 55, 'Fedezd fel Helsinki tengerparti panorámáját egy naplemente hajókirándulás során, ahol a város látképe a vízről különleges élményt nyújt. A fedélzeti kávézóban helyi harapnivalókat is kóstolhatsz, miközben a lenyugvó nap fényei megvilágítják a kikötőt és a várost. Ez a program romantikus élményként és városi kiruccanásként egyaránt ideális. '),
(75, 'hu', 22, 64, 'Varsói Királyi Kastély és park', 'varso_kiralyi_kastely', 45, 'Látogasd meg a varsói Királyi Kastélyot, ahol a lengyel történelem és királyi élet lenyűgöző emlékei várnak. A kastély gyönyörű termei, díszes szobái és környező parkjai ideális helyszínt biztosítanak egy hosszabb városi sétahoz. A környéken éttermek és kávézók sora található, így könnyen egész napos programot tervezhetsz. Ez az élmény történelmi és kulturális dimenziót ad a városi túrához. '),
(76, 'hu', 22, 64, 'Varsói modern művészet galéria', 'varso_modern_galeria', 40, 'Fedezd fel Varsó vibráló modern művészeti életét egy galéria látogatás során, ahol kortárs lengyel és nemzetközi alkotások várnak. A kiállítások sokszínűsége és kreatív hangulata inspiráló élményt kínál minden művészetkedvelő számára. A környék éttermei és kávézói további kulturális felfedezést tesznek lehetővé. '),
(77, 'hu', 24, 70, 'Pozsonyi Óváros történelmi séta', 'pozsony_ovaros', 35, 'Fedezd fel Pozsony történelmi óvárosát, ahol középkori utcák, hangulatos terek és gazdag építészeti örökség vár. A Fő tér és a régi városháza különleges hangulatot ad az egész napos sétának. Ismerd meg a város történelmét és legendáit egy idegenvezetéssel vagy önállóan. A séta ideális program egy hosszabb városi kiruccanáshoz. :contentReference[oaicite:3]{index=3}'),
(78, 'hu', 24, 70, 'Pozsonyi zenei esték & kulturális program', 'pozsony_zene', 45, 'Vegyél részt egy kulturális estén Pozsonyban, ahol klasszikus zenei koncert vagy helyi jazz est vár. A program kombinálja a helyi zenészek műsorát és a város hangulatos légkörét, ideális esti kikapcsolódásra. Ez az élmény remekül illeszthető vacsorához vagy városnézéshez. '),
(79, 'hu', 23, 69, 'České Budějovice Black Tower kilátó', 'ceske_budejovice_blacktower', 30, 'Látogasd meg České Budějovice történelmi Black Tower kilátóját, amely a város egyik legjellegzetesebb látnivalója. A tornyot a 16. században építették védekező célokra és ma panorámás kilátót kínál a városra. A közeli középkori épületek és hangulatos utcák ideális környezetet adnak a városi felfedezéshez. A kilátóból lenyűgöző panoráma nyílik a város tetejéről. :contentReference[oaicite:4]{index=4}'),
(80, 'hu', 23, 69, 'České Budějovice Iron Maiden Tower', 'ceske_budejovice_ironmaiden', 35, 'Fedezd fel az Iron Maiden tornyot, egy középkori börtön és erődített rész, ahol történelmi fegyverek és kiállítások várnak. A torony egykor a város védelmében szolgált, ma pedig izgalmas kulturális programot kínál a látogatóknak. A környező óváros és kávézók ideális hely egy hosszabb délutáni sétára. :contentReference[oaicite:5]{index=5}'),
(81, 'hu', 23, 68, 'Brno gasztro & városnézés', 'brno_gasztro', 40, 'Fedezd fel Brno hangulatos éttermeit és kávézóit egy helyi gasztro túra során, miközben a város történelmi központját is megismered. A séta során helyi specialitásokat kóstolhatsz, miközben a város történelmi tereit és épületeit is megcsodálod. Ez az élmény ideális gasztronómiai és városi felfedezésre egyaránt. '),
(82, 'hu', 23, 68, 'Brno zenei & rendezvény est', 'brno_zenei_est', 45, 'Vegyél részt egy helyi zenei esten Brnóban, ahol helyi előadók koncertjei és rendezvények várnak a városi kulturális térben. A hangulatos helyszínek és bárok kombinációja ideális esti programot biztosít. Ez a helyi élmény autentikus betekintést ad Brno zenei és kulturális életébe, és felejthetetlen élményt nyújt a látogatóknak.');
