INSERT INTO `translations` (`id`, `language_short_name`, `item_id`, `item_name`, `item`) VALUES
(1, 'de', 1, 'accommodations', '{\r\n  \"title\": \"Gemütliche Wohnung im Herzen von Prag\",\r\n  \"description\": \"Dieses komfortable Apartment im Herzen von Prag erfüllt alle Ansprüche. Die geräumigen Zimmer sind lichtdurchflutet, die Einrichtung ist modern und stilvoll. Ein idealer Ort sowohl für Paare als auch für Familien. Die wichtigsten Sehenswürdigkeiten und Restaurants der Stadt sind nur wenige Gehminuten entfernt. Eine perfekte Wahl für Entspannung und Stadtbesichtigungen.\"\r\n}\r\n'),
(2, 'en', 1, 'accommodations', '{\r\n  \"title\": \"Cozy Apartment in the Heart of Prague\",\r\n  \"description\": \"This comfortable apartment in the heart of Prague meets every need. The spacious rooms are filled with natural light, and the furnishings are modern and stylish. An ideal place for both couples and families. The city\'s main attractions and restaurants are just a few minutes\' walk away. A perfect choice for relaxation and sightseeing.\"\r\n}\r\n'),
(3, 'it', 1, 'accommodations', '{\r\n  \"title\": \"Accogliente appartamento nel cuore di Praga\",\r\n  \"description\": \"Questo confortevole appartamento nel cuore di Praga soddisfa ogni esigenza. Le camere spaziose sono luminose e l’arredamento è moderno ed elegante. È una soluzione ideale sia per coppie che per famiglie. Le principali attrazioni e i ristoranti della città si trovano a pochi minuti a piedi. Una scelta perfetta per il relax e per visitare la città.\"\r\n}\r\n'),
(4, 'ja', 1, 'accommodations', '{\r\n  \"title\": \"プラハ中心部の居心地の良いアパート\",\r\n  \"description\": \"この快適なアパートメントは、プラハの中心部に位置し、あらゆるニーズを満たします。広々とした客室は日当たりが良く、家具はモダンでスタイリッシュです。カップルにもご家族にも理想的な宿泊先です。市内の主要な観光名所やレストランへは徒歩わずか数分でアクセスできます。リラックスや観光に最適な選択です。\"\r\n}\r\n'),
(5, 'sr', 1, 'accommodations', '{\r\n  \"title\": \"Удобан стан у срцу Прага\",\r\n  \"description\": \"Овај удобан апартман у срцу Прага задовољава све потребе. Простране собе су осунчане, а намештај је модеран и стилски уређен. Идеално место како за парове, тако и за породице. Главне знаменитости и ресторани у граду налазе се на само неколико минута хода. Савршен избор за одмор и разгледање града.\"\r\n}\r\n'),
(6, 'it', 15, 'accommodations', '{\"title\":\"Appartamento sul mare\",\"description\":\"Appartamento sul mare proprio accanto alla spiaggia. Interni luminosi e spaziosi, arredati con mobili moderni. Ideale per famiglie o gruppi di amici. La zona è ricca di ristoranti e opportunità di svago. Godetevi una vacanza estiva all\'insegna del relax vicino alla spiaggia.\"}'),
(7, 'ja', 96, 'accommodations', '{\"title\":\"メキシコシティ スタイル アパートメント\",\"description\":\"メキシコシティ中心部にあるモダンで明るいアパートメント。広々としたリビングルーム、快適なベッド。ご家族やカップルに最適です。観光スポットやレストランにも近い。メキシコの都市生活を存分に満喫してください。\"}'),
(8, 'ja', 76, 'accommodations', '{\"title\":\"タンペレ パノラマ アパートメント\",\"description\":\"タンペレ中心部にある広々とした明るいアパートメント。モダンな家具と快適なベッド。ご家族やカップルに最適です。市内の観光スポットやレストランにも近いです。快適なご自宅からフィンランドの都市生活をお楽しみください。\"}'),
(9, 'ja', 75, 'accommodations', '{\"title\":\"ヘルシンキデザインアパートメント\",\"description\":\"ヘルシンキ中心部にある明るくモダンなアパートメント。快適なベッドと広々としたリビングルーム。ご家族やカップルに最適です。レストラン、カフェ、美術館も近くにあります。フィンランドの都市生活を存分にお楽しみください。\"}'),
(10, 'ja', 97, 'accommodations', '{\"title\":\"グアダラハラのデザインアパートメント\",\"description\":\"グアダラハラにある明るくモダンなアパート。快適な家具、設備完備。カップルやビジネス旅行者に最適。レストランや観光スポットも近く。快適な環境でメキシコの都市生活をお楽しみください。\"}'),
(11, 'ja', 98, 'accommodations', '{\"title\":\"モンテレー パノラマ アパートメント\",\"description\":\"モンテレー中心部にある広々とした明るいアパートメント。モダンな家具と快適なベッド。ご家族やご友人グループに最適です。市内の観光スポットやレストランにも近いです。メキシコの都市生活を存分にお楽しみください。\"}'),
(12, 'ja', 23, 'accommodations', '{\"title\":\"山のアパート\",\"description\":\"山のアパート、自然の中でくつろぐのにぴったり。広々として明るく、モダンな家具が置かれています。家族や友達グループに最適。周辺には、小旅行や観光名所がたくさんあります。快適でアットホームな、くつろぎの空間です。\"}'),
(13, 'ja', 43, 'accommodations', '{\"title\":\"ケルンスタイルアパートメント\",\"description\":\"ケルン中心部にある明るくモダンなアパート。快適なベッドと充実した設備。カップルや小さな家族に最適。観光スポットやレストランにも近い。短期滞在に最適な選択肢です。\"}'),
(14, 'ja', 41, 'accommodations', '{\"title\":\"ベルリンのモダンなアパートメント\",\"description\":\"ベルリン中心部にある若々しく明るいアパートメント。快適なベッドと実用的な家具。カップルやビジネス旅行者に最適です。公共交通機関やレストランにも近い。都会の休息にぴったりです。\"}'),
(15, 'ja', 42, 'accommodations', '{\"title\":\"ミュンヘン高級マンション\",\"description\":\"ミュンヘンの中心部にある、エレガントで広々としたアパートメント。モダンな家具と設備の整ったキッチン。ご家族やご友人との滞在に最適です。主要な観光スポットにも近いです。バイエルンの街の雰囲気をお楽しみください。\"}'),
(16, 'ja', 19, 'accommodations', '{\"title\":\"若々しいスタジオ\",\"description\":\"ベルリンにあるモダンな設備を備えた若々しいスタジオ。カップルやビジネス旅行者に最適です。明るく居心地の良いインテリアが快適さを提供します。交通機関や地元の観光スポットにも近い。短期滞在に最適です。\"}'),
(17, 'ja', 77, 'accommodations', '{\"title\":\"オウル・アークティック・アパートメント\",\"description\":\"オウル中心部にある明るくモダンなアパートメント。広々としたリビングルーム、快適なベッド。カップルやご家族に最適です。観光スポットやレストランも近くにあります。フィンランドの都市生活と北欧の雰囲気を、ご自宅のようにくつろぎながらお楽しみください。\"}'),
(18, 'ja', 28, 'accommodations', '{\"title\":\"都心部のアパート\",\"description\":\"ミラノのダウンタウンにある、快適で居心地の良いアパート。明るい室内、設備も整っている。カップルや家族に最適。市内の主要観光スポットや交通機関にも近い。ミラノを探索するのに最適な拠点。\"}'),
(19, 'ja', 40, 'accommodations', '{\"title\":\"ナポリの海辺のアパート\",\"description\":\"ナポリの海岸沿いにある明るく広々としたアパートメント。モダンな家具、設備完備、ご家族に最適です。レストランやビーチも近くにあります。毎日、太陽の光と海のパノラマをお楽しみください。\"}'),
(20, 'ja', 83, 'accommodations', '{\"title\":\"ブラチスラバのエレガントなアパートメント\",\"description\":\"ブダペスト中心部にあるモダンで明るいアパートメント。快適なベッド、広々としたリビングルーム。カップルやご家族に最適です。市内の観光スポットやレストランにも近いです。スロバキアの都市生活の快適さとスタイルをお楽しみください。\"}'),
(21, 'ja', 15, 'accommodations', '{\"title\":\"海辺のアパート\",\"description\":\"ビーチのすぐそばにある海辺のアパート。明るく広々とした室内、モダンな家具。ご家族やご友人グループに最適です。周辺にはレストランやレジャー施設がたくさんあります。海岸近くで、太陽の光あふれる夏の休暇をお楽しみください。\"}'),
(22, 'ja', 20, 'accommodations', '{\"title\":\"家族用住宅\",\"description\":\"ベルリンにある広々としたファミリー向けアパート。モダンな家具と設備の整ったキッチン。大家族に最適。市内の観光スポットや公園にも近い。くつろぎとリラクゼーションに最適な、快適で居心地の良い場所。\"}'),
(23, 'ja', 27, 'accommodations', '{\"title\":\"地中海風アパートメント\",\"description\":\"ローマにある地中海風のアパートメントで、居心地の良いインテリアが魅力。広々として明るく、モダンな家具が備わっています。ご家族やカップルに最適です。市内の観光スポットやレストランにも近い。快適な環境でイタリアのライフスタイルをお楽しみください。\"}'),
(24, 'de', 15, 'accommodations', '{\"title\":\"Apartment am Meer\",\"description\":\"Apartment direkt am Strand. Heller und geräumiger Innenraum mit modernen Möbeln. Ideal für Familien oder Gruppen von Freunden. Die Umgebung bietet zahlreiche Restaurants und Freizeitmöglichkeiten. Genießen Sie einen sonnigen Sommerurlaub in Strandnähe.\"}'),
(25, 'sr', 15, 'accommodations', '{\"title\":\"Апартман на самој обали\",\"description\":\"Апартман на самој обали, одмах поред плаже. Светли и пространи ентеријер са модерним намештајем. Идеалан за породице или групе пријатеља. Подручје је пуно ресторана и могућности за забаву. Уживајте у сунчаном летњем одмору на обали.\"}'),
(26, 'en', 15, 'accommodations', '{\"title\":\"Beachfront apartment\",\"description\":\"Beachfront apartment right next to the beach. Bright and spacious interior with modern furnishings. Ideal for families or groups of friends. The area is full of restaurants and leisure activities. Enjoy a sunny summer break by the coast.\"}'),
(27, 'en', 5, 'accommodations', '{\"title\":\"Cool apartment in Vienna\",\"description\":\"Youthful, comfortable flat in the centre of Vienna, ideal for sightseeing. The bright and practical furnishings meet all needs. Close to public transport and local restaurants. Quiet neighbourhood and comfortable relaxation guaranteed. Perfect choice for groups of friends or couples.\"}'),
(28, 'en', 6, 'accommodations', '{\"title\":\"Pulz Apartment\",\"description\":\"Renovated flat in Szeged, close to the city centre and market. Spacious and bright rooms, modern furnishings. Ideal for families and short stays. The area is full of restaurants and cultural attractions. A comfortable and homely atmosphere awaits guests.\"}'),
(29, 'en', 8, 'accommodations', '{\"title\":\"Downtown apartment\",\"description\":\"A comfortable apartment in the heart of Budapest with a homely atmosphere. The modern furniture and practical layout will satisfy all your needs. Ideal for families or groups of friends. Nearby restaurants, shops and attractions are within easy reach. The perfect place for city experiences and relaxation.\"}'),
(30, 'en', 7, 'accommodations', '{\"title\":\"Downtown, Budapest Szabadság Residence \",\"description\":\"Modern flat in central Budapest, in an excellent location. The flat is bright and well-equipped, ideal for couples or business travellers. The neighbourhood is full of restaurants, cafés and attractions. Convenient access to public transport. The perfect choice for sightseeing and relaxation.\"}'),
(31, 'sr', 6, 'accommodations', '{\"title\":\"Пулз Апартман\",\"description\":\"Реновирани стан у Сегедину, близу центра града и пијаце. Простране и светле собе, модерни намештај. Идеалан за породице и краткотрајне боравке. Околина је пуна ресторана и културних атракција. Госте очекује удобна и пријатна атмосфера.\"}'),
(32, 'sr', 5, 'accommodations', '{\"title\":\"Кул стан у Бечу\",\"description\":\"Младежни, удобан стан у центру Беча, идеалан за разгледање знаменитости. Светла и практична опрема задовољава све потребе. Близу јавног превоза и локалних ресторана. Тихо комшилук и удобно опуштање загарантовано. Савршен избор за групе пријатеља или парове.\"}'),
(33, 'sr', 8, 'accommodations', '{\"title\":\"Стана у центру града\",\"description\":\"Удобан стан у самом срцу Будимпеште са пријатном, домаћом атмосфером. Модеран намештај и практичан распоред задовољиће све ваше потребе. Идеално за породице или групе пријатеља. У близини се налазе ресторани, продавнице и атракције које су лако доступне. Савршено место за градска искуства и опуштање.\"}'),
(34, 'sr', 7, 'accommodations', '{\"title\":\"Центар, Будимпешта Szabadság Residence \",\"description\":\"Модеран стан у централном Будимпешти, на одличној локацији. Стан је светло и добро опремљен, идеалан за парове или пословне путнике. Околина је пуна ресторана, кафића и атракција. Погодан приступ јавном превозу. Савршен избор за разгледање града и опуштање.\"}'),
(35, 'de', 5, 'accommodations', '{\"title\":\"Cool apartment in Vienna\",\"description\":\"Jugendliche, komfortable Wohnung im Zentrum von Wien, ideal für Stadtbesichtigungen. Die helle und praktische Einrichtung erfüllt alle Bedürfnisse. In der Nähe von öffentlichen Verkehrsmitteln und lokalen Restaurants. Ruhige Umgebung und komfortable Erholung garantiert. Die perfekte Wahl für Freundesgruppen oder Paare.\"}'),
(36, 'de', 8, 'accommodations', '{\"title\":\"Apartment in der Innenstadt\",\"description\":\"Komfortables Apartment im Herzen von Budapest mit gemütlicher Atmosphäre. Die moderne Einrichtung und die praktische Aufteilung lassen keine Wünsche offen. Ideal für Familien oder Gruppen von Freunden. Restaurants, Geschäfte und Sehenswürdigkeiten in der Nähe sind leicht zu erreichen. Der perfekte Ort für Stadtbesichtigungen und Entspannung.\"}'),
(37, 'de', 6, 'accommodations', '{\"title\":\"Pulz Apartment\",\"description\":\"Renovierte Ferienwohnung in Szeged, nahe der Innenstadt und dem Markt. Geräumige und helle Zimmer, moderne Einrichtung. Ideal für Familien und Kurzaufenthalte. Die Umgebung ist reich an Restaurants und kulturellen Sehenswürdigkeiten. Es erwartet Sie eine gemütliche und heimelige Atmosphäre.\"}'),
(38, 'de', 7, 'accommodations', '{\"title\":\"Innenstadt, Budapest Szabadság Residenz \",\"description\":\"Moderne Wohnung im Zentrum von Budapest in ausgezeichneter Lage. Die Wohnung ist hell, gut ausgestattet und ideal für Paare oder Geschäftsreisende. Die Umgebung ist reich an Restaurants, Cafés und Sehenswürdigkeiten. Bequemer Zugang zu öffentlichen Verkehrsmitteln. Die perfekte Wahl für Sightseeing und Entspannung.\"}'),
(39, 'en', 51, 'accommodations', '{\"title\":\"Barcelona Beachfront Apartment\",\"description\":\"Spacious apartment in the centre of Barcelona, close to the seafront. Modern furnishings and fully equipped. Ideal for families and friends. Close to attractions and restaurants. Enjoy Catalan city life and relaxation by the sea.\"}'),
