(88, 'en', 34, 'accommodations', '{\"title\":\"České Budějovice Luxury Apartment\",\"description\":\"Elegant, modern apartment in the centre of České Budějovice. Spacious living room, well-equipped kitchen and comfortable bedroom. Ideal for families or groups of friends. Close to the city\'s main attractions. Enjoy every moment of Czech city life.\"}'),
(89, 'en', 81, 'accommodations', '{\"title\":\"Modern Apartment in Brno\",\"description\":\"Spacious, bright apartment in the centre of Brno. Modern furnishings and comfortable beds. Ideal for couples and families. Close to city attractions and restaurants. Enjoy every moment of Czech city life.\"}'),
(90, 'en', 82, 'accommodations', '{\"title\":\"České Budějovice Napfény Apartment\",\"description\":\"Bright, spacious flat in the centre of České Budějovice. Modern furnishings, comfortable beds. Ideal for families and couples. Close to local attractions and restaurants. Enjoy every moment of Czech city life.\"}'),
