(112, 'en', 44, 'accommodations', '{\"title\":\"Viennese Elegance Apartment\",\"description\":\"Spacious, elegant apartment in the centre of Vienna. Modern furniture and comfortable beds. Ideal for couples and business travellers. Close to sights, restaurants and cafés. Enjoy every moment of life in Vienna.\"}'),
(113, 'en', 13, 'accommodations', '{\"title\":\"Apartment in Vienna city centre\",\"description\":\"Elegant flat in the centre of Vienna, close to attractions. The spacious and bright interior is ideal for families and couples. Modern furniture and all necessary equipment. Restaurants and cafés within walking distance. Convenient starting point for exploring the city.\"}'),
(114, 'en', 46, 'accommodations', '{\"title\":\"Salzburg Historic Apartment\",\"description\":\"Stylish flat in Salzburg\'s historic city centre. Bright living room, comfortable beds and well-equipped kitchen. Ideal for couples and small families. Within walking distance of the main attractions. Enjoy the atmosphere of this historic city.\"}'),
(115, 'en', 14, 'accommodations', '{\"title\":\"Compact studio\",\"description\":\"Compact studio in Vienna, ideal for short stays. The practical layout and bright interior meet all requirements. Close to the city\'s main attractions and transport links. Perfect for couples or solo travellers. A comfortable and homely atmosphere awaits guests.\"}'),
(116, 'en', 4, 'accommodations', '{\"title\":\"Charming studio in a central location\",\"description\":\"Stylish, quiet studio in Vienna with all necessary amenities. The modern interior provides a pleasant atmosphere for relaxation. Ideal for couples and short city breaks. The city\'s sights and restaurants are within easy reach. The perfect base for exploring Vienna.\"}'),
(117, 'en', 75, 'accommodations', '{\"title\":\"Helsinki Design Apartment\",\"description\":\"Bright, modern apartment in central Helsinki. Comfortable beds and spacious living room. Ideal for families and couples. Close to restaurants, cafés and museums. Enjoy every moment of Finnish city life.\"}'),
(118, 'en', 77, 'accommodations', '{\"title\":\"Oulu Arctic Apartment\",\"description\":\"Bright, modern apartment in the centre of Oulu. Spacious living room, comfortable beds. Ideal for couples and families. Close to attractions and restaurants. Enjoy Finnish city life and the northern atmosphere in your own home.\"}'),
(119, 'en', 76, 'accommodations', '{\"title\":\"Tampere Panorama Apartment\",\"description\":\"Spacious and bright apartment in the centre of Tampere. Modern furnishings and comfortable beds. Ideal for families and couples. Close to the city\'s attractions and restaurants. Enjoy Finnish city life from the comfort of your own home.\"}'),
(120, 'en', 23, 'accommodations', '{\"title\":\"Mountain apartment\",\"description\":\"Mountain apartment for relaxation close to nature. Spacious and bright, with modern furnishings. Ideal for families and groups of friends. The area is full of excursion opportunities and attractions. A comfortable and cosy place to relax.\"}'),
(121, 'en', 72, 'accommodations', '{\"title\":\"Oslo Modern Apartment\",\"description\":\"Bright, spacious apartment in the centre of Oslo. Modern furnishings, comfortable beds and fully equipped. Ideal for families and couples. Close to attractions and restaurants. Enjoy every moment of Norwegian city life.\"}'),
