(123, 'en', 73, 'accommodations', '{\"title\":\"Bergen Fjord Apartment\",\"description\":\"Spacious, bright apartment in the historic part of Bergen. Modern furnishings and comfortable beds. Ideal for couples and families. Close to city attractions and restaurants. Enjoy the view of the fjords and Norwegian city life.\"}'),
(124, 'en', 73, 'accommodations', '{\"title\":\"Bergen Fjord Apartment\",\"description\":\"Spacious, bright apartment in the historic part of Bergen. Modern furnishings and comfortable beds. Ideal for couples and families. Close to city attractions and restaurants. Enjoy the view of the fjords and Norwegian city life.\"}'),
(125, 'en', 56, 'accommodations', '{\"title\":\"Luxury Apartment in Paris\",\"description\":\"Elegant, bright apartment in the centre of Paris. Modern furniture, fully equipped. Ideal for couples and families. Close to major attractions, restaurants and cafés. Enjoy the romantic French atmosphere every moment.\"}'),
(126, 'en', 74, 'accommodations', '{\"title\":\"Tromsø Arctic Studio\",\"description\":\"Modern studio in the centre of Tromsø. Comfortable bed, bright interior. Ideal for couples and solo travellers. Close to city attractions and restaurants. Enjoy the magic of the Northern Lights from your own studio.\"}'),
(127, 'en', 72, 'accommodations', '{\"title\":\"Oslo Modern Apartment\",\"description\":\"Bright, spacious apartment in the centre of Oslo. Modern furnishings, comfortable beds and fully equipped. Ideal for families and couples. Close to attractions and restaurants. Enjoy every moment of Norwegian city life.\"}'),
(128, 'en', 57, 'accommodations', '{\"title\":\"Lyon Style Apartment\",\"description\":\"Bright, modern apartment in the centre of Lyon. Comfortable beds, fully equipped. Ideal for couples and business travellers. Close to restaurants and attractions. Enjoy every moment of French city life.\"}'),
(129, 'en', 58, 'accommodations', '{\"title\":\"Marseille Seaside Apartment\",\"description\":\"Spacious, bright apartment in Marseille, close to the seafront. Modern furnishings, comfortable beds and fully equipped. Ideal for families and groups of friends. Close to restaurants and attractions. Enjoy Mediterranean life every moment.\"}'),
(130, 'en', 17, 'accommodations', '{\"title\":\"Romantic flat\",\"description\":\"Romantic apartment in Paris, in an excellent location. The interiors are elegant, stylish and cosy. Ideal for couples on a romantic getaway. The neighbourhood is full of restaurants, cafés and attractions. Enjoy every moment of the Parisian atmosphere.\"}'),
(131, 'en', 18, 'accommodations', '{\"title\":\"Apartment with balcony\",\"description\":\"Bright apartment with a balcony in Paris. Modern furnishings and a comfortable layout will satisfy all your needs. Ideal for families and groups of friends. Close to the city\'s main attractions. Enjoy the fresh air and city views from the private balcony.\"}'),
(132, 'en', 17, 'accommodations', '{\"title\":\"Romantic flat\",\"description\":\"Romantic apartment in Paris, in an excellent location. The interiors are elegant, stylish and cosy. Ideal for couples on a romantic getaway. The neighbourhood is full of restaurants, cafés and attractions. Enjoy every moment of the Parisian atmosphere.\"}'),
(133, 'en', 18, 'accommodations', '{\"title\":\"Apartment with balcony\",\"description\":\"Bright apartment with a balcony in Paris. Modern furnishings and a comfortable layout will satisfy all your needs. Ideal for families and groups of friends. Close to the city\'s main attractions. Enjoy the fresh air and city views from the private balcony.\"}'),
(134, 'en', 56, 'accommodations', '{\"title\":\"Luxury Apartment in Paris\",\"description\":\"Elegant, bright apartment in the centre of Paris. Modern furniture, fully equipped. Ideal for couples and families. Close to major attractions, restaurants and cafés. Enjoy the romantic French atmosphere every moment.\"}'),
(135, 'en', 72, 'accommodations', '{\"title\":\"Oslo Modern Apartment\",\"description\":\"Bright, spacious apartment in the centre of Oslo. Modern furnishings, comfortable beds and fully equipped. Ideal for families and couples. Close to attractions and restaurants. Enjoy every moment of Norwegian city life.\"}'),
(136, 'sr', 57, 'accommodations', '{\"title\":\"Стана у лионском стилу\",\"description\":\"Светли, модерни апартман у центру Лиона. Удобни кревети, потпуно опремљен. Идеалан за парове и пословне путнике. У близини ресторана и атракција. Уживајте у сваком тренутку француског градског живота.\"}'),
(137, 'sr', 72, 'accommodations', '{\"title\":\"Модеран стан у Ослу\",\"description\":\"Светли, пространи стан у центру Осла. Модеран намештај, удобни кревети и потпуно опремљен. Идеалан за породице и парове. У близини атракција и ресторана. Уживајте у сваком тренутку градског живота у Норвешкој.\"}'),
(138, 'sr', 58, 'accommodations', '{\"title\":\"Станови на обали Марсеја\",\"description\":\"Простран, светли стан у Марсеју, близу приобаља. Модеран намештај, удобни кревети и потпуно опремљен. Идеалан за породице и групе пријатеља. Близу ресторана и атракција. Уживајте у медитеранском животу у сваком тренутку.\"}'),
(139, 'sr', 17, 'accommodations', '{\"title\":\"Романтичан стан\",\"description\":\"Романтичан стан у Паризу, на одличној локацији. Интеријери су елегантни, стилски и пријатни. Идеалан за парове на романтичном одмору. Околина је пуна ресторана, кафића и атракција. Уживајте у сваком тренутку париске атмосфере.\"}'),
(140, 'sr', 18, 'accommodations', '{\"title\":\"Стана са балконом\",\"description\":\"Светли стан са балконом у Паризу. Модеран намештај и удобан распоред задовољиће све ваше потребе. Идеално за породице и групе пријатеља. У близини главних градских атракција. Уживајте у свежем ваздуху и погледу на град са приватног балкона.\"}'),
(141, 'sr', 56, 'accommodations', '{\"title\":\"Луксузни стан у Паризу\",\"description\":\"Елегантан, светли стан у центру Париза. Модеран намештај, потпуно опремљен. Идеалан за парове и породице. У близини главних атракција, ресторана и кафића. Уживајте у романтичној француској атмосфери у сваком тренутку.\"}'),
(142, 'sr', 26, 'accommodations', '{\"title\":\"Градски студио\",\"description\":\"Градски студио у Њујорку, идеалан за пословне путнике. Светли и модерни ентеријер са практичним садржајима. Близу саобраћајних веза и градских атракција. Удобно и пријатно место за кратки боравак.\"}'),
(143, 'sr', 73, 'accommodations', '{\"title\":\"Берген Фјорд Апартман\",\"description\":\"Простран, светли стан у историјском делу Бергена. Модеран намештај и удобни кревети. Идеално за парове и породице. Близу градских атракција и ресторана. Уживајте у погледу на фјордове и норвешки градски живот.\"}'),
(144, 'sr', 74, 'accommodations', '{\"title\":\"Тромсо Арктичко студио\",\"description\":\"Модеран студио у центру Тромсоа. Удобни кревет, светли ентеријер. Идеално за парове и самосталне путнике. У близини градских атракција и ресторана. Уживајте у магији северне светлости из свог студија.\"}'),
(145, 'sr', 25, 'accommodations', '{\"title\":\"Луксузни апартман\",\"description\":\"Луксузан стан у Њујорку са премиум погодностима. Простран и елегантан ентеријер са удобним намештајем. Идеалан за породице и групе пријатеља. Близу градских атракција. Уживајте у премиум опуштању у срцу метрополе.\"}'),
(146, 'sr', 63, 'accommodations', '{\"title\":\"Модеран стан у Лос Анђелесу\",\"description\":\"Светли и стилски апартман у самом центру Лос Анђелеса. Удобни кревети и модерни намештај. Идеално за парове и пословне путнике. У близини атракција и плажа. Уживајте у калифорнијском начину живота у сваком тренутку.\"}'),
(147, 'sr', 62, 'accommodations', '{\"title\":\"Панорамски стан у Њујорку\",\"description\":\"Простран, светао стан у самом срцу Њујорка. Модеран намештај, удобни кревети и потпуно опремљен. Идеалан за породице и пословне путнике. У близини главних атракција и ресторана. Уживајте у сваком тренутку градског живота.\"}'),
(148, 'sr', 64, 'accommodations', '{\"title\":\"Чикаго Елеганција Апартман\",\"description\":\"Простран, светли стан у самом центру Чикага. Модеран намештај и удобни кревети. Идеалан за породице и пословне путнике. У близини ресторана и атракција. Уживајте у сваком тренутку живота у америчком граду.\"}'),
(149, 'sr', 83, 'accommodations', '{\"title\":\"Елегантан стан у Братислави\",\"description\":\"Модеран, светли стан у центру Братиславе. Удобни кревети, пространи дневни боравак. Идеално за парове и породице. У близини градских атракција и ресторана. Уживајте у удобности и стилу словачkog градског живота.\"}'),
(150, 'sr', 28, 'accommodations', '{\"title\":\"Центар раван\",\"description\":\"Станов у центру Милана, удобан и пријатан. Светли ентеријер, добро опремљен. Идеалан за парове и породице. Близу главних градских атракција и саобраћајних веза. Савршена полазна тачка за истраживање Милана.\"}'),
(151, 'sr', 27, 'accommodations', '{\"title\":\"Медитерански апартман\",\"description\":\"Медитерански стан у Риму са пријатним ентеријером. Простран и светао, са модерним намештајем. Идеалан за породице и парове. Близу градских атракција и ресторана. Уживајте у италијанском стилу живота у удобном окружењу.\"}'),
(152, 'sr', 68, 'accommodations', '{\"title\":\"Апартман Чикаго Скајлајн\",\"description\":\"Простран стан са панорамским погледом у центру Чикага. Модеран намештај и удобни кревети. Идеално за пословне путнике и породице. У близини ресторана, паркова и атракција. Уживајте у живописном градском животу из удобности свог дома.\"}'),
(153, 'sr', 67, 'accommodations', '{\"title\":\"Апартман Сунчани Лос Анђелес\",\"description\":\"Светли, пространи стан у самом срцу Лос Анђелеса. Модеран намештај, удобни кревети, потпуно опремљен. Идеалан за породице и групе пријатеља. Близу градских атракција и ресторана. Уживајте у калифорнијском начину живота у свом стану.\"}'),
(154, 'sr', 38, 'accommodations', '{\"title\":\"Апартман Романска елеганција\",\"description\":\"Елегантан, светли стан у центру Рима. Модеран намештај, удобни кревети, потпуно опремљен. Идеалан за парове или породице. У близини историјских атракција. Савршен избор за романтичне шетње градом.\"}'),
(155, 'sr', 40, 'accommodations', '{\"title\":\"Апартман на плажи у Напуљу\",\"description\":\"Светли и пространи апартман у приморском делу Напуља. Модеран намештај, потпуно опремљен, идеалан за породице. У близини ресторана и плажа. Уживајте у сунчаним данима и погледу на море сваки дан.\"}'),
(156, 'sr', 39, 'accommodations', '{\"title\":\"Милански стилски апартман\",\"description\":\"Модеран, елегантан стан у самом срцу Милана. Светла и пространа дневна соба, удобне спаваће собе. Идеалан за пословне путнике или парове. У близини саобраћајних веза и модних атракција. Уживајте у живописној атмосфери Милана.\"}'),
(157, 'sr', 96, 'accommodations', '{\"title\":\"Стана у стилу Мексико Ситија\",\"description\":\"Модеран, светли стан у центру Мехика. Пространа дневна соба, удобни кревети. Идеалан за породице и парове. Близу атракција и ресторана. Уживајте у сваком тренутку живота у Мехику.\"}'),
(158, 'sr', 92, 'accommodations', '{\"title\":\"Гуангжу панорамски апартман\",\"description\":\"Простран и светли стан у центру Гуангжоу. Модеран намештај и удобни кревети. Идеалан за породице и пословне путнике. У близини атракција и ресторана. Уживајте у живописној атмосфери града из свог стана.\"}');
INSERT INTO `translations` (`id`, `language_short_name`, `item_id`, `item_name`, `item`) VALUES
(159, 'sr', 90, 'accommodations', '{\"title\":\"Историјски стан у Пекингу\",\"description\":\"Прелеп, прострајан стан у историјској четврти Пекинга. Модеран намештај, удобни кревети. Идеалан за породице и парове. Близу атракција и локалних ресторана. Уживајте у кинеској урбаној култури у удобном окружењу.\"}'),
(160, 'sr', 97, 'accommodations', '{\"title\":\"Дизајнерски апартман у Гвадалахари\",\"description\":\"Светли, модерни стан у Гвадалахари. Удобни намештај, потпуно опремљен. Идеалан за парове и пословне путнике. У близини ресторана и атракција. Уживајте у мексичком градском животу у удобном окружењу.\"}'),
(161, 'sr', 91, 'accommodations', '{\"title\":\"Модеран стан у Шангају\",\"description\":\"Светли, модерни апартман у центру Шангаја. Удобни намештај, простране спаваће собе. Идеално за породице и пријатеље. У близини продавница и ресторана. Уживајте у сваком тренутку живота у овој кинеској метрополи.\"}'),
(162, 'sr', 98, 'accommodations', '{\"title\":\"Панорамски апартман Монтереј\",\"description\":\"Простран, светли стан у центру Монтереја. Модеран намештај и удобни кревети. Идеалан за породице и групе пријатеља. У близини градских атракција и ресторана. Уживајте у сваком тренутку мексичког градског живота.\"}'),
(163, 'sr', 24, 'accommodations', '{\"title\":\"Скандинавски студио\",\"description\":\"Скандинавски студио са чистим дизајном. Савремене погодности и удобан распоред. Идеалан за парове и пословне путнике. Близу градских атракција и ресторана. Практичан и стилски избор за кратки боравак.\"}'),
(164, 'sr', 87, 'accommodations', '{\"title\":\"Сеул Панорама Студио\",\"description\":\"Светли студио у центру Сеула. Модеран намештај, удобан кревет. Идеално за самосталне путнике или парове. Близу метроа и ресторана. Уживајте у живописном градском животу из удобности свог апартмана.\"}'),
(165, 'sr', 88, 'accommodations', '{\"title\":\"Станови на обали Пусана\",\"description\":\"Простран стан у приморском делу Бусана. Светло и модерно намештање, удобни кревети. Идеално за породице и групе пријатеља. У близини плаже и ресторана. Уживајте у приморској атмосфери у центру града.\"}'),
(166, 'sr', 89, 'accommodations', '{\"title\":\"Инцион Бизнис Студио\",\"description\":\"Модеран, практичан студио у центру Инчхона. Удобни кревет, потпуно опремљен. Идеалан за пословне путнике и парове. Близу саобраћајних чворишта и ресторана. Уживајте у погодностима града у свом студију.\"}'),
(167, 'sr', 70, 'accommodations', '{\"title\":\"Простран стан у Малмo\",\"description\":\"Светли и пространи стан у самом срцу Малмеа. Модеран намештај и удобни кревети. Идеалан за породице и пријатеље. У близини градских атракција и ресторана. Уживајте у сваком тренутку шведског градског живота из овог удобног стана.\"}'),
(168, 'sr', 69, 'accommodations', '{\"title\":\"Стокхолм Дизајн Апартман\",\"description\":\"Модеран, светли стан у централном Стокхолму. Удобни кревети, пространи дневни боравак и потпуно опремљена кухиња. Идеално за парове и породице. У близини кафића, ресторана и музеја. Уживајте у удобности и стилу шведског градског живота.\"}'),
(169, 'sr', 71, 'accommodations', '{\"title\":\"Панорамски апартман у Ореброу\",\"description\":\"Простран, сунчан стан у центру Ореброа. Модеран намештај и удобни кревети. Идеалан за породице и парове. Близу атракција и ресторана. Уживајте у погодностима шведског градског живота као код куће.\"}'),
(170, 'sr', 21, 'accommodations', '{\"title\":\"Стана са погледом на море\",\"description\":\"Апартман са погледом на море у мирном окружењу. Простран и светли ентеријер са свим погодностима. Идеалан за парове и породице. Близу плаже и ресторана. Уживајте у мирном одмору на мору.\"}'),
(171, 'sr', 99, 'accommodations', '{\"title\":\"Апартман Лисабонско Сунце\",\"description\":\"Светли, пространи стан у историјском центру Лисабона. Модеран намештај, удобни кревети. Идеалан за породице и парове. У близини атракција и ресторана. Уживајте у сваком тренутку градског живота у Португалији.\"}'),
(172, 'sr', 100, 'accommodations', '{\"title\":\"Апартман Порто Дизајн\",\"description\":\"Стилски, модеран апартман у центру Порта. Удобни кревети, потпуно опремљен. Идеалан за парове и пословне путнике. Близу атракција и ресторана. Уживајте у португалском градском животу у удобном окружењу.\"}'),
(173, 'sr', 30, 'accommodations', '{\"title\":\"Модеран студио\",\"description\":\"Модеран студио у Грчкој, практичан и удобан. Светли ентеријер задовољава све потребе. Идеалан за парове и краткотрајне боравке. Близу локалних атракција и ресторана. Савршен избор за опуштање.\"}'),
(174, 'sr', 47, 'accommodations', '{\"title\":\"Панорамски апартман у Атини\",\"description\":\"Простран и светао стан у самом срцу Атине. Модеран намештај, удобни кревети. Идеалан за парове и породице. У близини античких споменика и ресторана. Уживајте у сваком тренутку медитеранског живота.\"}'),
(175, 'sr', 48, 'accommodations', '{\"title\":\"Модеран стан у Солуну\",\"description\":\"Светли, модерни апартман у Солуну. Удобни кревети, потпуно опремљен. Идеалан за парове и мале породице. Близу градских атракција и ресторана. Уживајте у грчком начину живота у сваком тренутку.\"}'),
(176, 'sr', 19, 'accommodations', '{\"title\":\"Младежни студио\",\"description\":\"Младежнички студио у Берлину са модерним погодностима. Идеалан за парове и пословне путнике. Светли и пријатни ентеријер обезбеђује удобност. Близу саобраћајних веза и локалних атракција. Савршен за краткотрајне боравке.\"}'),
(177, 'sr', 29, 'accommodations', '{\"title\":\"Историјски стан\",\"description\":\"Грчки апартман са историјском атмосфером. Класичан намештај, светло и пространо. Идеалан за породице и групе пријатеља. Близу локалних атракција и ресторана. Уживајте у традиционалном грчком окружењу у удобности.\"}'),
(178, 'sr', 49, 'accommodations', '{\"title\":\"Апартман на самој обали у Родосу\",\"description\":\"Простран стан на острву Родос, близу приобаља. Модеран намештај и удобни кревети. Идеално за породице и групе пријатеља. Близу ресторана и атракција. Уживајте у сунцу и опустите се уз море.\"}'),
(179, 'sr', 20, 'accommodations', '{\"title\":\"Породични стан\",\"description\":\"Простран породични стан у Берлину. Модеран намештај и добро опремљена кухиња. Идеалан за веће породице. Близу градских атракција и паркова. Удобно, пријатно место за опуштање и одмор.\"}'),
(180, 'sr', 43, 'accommodations', '{\"title\":\"Стана у колоњском стилу\",\"description\":\"Светли и модерни стан у центру Келна. Удобни кревети и потпуно опремљен. Идеалан за парове и мале породице. Близу атракција и ресторана. Савршен избор за кратки градски одмор.\"}'),
(181, 'sr', 41, 'accommodations', '{\"title\":\"Модеран стан у Берлину\",\"description\":\"Младaлачки, светли стан у центру Берлина. Удобни кревети и практичан намештај. Идеалан за парове или пословне путнике. Близу јавног превоза и ресторана. Савршен за градски одмор.\"}'),
(182, 'sr', 42, 'accommodations', '{\"title\":\"Луксузан стан у Минхену\",\"description\":\"Елегантан, прострајан апартман у самом срцу Минхена. Модеран намештај и добро опремљена кухиња. Идеалан за породице и пријатеље. У близини главних атракција. Уживајте у атмосфери овог баварског града.\"}'),
(183, 'sr', 52, 'accommodations', '{\"title\":\"Романтичан стан у Севиљи\",\"description\":\"Стилски, светли апартман у историјском делу Севиље. Удобни намештај и добро опремљена кухиња. Идеално за парове и мале породице. У близини главних градских атракција и ресторана. Уживајте у шпанској атмосфери у сваком тренутку.\"}'),
(184, 'sr', 50, 'accommodations', '{\"title\":\"Елегантан стан у Мадриду\",\"description\":\"Светли, стилски стан у центру Мадрида. Модеран намештај и удобни кревети. Идеалан за парове и породице. У близини главних градских атракција и ресторана. Уживајте у сваком тренутку шпанског градског живота.\"}'),
(185, 'sr', 59, 'accommodations', '{\"title\":\"Мадридски елегантан апартман\",\"description\":\"Светли, стилски стан у центру Мадрида. Удобни кревети, модеран намештај. Идеалан за парове и породице. Близу атракција и ресторана. Уживајте у сваком тренутку градског живота у Шпанији.\"}'),
(186, 'sr', 16, 'accommodations', '{\"title\":\"Градски студио\",\"description\":\"Модеран урбани студио у центру Мадрида. Светло и практично, са свим неопходним садржајима. Идеално за парове и пословне путнике. Близу главних атракција и саобраћајних чворишта. Удобan и стилски боравак у граду.\"}'),
(187, 'sr', 60, 'accommodations', '{\"title\":\"Панорамски апартман у Барселони\",\"description\":\"Простран и светли стан у центру Барселоне. Удобни намештај, потпуно опремљен. Идеалан за породице и парове. У близини атракција и ресторана. Уживајте у сваком тренутку медитеранског живота.\"}'),
(188, 'sr', 61, 'accommodations', '{\"title\":\"Романтичан стан у Севиљи\",\"description\":\"Стилски апартман у историјском делу Севиље. Удобно намештен и потпуно опремљен. Идеалан за парове и мале породице. Близу атракција и ресторана. Уживајте у шпанској атмосфери у сваком тренутку.\"}'),
(189, 'sr', 51, 'accommodations', '{\"title\":\"Апартман на плажи у Барселони\",\"description\":\"Простран стан у центру Барселоне, близу приобаља. Модеран намештај и потпуно опремљен. Идеалан за породице и пријатеље. Близу атракција и ресторана. Уживајте у каталонском градском животу и опуштању уз море.\"}'),
(190, 'sr', 3, 'accommodations', '{\"title\":\"Удобан стан у центру\",\"description\":\"Сунчан, пријатан стан у центру Прага. Стана је опремљен модерним намештајем и пружа све основне погодности за удобан боравак. Околина је пуна атракција, кафића и ресторана. Одличне саобраћајне везе, идеалне за свако путовање. Уживајте у сваком тренутку градског живота у овом пријатном стану.\"}'),
(191, 'sr', 77, 'accommodations', '{\"title\":\"Арктички апартман у Оулу\",\"description\":\"Светли, модерни апартман у центру Оулуа. Пространа дневна соба, удобни кревети. Идеално за парове и породице. У близини атракција и ресторана. Уживајте у финском градском животу и северној атмосфери у свом дому.\"}'),
(192, 'sr', 75, 'accommodations', '{\"title\":\"Хелсинки дизајнерски апартман\",\"description\":\"Светли, модерни стан у централном Хелсинкију. Удобни кревети и пространи дневни боравак. Идеално за породице и парове. У близини ресторана, кафића и музеја. Уживајте у сваком тренутку градског живота у Финској.\"}'),
(193, 'sr', 76, 'accommodations', '{\"title\":\"Тампере панорамски апартман\",\"description\":\"Простран и светли стан у центру Тампереа. Модеран намештај и удобни кревети. Идеалан за породице и парове. У близини градских атракција и ресторана. Уживајте у финском градском животу из удобности свог дома.\"}'),
(194, 'sr', 23, 'accommodations', '{\"title\":\"Планински апартман\",\"description\":\"Планински апартман за опуштање у близини природе. Простран и светао, са модерним намештајем. Идеалан за породице и групе пријатеља. Подручје је пуно могућности за излете и атракција. Удобно и пријатно место за опуштање.\"}'),
(195, 'sr', 2, 'accommodations', '{\"title\":\"Удобни студио са балконом\",\"description\":\"Модеран студио са балконом, идеалан за кратки боравак у граду. Светли, пријатни ентеријер пружа сваки комфор. У близини саобраћајних веза и локалних ресторана. Савршено за парове или пословне путнике. Уживајте у градској вреви са свог приватног балкона!\"}'),
(196, 'sr', 32, 'accommodations', '{\"title\":\"Панорама апартман у Прагу\",\"description\":\"Простран и сунчан стан у самом срцу Прага. Модеран намештај, удобни кревети и све погодности очекују госте. У близини су познате знаменитости, ресторани и кафићи. Идеално за породице и парове. Уживајте у сваком тренутку градског живота кроз панорамске прозоре.\"}'),
(197, 'sr', 81, 'accommodations', '{\"title\":\"Модеран стан у Брну\",\"description\":\"Простран, светли стан у центру Брна. Модеран намештај и удобни кревети. Идеалан за парове и породице. У близини градских атракција и ресторана. Уживајте у сваком тренутку градског живота у Чешкој.\"}'),
(198, 'sr', 33, 'accommodations', '{\"title\":\"Брно стилски апартман\",\"description\":\"Удобни и стилски апартман у центру Брна. Светле собе, модеран намештај и удобни кревети очекују госте. Идеално за парове и мале породице. У близини ресторана и саобраћајних веза. Савршен избор за разгледање града и опуштање.\"}'),
(199, 'sr', 82, 'accommodations', '{\"title\":\"Чешке Будејовице Напфенј Апартман\",\"description\":\"Светли, пространи стан у центру Чешких Будејовица. Модеран намештај, удобни кревети. Идеалан за породице и парове. У близини локалних атракција и ресторана. Уживајте у сваком тренутку градског живота у Чешкој.\"}'),
(200, 'sr', 34, 'accommodations', '{\"title\":\"Луксузни апартман у Чешким Будејовицама\",\"description\":\"Елегантан, модеран стан у центру Чешких Будејевица. Пространа дневна соба, добро опремљена кухиња и удобна спаваћа соба. Идеално за породице или групе пријатеља. У близини главних градских атракција. Уживајте у сваком тренутку градског живота у Чешкој.\"}'),
(201, 'sr', 65, 'accommodations', '{\"title\":\"Стана у монреалском стилу\",\"description\":\"Светли, модерни апартман у центру Монреала. Удобни кревети, потпуно опремљен. Идеалан за парове и породице. У близини главних атракција и ресторана. Уживајте у сваком тренутку градског живота у Канади.\"}'),
(202, 'sr', 66, 'accommodations', '{\"title\":\"Панорамски апартман у Торонту\",\"description\":\"Простран, светли стан у Торонту. Модеран намештај и удобни кревети. Идеалан за породице и групе пријатеља. Близу атракција и ресторана. Уживајте у сваком тренутку градског живота у Канади.\"}'),
(203, 'sr', 86, 'accommodations', '{\"title\":\"Модеран стан у Бризбејну\",\"description\":\"Простран и сунчан стан у центру Бризбена. Модеран намештај, удобни кревети и потпуно опремљен. Идеалан за породице и пријатеље. У близини локалних атракција и ресторана. Уживајте у живописном градском животу из удобности свог дома.\"}'),
(204, 'sr', 84, 'accommodations', '{\"title\":\"Апартман Сиднејска лука\",\"description\":\"Прелеп, модеран стан у центру Сиднеја са погледом на луку. Простран дневни боравак, удобне спаваће собе. Идеалан за породице и парове. У близини ресторана и атракција. Уживајте у сваком тренутку аустралијског градског живота.\"}'),
(205, 'sr', 85, 'accommodations', '{\"title\":\"Апартман са дизајном у Мелбурну\",\"description\":\"Стилски, модеран стан у срцу Мелбурна. Светли простори и удобни кревети. Идеалан за парове и пословне путнике. У близини кафића, ресторана и уметничких простора. Уживајте у креативној атмосфери града из свог стана.\"}'),
(206, 'sr', 95, 'accommodations', '{\"title\":\"Апартман Саншајн у Ченају\",\"description\":\"Простран, светли стан у центру Ченаја. Модеран намештај, удобни кревети. Идеалан за породице и пријатеље. У близини атракција и ресторана. Уживајте у сваком тренутку градског живота.\"}'),
(207, 'sr', 94, 'accommodations', '{\"title\":\"Модеран стан у Бангалору\",\"description\":\"Светли, модерни стан у центру Бангалора. Удобни кревети и потпуно опремљен. Идеалан за парове и пословне путнике. У близини ресторана, продавница и атракција. Уживајте у индијском градском животу у удобном окружењу.\"}'),
(208, 'sr', 93, 'accommodations', '{\"title\":\"Луксузни стан у Мумбају\",\"description\":\"Простран и елегантан апартман у центру Мумбаја. Модеран намештај, удобни кревети и потпуно опремљен. Идеалан за породице и парове. У близини градских атракција и ресторана. Уживајте у сваком тренутку живота у индијском граду.\"}'),
(209, 'sr', 31, 'accommodations', '{\"title\":\"Близу Хагиматикума\",\"description\":\"Удобан стан у Маку, близу спа центра Хагиматикум. Простран и светли, са модерним намештајем. Идеалан за породице и парове. Окружен ресторанима и атракцијама. Савршено место за опуштање и одмор.\"}'),
(210, 'sr', 36, 'accommodations', '{\"title\":\"Стана у центру Сегедина\",\"description\":\"Светли и удобни стан у центру Сегедина. Модеран намештај и практичан распоред. У близини пијаца, ресторана и културних установа. Идеално за породице и пријатеље. Савршено место за опуштање и градска искуства.\"}'),
(211, 'sr', 9, 'accommodations', '{\"title\":\"Модеран студио\",\"description\":\"Светли, модерни студио у центру Будимпеште. Удобни намештај, практичан распоред и сва потребна опрема. Идеалан за парове или пословне путнике. Градске атракције и ресторани су на пешачкој удаљености. Савршена комбинација удобности и градског живота.\"}'),
(212, 'sr', 10, 'accommodations', '{\"title\":\"Панорамски стан\",\"description\":\"Простран стан са прелепим погледом, идеалан за породице. Модеран намештај и удобни комади намештаја задовољавају све потребе. Близу центра града и атракција. Околина је мирна и тиха. Уживајте у панорамским погледима у свако доба дана.\"}'),
(213, 'sr', 35, 'accommodations', '{\"title\":\"Луксузни стан у Будимпешти\",\"description\":\"Простран, модеран стан у центру Будимпеште. Елегантан намештај, потпуно опремљена кухиња и удобне спаваће собе. Идеалан за породице и групе пријатеља. У близини атракција и ресторана. Уживајте у живахном животу престонице у сваком тренутку.\"}'),
(214, 'sr', 37, 'accommodations', '{\"title\":\"Панорама апартман у Дебрецену\",\"description\":\"Простран, модеран стан у центру Дебрецена. Светла дневна соба и удобне спаваће собе. Потпуно опремљен, идеалан за породице и парове. У пешачкој удаљености од ресторана и трговинских објеката. Уживајте у сваком тренутку градског живота у Дебрецену.\"}'),
(215, 'sr', 45, 'accommodations', '{\"title\":\"Линзи Панорама Апартман\",\"description\":\"Светли, модерни апартман у центру Линца. Удобно намештен, потпуно опремљен. Идеалан за породице и парове. У близини ресторана и културних атракција. Уживајте у сваком тренутку градског живота.\"}'),
(216, 'sr', 44, 'accommodations', '{\"title\":\"Стана виенске елеганције\",\"description\":\"Простран, елегантан стан у центру Беча. Модеран намештај и удобни кревети. Идеалан за парове и пословне путнике. У близини знаменитости, ресторана и кафића. Уживајте у сваком тренутку живота у Бечу.\"}'),
(217, 'sr', 46, 'accommodations', '{\"title\":\"Салцбургски историјски стан\",\"description\":\"Стилски стан у историјском центру Салцбурга. Светла дневна соба, удобни кревети и добро опремљена кухиња. Идеално за парове и мале породице. У пешачкој удаљености од главних атракција. Уживајте у атмосфери овог историјског града.\"}'),
(218, 'sr', 13, 'accommodations', '{\"title\":\"Стана у центру Беча\",\"description\":\"Елегантан стан у центру Беча, близу атракција. Простран и светли ентеријер идеалан је за породице и парове. Модеран намештај и сва потребна опрема. Ресторани и кафићи су на пешачкој удаљености. Погодна полазна тачка за истраживање града.\"}'),
(219, 'sr', 4, 'accommodations', '{\"title\":\"Шармантан студио на централној локацији\",\"description\":\"Стилски, тихи студио у Бечу са свим неопходним садржајима. Модеран ентеријер пружа пријатну атмосферу за опуштање. Идеалан за парове и кратке градске одморе. Градске знаменитости и ресторани су лако доступни. Савршена база за истраживање Беча.\"}'),
(220, 'sr', 14, 'accommodations', '{\"title\":\"Компактни студио\",\"description\":\"Компактни студио у Бечу, идеалан за краткотрајне боравке. Практичан распоред и светли ентеријер испуњавају све захтеве. Близу главних градских атракција и саобраћајних веза. Савршено за парове или самосталне путнике. Госте очекује удобна и пријатна атмосфера.\"}'),
(221, 'sr', 78, 'accommodations', '{\"title\":\"Елегантан стан у Варшави\",\"description\":\"Светли, пространи стан у центру Варшаве. Модеран намештај, удобни кревети. Идеално за породице и парове. У близини градских атракција и ресторана. Уживајте у сваком тренутку градског живота у Пољској.\"}'),
(222, 'sr', 79, 'accommodations', '{\"title\":\"Краковски историјски апартман\",\"description\":\"Простран, светли стан у историјском делу Кракова. Модеран намештај и удобни кревети. Идеалан за породице и парове. У близини атракција и ресторана. Уживајте у шарму пољског градског живота из удобности свог дома.\"}'),
(223, 'sr', 80, 'accommodations', '{\"title\":\"Гданска панорама апартман\",\"description\":\"Светли, модерни апартман у центру Гдањска. Простран дневни боравак, удобни кревети. Идеално за породице и парове. У близини атракција и ресторана. Уживајте у сваком тренутку градског живота у Пољској.\"}'),
(224, 'sr', 55, 'accommodations', '{\"title\":\"Саппоро апартман на обали\",\"description\":\"Простран, светли стан у Сапороу. Модеран намештај и удобни кревети. Идеално за породице и пријатеље. У близини ресторана и атракција. Уживајте у јапанском градском и природном искуству.\"}'),
(225, 'sr', 53, 'accommodations', '{\"title\":\"Токијски модеран стан\",\"description\":\"Простран, светли стан у централном Токију. Модеран намештај, удобни кревети. Идеалан за парове и пословне путнике. У близини ресторана, тржних центара и атракција. Уживајте у сваком тренутку јапанског градског живота.\"}'),
(226, 'sr', 53, 'accommodations', '{\"title\":\"Токијски модеран стан\",\"description\":\"Простран, светли стан у централном Токију. Модеран намештај, удобни кревети. Идеалан за парове и пословне путнике. У близини ресторана, тржних центара и атракција. Уживајте у сваком тренутку јапанског градског живота.\"}'),
(227, 'sr', 55, 'accommodations', '{\"title\":\"Саппоро апартман на обали\",\"description\":\"Простран, светли стан у Сапороу. Модеран намештај и удобни кревети. Идеално за породице и пријатеље. Близу ресторана и атракција. Уживајте у јапанском градском и природном искуству.\"}'),
(228, 'de', 65, 'accommodations', '{\"title\":\"Montreal Stil Wohnung\",\"description\":\"Helles, modernes Apartment im Zentrum von Montreal. Bequeme Betten, komplett ausgestattet. Ideal für Paare und Familien. In der Nähe der wichtigsten Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des kanadischen Stadtlebens.\"}'),
(229, 'de', 66, 'accommodations', '{\"title\":\"Toronto Panorama Wohnung\",\"description\":\"Geräumiges, helles Apartment in Toronto. Moderne Möbel und bequeme Betten. Ideal für Familien und Gruppen von Freunden. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des kanadischen Stadtlebens.\"}'),
(230, 'de', 93, 'accommodations', '{\"title\":\"Luxuswohnung in Mumbai\",\"description\":\"Geräumiges und elegantes Apartment im Zentrum von Mumbai. Moderne Möbel, bequeme Betten und komplette Ausstattung. Ideal für Familien und Paare. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie jeden Moment des indischen Stadtlebens.\"}'),
(231, 'de', 95, 'accommodations', '{\"title\":\"Csennai Sonnenschein Wohnung\",\"description\":\"Geräumiges, helles Apartment im Zentrum von Chennai. Moderne Möbel, bequeme Betten. Ideal für Familien und Freunde. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des Stadtlebens.\"}'),
(232, 'de', 94, 'accommodations', '{\"title\":\"Moderne Wohnung in Bangalore\",\"description\":\"Helle, moderne Wohnung im Zentrum von Bangalore. Bequeme Betten und komplette Ausstattung. Ideal für Paare und Geschäftsreisende. In der Nähe von Restaurants, Geschäften und Sehenswürdigkeiten. Genießen Sie das indische Stadtleben in einer komfortablen Umgebung.\"}'),
(233, 'de', 17, 'accommodations', '{\"title\":\"Romantische Wohnung\",\"description\":\"Romantische Wohnung in Paris in ausgezeichneter Lage. Die Innenräume sind elegant, stilvoll und gemütlich. Ideal für Paare, die einen romantischen Kurzurlaub verbringen möchten. Die Umgebung ist voller Restaurants, Cafés und Sehenswürdigkeiten. Genießen Sie jeden Moment der Pariser Atmosphäre.\"}'),
(234, 'de', 57, 'accommodations', '{\"title\":\"Lyoni Stil Apartment\",\"description\":\"Helles, modernes Apartment im Zentrum von Lyon. Bequeme Betten, komplett ausgestattet. Ideal für Paare und Geschäftsreisende. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie jeden Moment des französischen Stadtlebens.\"}'),
(235, 'de', 18, 'accommodations', '{\"title\":\"Apartment mit Balkon\",\"description\":\"Helles Apartment mit Balkon in Paris. Moderne Möbel und eine komfortable Einrichtung erfüllen alle Bedürfnisse. Ideal für Familien und Gruppen von Freunden. In der Nähe der wichtigsten Sehenswürdigkeiten der Stadt. Genießen Sie die frische Luft und den Blick auf die Stadt von Ihrem privaten Balkon aus.\"}'),
(236, 'de', 33, 'accommodations', '{\"title\":\"Brno Style Apartment\",\"description\":\"Gemütliches und stilvolles Apartment im Zentrum von Brünn. Helle Räume, moderne Möbel und bequeme Betten erwarten die Gäste. Ideal für Paare und kleine Familien. In der Nähe von Restaurants und Verkehrsknotenpunkten. Die perfekte Wahl für Sightseeing und Entspannung.\"}'),
(237, 'de', 32, 'accommodations', '{\"title\":\"Prag Panorama Apartment\",\"description\":\"Geräumige und sonnige Wohnung im Herzen von Prag. Moderne Möbel, bequeme Betten und eine komplette Ausstattung erwarten die Gäste. In der Nähe von berühmten Sehenswürdigkeiten, Restaurants und Cafés. Ideal für Familien und Paare. Genießen Sie jeden Moment des Stadtlebens aus den Panoramafenstern.\"}'),
(238, 'de', 56, 'accommodations', '{\"title\":\"Luxuswohnung in Paris\",\"description\":\"Elegante, helle Wohnung im Zentrum von Paris. Moderne Einrichtung, komplett ausgestattet. Ideal für Paare und Familien. In der Nähe der wichtigsten Sehenswürdigkeiten, Restaurants und Cafés. Genießen Sie die romantische französische Atmosphäre in jedem Moment.\"}'),
(239, 'de', 3, 'accommodations', '{\"title\":\"Gemütliche Wohnung im Zentrum\",\"description\":\"Sonnige, gemütliche Wohnung im Zentrum von Prag. Die Wohnung ist mit modernen Möbeln ausgestattet und bietet alle Annehmlichkeiten für einen komfortablen Aufenthalt. Die Umgebung ist reich an Sehenswürdigkeiten, Cafés und Restaurants. Hervorragende Verkehrsanbindung, ideal für jede Art von Reise. Genießen Sie jeden Moment des Stadtlebens in dieser gemütlichen Wohnung.\"}'),
(240, 'de', 58, 'accommodations', '{\"title\":\"Marseille Strandwohnung\",\"description\":\"Geräumiges, helles Apartment in Marseille, nahe der Küste. Moderne Einrichtung, bequeme Betten und komplett ausgestattet. Ideal für Familien und Gruppen von Freunden. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie das mediterrane Leben in vollen Zügen.\"}'),
(241, 'de', 2, 'accommodations', '{\"title\":\"Gemütliches Studio mit Balkon\",\"description\":\"Modernes Studio mit Balkon, ideal für einen kurzen Aufenthalt in der Stadt. Das helle, gemütliche Interieur bietet allen Komfort. In der Nähe von Verkehrsmitteln und lokalen Restaurants. Perfekt für Paare oder Geschäftsreisende. Genießen Sie das geschäftige Treiben der Stadt von Ihrem eigenen Balkon aus!\"}'),
(242, 'de', 81, 'accommodations', '{\"title\":\"Moderne Wohnung in Brünn\",\"description\":\"Geräumiges, helles Apartment im Zentrum von Brünn. Moderne Möbel und bequeme Betten. Ideal für Paare und Familien. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie jeden Moment des tschechischen Stadtlebens.\"}'),
(243, 'de', 34, 'accommodations', '{\"title\":\"České Budějovice Luxuswohnung\",\"description\":\"Elegante, moderne Wohnung im Zentrum von České Budějovice. Geräumiges Wohnzimmer, gut ausgestattete Küche und komfortables Schlafzimmer. Ideal für Familien oder Gruppen von Freunden. In der Nähe der wichtigsten Sehenswürdigkeiten der Stadt. Genießen Sie jeden Moment des tschechischen Stadtlebens.\"}'),
(244, 'de', 16, 'accommodations', '{\"title\":\"Stadtstudio\",\"description\":\"Modernes Stadtstudio im Zentrum von Madrid. Hell und praktisch, mit allem Notwendigen ausgestattet. Ideal für Paare und Geschäftsreisende. In der Nähe der wichtigsten Sehenswürdigkeiten und Verkehrsknotenpunkte. Komfortabler und stilvoller Aufenthalt in der Stadt.\"}'),
(245, 'de', 51, 'accommodations', '{\"title\":\"Barcelona Strandwohnung\",\"description\":\"Geräumiges Apartment im Zentrum von Barcelona, nahe am Meer. Modern eingerichtet und komplett ausgestattet. Ideal für Familien und Freunde. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie das katalanische Stadtleben und die Entspannung am Meer.\"}'),
(246, 'de', 82, 'accommodations', '{\"title\":\"České Budějovice Napfény Wohnung\",\"description\":\"Helles, geräumiges Apartment im Zentrum von České Budějovice. Moderne Möbel, bequeme Betten. Ideal für Familien und Paare. In der Nähe von lokalen Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des tschechischen Stadtlebens.\"}'),
(247, 'de', 50, 'accommodations', '{\"title\":\"Madrid Elegantes Apartment\",\"description\":\"Helle, stilvolle Wohnung im Zentrum von Madrid. Moderne Möbel und bequeme Betten. Ideal für Paare und Familien. In der Nähe der wichtigsten Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie jeden Moment des spanischen Stadtlebens.\"}'),
(248, 'de', 52, 'accommodations', '{\"title\":\"Romantische Wohnung in Sevilla\",\"description\":\"Stilvolles, helles Apartment im historischen Teil von Sevilla. Bequeme Möbel und gut ausgestattete Küche. Ideal für Paare und kleine Familien. In der Nähe der wichtigsten Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie die spanische Atmosphäre in jedem Moment.\"}'),
(249, 'de', 59, 'accommodations', '{\"title\":\"Madrid Elegancia Wohnung\",\"description\":\"Helle, stilvolle Wohnung im Zentrum von Madrid. Bequeme Betten, moderne Möbel. Ideal für Paare und Familien. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des spanischen Stadtlebens.\"}'),
(250, 'de', 61, 'accommodations', '{\"title\":\"Romantische Wohnung in Sevilla\",\"description\":\"Stilvolles Apartment im historischen Viertel von Sevilla. Komfortable Einrichtung und komplett ausgestattet. Ideal für Paare und kleine Familien. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie das spanische Flair in jedem Moment.\"}'),
(251, 'de', 60, 'accommodations', '{\"title\":\"Barcelona Panorama Apartment\",\"description\":\"Geräumiges und helles Apartment im Zentrum von Barcelona. Bequeme Möbel, komplett ausgestattet. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des mediterranen Lebens.\"}'),
(252, 'de', 87, 'accommodations', '{\"title\":\"Seoul Panorama Studio\",\"description\":\"Helles Studio im Zentrum von Seoul. Moderne Möbel, bequemes Bett. Ideal für Alleinreisende oder Paare. In der Nähe von U-Bahn und Restaurants. Genießen Sie das pulsierende Leben der Stadt in Ihrer eigenen komfortablen Wohnung.\"}'),
(253, 'de', 89, 'accommodations', '{\"title\":\"Incshon Business Studio\",\"description\":\"Modernes, praktisches Studio im Zentrum von Incshon. Bequemes Bett, komplett ausgestattet. Ideal für Geschäftsreisende und Paare. In der Nähe von Verkehrsknotenpunkten und Restaurants. Genießen Sie den Komfort der Stadt in Ihrem eigenen Studio.\"}'),
(254, 'de', 88, 'accommodations', '{\"title\":\"Pusan Strandwohnung\",\"description\":\"Geräumiges Apartment an der Küste von Pusan. Helle und moderne Einrichtung, bequeme Betten. Ideal für Familien und Freundesgruppen. In der Nähe des Strandes und von Restaurants. Genießen Sie die Strandatmosphäre im Stadtzentrum.\"}'),
(255, 'de', 98, 'accommodations', '{\"title\":\"Monterrey Panorama Wohnung\",\"description\":\"Geräumiges, helles Apartment im Zentrum von Monterrey. Moderne Möbel und bequeme Betten. Ideal für Familien und Gruppen von Freunden. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie jeden Moment des mexikanischen Stadtlebens.\"}'),
(256, 'de', 97, 'accommodations', '{\"title\":\"Guadalajara Design Wohnung\",\"description\":\"Helle, moderne Wohnung in Guadalajara. Bequeme Möbel, komplett ausgestattet. Ideal für Paare und Geschäftsreisende. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie das mexikanische Stadtleben in einer komfortablen Umgebung.\"}'),
(257, 'de', 96, 'accommodations', '{\"title\":\"Mexiko-Stadt Stil Wohnung\",\"description\":\"Modernes, helles Apartment im Zentrum von Mexiko-Stadt. Geräumiges Wohnzimmer, bequeme Betten. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des mexikanischen Stadtlebens.\"}'),
(258, 'de', 72, 'accommodations', '{\"title\":\"Moderne Wohnung in Oslo\",\"description\":\"Helles, geräumiges Apartment im Zentrum von Oslo. Moderne Möbel, bequeme Betten und komplett ausgestattet. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des norwegischen Stadtlebens.\"}'),
(259, 'de', 20, 'accommodations', '{\"title\":\"Familienwohnung\",\"description\":\"Geräumige Familienwohnung in Berlin. Moderne Möbel und gut ausgestattete Küche. Ideal für größere Familien. In der Nähe der Sehenswürdigkeiten und Parks der Stadt. Bequemer, gemütlicher Ort zum Entspannen und Erholen.\"}'),
(260, 'de', 26, 'accommodations', '{\"title\":\"Stadtstudio\",\"description\":\"Stadtstudio in New York, ideal für Geschäftsreisende. Helles und modernes Interieur mit praktischer Ausstattung. In der Nähe von Verkehrsmitteln und Sehenswürdigkeiten der Stadt. Komfortabler und gemütlicher Ort für einen kurzen Aufenthalt.\"}'),
(261, 'de', 80, 'accommodations', '{\"title\":\"Gdańsk Panorama Apartment\",\"description\":\"Helles, modernes Apartment im Zentrum von Danzig. Geräumiges Wohnzimmer, bequeme Betten. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des polnischen Stadtlebens.\"}'),
(262, 'de', 62, 'accommodations', '{\"title\":\"New York City Panorama Apartment\",\"description\":\"Geräumiges, helles Apartment im Herzen von New York. Moderne Möbel, bequeme Betten und komplette Ausstattung. Ideal für Familien und Geschäftsreisende. In der Nähe der wichtigsten Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des Großstadtlebens.\"}'),
(263, 'de', 78, 'accommodations', '{\"title\":\"Elegante Wohnung in Warschau\",\"description\":\"Helles, geräumiges Apartment im Zentrum von Warschau. Moderne Möbel, bequeme Betten. Ideal für Familien und Paare. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie jeden Moment des polnischen Stadtlebens.\"}'),
(264, 'de', 79, 'accommodations', '{\"title\":\"Historische Wohnung in Krakau\",\"description\":\"Geräumige, helle Wohnung im historischen Teil von Krakau. Moderne Möbel und bequeme Betten. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie den Charme des polnischen Stadtlebens von Ihrem eigenen Zuhause aus.\"}'),
(265, 'de', 25, 'accommodations', '{\"title\":\"Luxus-Suite\",\"description\":\"Luxuriöses Apartment in New York mit Premium-Ausstattung. Geräumiges und elegantes Interieur mit komfortablen Möbeln. Ideal für Familien und Freundesgruppen. In der Nähe der Sehenswürdigkeiten der Stadt. Genießen Sie Premium-Entspannung im Herzen der Metropole.\"}'),
(266, 'de', 64, 'accommodations', '{\"title\":\"Chicago Elegancia Apartment\",\"description\":\"Geräumige, helle Wohnung im Zentrum von Chicago. Moderne Möbel und bequeme Betten. Ideal für Familien und Geschäftsreisende. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie jeden Moment des amerikanischen Großstadtlebens.\"}'),
(267, 'de', 68, 'accommodations', '{\"title\":\"Chicago Skyline Wohnung\",\"description\":\"Geräumiges Apartment mit Panoramablick im Zentrum von Chicago. Moderne Möbel und bequeme Betten. Ideal für Geschäftsreisende und Familien. In der Nähe von Restaurants, Parks und Sehenswürdigkeiten. Genießen Sie das pulsierende Leben der Stadt von Ihrem komfortablen Zuhause aus.\"}'),
(268, 'de', 63, 'accommodations', '{\"title\":\"Moderne Wohnung in Los Angeles\",\"description\":\"Helle und stilvolle Wohnung im Zentrum von Los Angeles. Bequeme Betten und moderne Möbel. Ideal für Paare und Geschäftsreisende. In der Nähe von Sehenswürdigkeiten und Stränden. Genießen Sie den kalifornischen Lebensstil in vollen Zügen.\"}'),
(269, 'de', 67, 'accommodations', '{\"title\":\"Los Angeles Sunshine Apartment\",\"description\":\"Helles, geräumiges Apartment im Herzen von Los Angeles. Moderne Möbel, bequeme Betten, komplett ausgestattet. Ideal für Familien und Freundesgruppen. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie den kalifornischen Lebensstil in Ihrem eigenen Apartment.\"}'),
(270, 'de', 75, 'accommodations', '{\"title\":\"Helsinki Design Wohnung\",\"description\":\"Helles, modernes Apartment im Zentrum von Helsinki. Bequeme Betten und geräumiges Wohnzimmer. Ideal für Familien und Paare. In der Nähe von Restaurants, Cafés und Museen. Genießen Sie jeden Moment des finnischen Stadtlebens.\"}'),
(271, 'de', 23, 'accommodations', '{\"title\":\"Bergwohnung\",\"description\":\"Bergwohnung für Erholung in der Natur. Geräumig und hell, mit modernen Möbeln. Ideal für Familien und Freundesgruppen. Die Umgebung bietet zahlreiche Ausflugsmöglichkeiten und Sehenswürdigkeiten. Ein komfortabler und gemütlicher Ort zum Entspannen.\"}'),
(272, 'de', 76, 'accommodations', '{\"title\":\"Tampere Panorama Apartment\",\"description\":\"Geräumiges und helles Apartment im Zentrum von Tampere. Moderne Möbel und bequeme Betten. Ideal für Familien und Paare. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie das finnische Stadtleben von Ihrem komfortablen Zuhause aus.\"}'),
(273, 'de', 77, 'accommodations', '{\"title\":\"Oulu Arctic Wohnung\",\"description\":\"Helles, modernes Apartment im Zentrum von Oulu. Geräumiges Wohnzimmer, bequeme Betten. Ideal für Paare und Familien. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie das finnische Stadtleben und die nordische Atmosphäre in Ihrem eigenen Zuhause.\"}'),
(274, 'de', 9, 'accommodations', '{\"title\":\"Modernes Studio\",\"description\":\"Helles, modernes Studio im Zentrum von Budapest. Bequeme Möbel, praktische Einrichtung und alle notwendigen Ausstattungen. Ideal für Paare oder Geschäftsreisende. Die Sehenswürdigkeiten und Restaurants der Stadt sind zu Fuß erreichbar. Die perfekte Kombination aus Komfort und Stadtleben.\"}'),
(275, 'de', 10, 'accommodations', '{\"title\":\"Wohnung mit Panoramablick\",\"description\":\"Geräumige Wohnung mit wunderschöner Aussicht, ideal für Familien. Die moderne Ausstattung und die bequemen Möbel lassen keine Wünsche offen. In der Nähe des Stadtzentrums und der Sehenswürdigkeiten. Die Umgebung ist ruhig und bietet Erholung. Genießen Sie den Panoramablick zu jeder Tageszeit.\"}'),
(276, 'de', 31, 'accommodations', '{\"title\":\"In der Nähe von Hagymatikum\",\"description\":\"Komfortable Wohnung in Makó, in der Nähe des Hagymatikum-Thermalbads. Geräumig und hell, mit modernen Möbeln. Ideal für Familien und Paare. Die Umgebung ist reich an Restaurants und Sehenswürdigkeiten. Der perfekte Ort zum Entspannen und Erholen.\"}'),
(277, 'de', 83, 'accommodations', '{\"title\":\"Bratislava Elegant Apartment\",\"description\":\"Modernes, helles Apartment im Zentrum von Bratislava. Bequeme Betten, geräumiges Wohnzimmer. Ideal für Paare und Familien. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie den Komfort und Stil des slowakischen Stadtlebens.\"}'),
(278, 'de', 36, 'accommodations', '{\"title\":\"Apartment in der Innenstadt von Szeged\",\"description\":\"Helles und komfortables Apartment im Stadtzentrum von Szeged. Moderne Einrichtung und praktische Raumaufteilung. In der Nähe von Märkten, Restaurants und kulturellen Sehenswürdigkeiten. Ideal für Familien und Freunde. Der perfekte Ort zum Entspannen und für Stadtbesichtigungen.\"}'),
(279, 'de', 35, 'accommodations', '{\"title\":\"Luxuswohnung in Budapest\",\"description\":\"Geräumige, moderne Wohnung im Zentrum von Budapest. Elegante Möbel, voll ausgestattete Küche und komfortable Schlafzimmer. Ideal für Familien und Freundesgruppen. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie das pulsierende Leben der Hauptstadt in jedem Moment.\"}'),
(280, 'de', 37, 'accommodations', '{\"title\":\"Panorama-Wohnung in Debrecen\",\"description\":\"Geräumige, moderne Wohnung im Zentrum von Debrecen. Helles Wohnzimmer und komfortable Schlafzimmer. Voll ausgestattet, ideal für Familien und Paare. Restaurants und Einkaufsmöglichkeiten sind zu Fuß erreichbar. Genießen Sie jeden Moment des Stadtlebens in Debrecen.\"}'),
(281, 'de', 42, 'accommodations', '{\"title\":\"Luxuswohnung in München\",\"description\":\"Elegante, geräumige Wohnung im Herzen Münchens. Moderne Möbel und gut ausgestattete Küche. Ideal für Familien und Freunde. In der Nähe der wichtigsten Sehenswürdigkeiten. Genießen Sie die Atmosphäre der bayerischen Stadt.\"}'),
(282, 'de', 41, 'accommodations', '{\"title\":\"Moderne Wohnung in Berlin\",\"description\":\"Jugendliche, helle Wohnung im Zentrum von Berlin. Bequeme Betten und praktische Möbel. Ideal für Paare oder Geschäftsreisende. In der Nähe von öffentlichen Verkehrsmitteln und Restaurants. Perfekt für einen erholsamen Stadturlaub.\"}'),
(283, 'de', 19, 'accommodations', '{\"title\":\"Jugendliches Studio\",\"description\":\"Junges Studio in Berlin mit moderner Ausstattung. Ideal für Paare und Geschäftsreisende. Helles und gemütliches Interieur sorgt für Komfort. In der Nähe von Verkehrsmitteln und lokalen Sehenswürdigkeiten. Perfekt für kurze Aufenthalte.\"}'),
(284, 'de', 43, 'accommodations', '{\"title\":\"Kölni Stil Apartment\",\"description\":\"Helle und moderne Wohnung im Zentrum von Köln. Bequeme Betten und komplett ausgestattet. Ideal für Paare und kleine Familien. In der Nähe von Sehenswürdigkeiten und Restaurants. Die perfekte Wahl für einen kurzen Aufenthalt in der Stadt.\"}'),
(285, 'de', 30, 'accommodations', '{\"title\":\"Modernes Studio\",\"description\":\"Modernes Studio in Griechenland, praktisch und komfortabel. Das helle Interieur erfüllt alle Anforderungen. Ideal für Paare und kurze Aufenthalte. In der Nähe von lokalen Sehenswürdigkeiten und Restaurants. Die perfekte Wahl für Entspannung.\"}'),
(286, 'de', 29, 'accommodations', '{\"title\":\"Historische Wohnung\",\"description\":\"Griechische Wohnung mit historischem Flair. Klassisch eingerichtet, hell und geräumig. Ideal für Familien und Freundesgruppen. In der Nähe von lokalen Sehenswürdigkeiten und Restaurants. Genießen Sie die traditionelle griechische Umgebung in komfortabler Atmosphäre.\"}'),
(287, 'de', 48, 'accommodations', '{\"title\":\"Moderne Wohnung in Thessaloniki\",\"description\":\"Helle, moderne Wohnung in Thessaloniki. Bequeme Betten, komplett ausgestattet. Ideal für Paare und kleine Familien. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie den griechischen Lebensstil in jedem Moment.\"}'),
(288, 'de', 47, 'accommodations', '{\"title\":\"Panorama-Wohnung in Athen\",\"description\":\"Geräumige und helle Wohnung im Herzen von Athen. Moderne Möbel, bequeme Betten. Ideal für Paare und Familien. In der Nähe von antiken Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des mediterranen Lebens.\"}'),
(289, 'de', 49, 'accommodations', '{\"title\":\"Wohnung am Meer in Rhodos\",\"description\":\"Geräumiges Apartment auf der Insel Rhodos, nahe am Meer. Moderne Einrichtung und bequeme Betten. Ideal für Familien und Freundesgruppen. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie die Sonne und die Entspannung am Meer.\"}'),
(290, 'de', 90, 'accommodations', '{\"title\":\"Historische Wohnung in Peking\",\"description\":\"Wunderschöne, geräumige Wohnung im historischen Viertel von Peking. Moderne Möbel, bequeme Betten. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und lokalen Restaurants. Genießen Sie die chinesische Stadtkultur in einer komfortablen Umgebung.\"}'),
(291, 'de', 91, 'accommodations', '{\"title\":\"Moderne Wohnung in Shanghai\",\"description\":\"Helles, modernes Apartment im Zentrum von Shanghai. Bequeme Möbel, geräumige Schlafzimmer. Ideal für Familien und Freunde. In der Nähe von Geschäften und Restaurants. Genießen Sie jeden Moment des chinesischen Großstadtlebens.\"}'),
(292, 'de', 85, 'accommodations', '{\"title\":\"Melbourne Design Wohnung\",\"description\":\"Stilvolle, moderne Wohnung im Herzen von Melbourne. Helle Räume und bequeme Betten. Ideal für Paare und Geschäftsreisende. In der Nähe von Cafés, Restaurants und Kunststätten. Genießen Sie die kreative Atmosphäre der Stadt in Ihrer eigenen Wohnung.\"}'),
(293, 'de', 84, 'accommodations', '{\"title\":\"Sydney Harbour Wohnung\",\"description\":\"Wunderschönes, modernes Apartment im Zentrum von Sydney mit Blick auf den Hafen. Geräumiges Wohnzimmer, komfortable Schlafzimmer. Ideal für Familien und Paare. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie jeden Moment des australischen Stadtlebens.\"}'),
(294, 'de', 92, 'accommodations', '{\"title\":\"Kuangchou Panorama Apartment\",\"description\":\"Geräumige und helle Wohnung im Zentrum von Guangzhou. Moderne Möbel und bequeme Betten. Ideal für Familien und Geschäftsreisende. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie die lebhafte Atmosphäre der Stadt in Ihrer eigenen Wohnung.\"}'),
(295, 'de', 86, 'accommodations', '{\"title\":\"Moderne Wohnung in Brisbane\",\"description\":\"Geräumiges und sonniges Apartment im Zentrum von Brisbane. Moderne Möbel, bequeme Betten und komplett ausgestattet. Ideal für Familien und Freunde. In der Nähe von lokalen Sehenswürdigkeiten und Restaurants. Genießen Sie das pulsierende Leben der Stadt von Ihrem komfortablen Zuhause aus.\"}'),
(296, 'de', 28, 'accommodations', '{\"title\":\"Apartment in the city center\",\"description\":\"Komfortable und gemütliche Wohnung im Stadtzentrum von Mailand. Helles Interieur, gut ausgestattet. Ideal für Paare und Familien. In der Nähe der wichtigsten Sehenswürdigkeiten und Verkehrsmittel der Stadt. Perfekter Ausgangspunkt, um Mailand zu entdecken.\"}'),
(297, 'de', 38, 'accommodations', '{\"title\":\"Römische Eleganz Wohnung\",\"description\":\"Elegante, helle Wohnung im Zentrum von Rom. Moderne Einrichtung, bequeme Betten, komplett ausgestattet. Ideal für Paare oder Familien. In der Nähe der historischen Sehenswürdigkeiten. Die perfekte Wahl für romantische Stadtspaziergänge.\"}'),
(298, 'de', 40, 'accommodations', '{\"title\":\"Wohnung am Meer in Neapel\",\"description\":\"Helles und geräumiges Apartment an der Küste von Neapel. Moderne Einrichtung, komplett ausgestattet, ideal für Familien. In der Nähe von Restaurants und Stränden. Genießen Sie jeden Tag die Sonne und den Meerblick.\"}'),
(299, 'de', 39, 'accommodations', '{\"title\":\"Mailänder Stil Apartment\",\"description\":\"Moderne, elegante Wohnung im Herzen von Mailand. Helles und geräumiges Wohnzimmer, komfortable Schlafzimmer. Ideal für Geschäftsreisende oder Paare. In der Nähe von Verkehrsmitteln und Modesehenswürdigkeiten. Genießen Sie die pulsierende Atmosphäre Mailands.\"}'),
(300, 'de', 27, 'accommodations', '{\"title\":\"Mediterranes Apartment\",\"description\":\"Mediterranes Apartment in Rom mit gemütlichem Interieur. Geräumig und hell, mit modernen Möbeln. Ideal für Familien und Paare. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie den italienischen Lebensstil in einer komfortablen Umgebung.\"}'),
(301, 'de', 44, 'accommodations', '{\"title\":\"Wiener Eleganz Wohnung\",\"description\":\"Geräumige, elegante Wohnung im Zentrum von Wien. Moderne Möbel und bequeme Betten. Ideal für Paare und Geschäftsreisende. In der Nähe von Sehenswürdigkeiten, Restaurants und Cafés. Genießen Sie jeden Moment des Wiener Lebens.\"}'),
(302, 'de', 45, 'accommodations', '{\"title\":\"Linzi Panorama Apartment\",\"description\":\"Helles, modernes Apartment im Zentrum von Linz. Bequeme Möbel, komplett ausgestattet. Ideal für Familien und Paare. In der Nähe von Restaurants und kulturellen Sehenswürdigkeiten. Genießen Sie jeden Moment des Stadtlebens.\"}'),
(303, 'de', 4, 'accommodations', '{\"title\":\"Charmantes Studio zentral\",\"description\":\"Stilvolles, ruhiges Studio in Wien mit allem, was Sie brauchen. Die moderne Einrichtung sorgt für eine angenehme Atmosphäre zum Entspannen. Ideal für Paare und kurze Städtereisen. Die Sehenswürdigkeiten und Restaurants der Stadt sind leicht zu erreichen. Der perfekte Ausgangspunkt, um Wien zu entdecken.\"}'),
(304, 'de', 14, 'accommodations', '{\"title\":\"Kompaktes Studio\",\"description\":\"Kompaktes Studio in Wien, ideal für Kurzaufenthalte. Die praktische Aufteilung und das helle Interieur lassen keine Wünsche offen. In der Nähe der wichtigsten Sehenswürdigkeiten und Verkehrsmittel der Stadt. Perfekt für Paare oder Alleinreisende. Es erwartet Sie eine gemütliche und heimelige Atmosphäre.\"}'),
(305, 'de', 46, 'accommodations', '{\"title\":\"Salzburg Historische Wohnung\",\"description\":\"Stilvolle Wohnung im historischen Stadtzentrum von Salzburg. Helles Wohnzimmer, bequeme Betten und gut ausgestattete Küche. Ideal für Paare und kleine Familien. Die wichtigsten Sehenswürdigkeiten sind zu Fuß erreichbar. Genießen Sie die Atmosphäre dieser historischen Stadt.\"}'),
(306, 'de', 13, 'accommodations', '{\"title\":\"Wohnung in der Wiener Innenstadt\",\"description\":\"Elegante Wohnung im Zentrum von Wien, in der Nähe der Sehenswürdigkeiten. Der geräumige und helle Innenraum ist ideal für Familien und Paare. Moderne Möbel und alle notwendigen Ausstattungen. Restaurants und Cafés sind zu Fuß erreichbar. Bequemer Ausgangspunkt, um die Stadt zu erkunden.\"}'),
(307, 'de', 53, 'accommodations', '{\"title\":\"Moderne Wohnung in Tokio\",\"description\":\"Geräumige, helle Wohnung im Zentrum von Tokio. Moderne Möbel, bequeme Betten. Ideal für Paare und Geschäftsreisende. In der Nähe von Restaurants, Einkaufszentren und Sehenswürdigkeiten. Genießen Sie jeden Moment des japanischen Großstadtlebens.\"}'),
(308, 'de', 55, 'accommodations', '{\"title\":\"Wohnung am Meer in Sapporo\",\"description\":\"Geräumige, helle Wohnung in Sapporo. Moderne Möbel und bequeme Betten. Ideal für Familien und Freunde. In der Nähe von Restaurants und Sehenswürdigkeiten. Genießen Sie das japanische Stadtleben und die Natur.\"}');
INSERT INTO `translations` (`id`, `language_short_name`, `item_id`, `item_name`, `item`) VALUES
(309, 'de', 74, 'accommodations', '{\"title\":\"Tromsø Arctic Studio\",\"description\":\"Modernes Studio im Zentrum von Tromsø. Bequemes Bett, helles Interieur. Ideal für Paare und Alleinreisende. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie den Zauber der Nordlichter in Ihrem eigenen Studio.\"}'),
(310, 'de', 73, 'accommodations', '{\"title\":\"Bergen Fjord Wohnung\",\"description\":\"Geräumige, helle Wohnung im historischen Teil von Bergen. Moderne Möbel und bequeme Betten. Ideal für Paare und Familien. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie den Blick auf die Fjorde und das norwegische Stadtleben.\"}'),
(311, 'de', 21, 'accommodations', '{\"title\":\"Apartment mit Meerblick\",\"description\":\"Apartment mit Meerblick in ruhiger Umgebung. Geräumiges und helles Interieur mit allen Annehmlichkeiten. Ideal für Paare und Familien. In der Nähe des Strandes und von Restaurants. Genießen Sie einen ruhigen Urlaub am Meer.\"}'),
(312, 'de', 99, 'accommodations', '{\"title\":\"Lissabon Sonnige Wohnung\",\"description\":\"Helles, geräumiges Apartment im historischen Zentrum von Lissabon. Moderne Möbel, bequeme Betten. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie jeden Moment des portugiesischen Stadtlebens.\"}'),
(313, 'de', 100, 'accommodations', '{\"title\":\"Porto Design Wohnung\",\"description\":\"Stilvolle, moderne Wohnung im Zentrum von Porto. Bequeme Betten, komplett ausgestattet. Ideal für Paare und Geschäftsreisende. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie das portugiesische Stadtleben in einer komfortablen Umgebung.\"}'),
(314, 'de', 70, 'accommodations', '{\"title\":\"Geräumige Wohnung in Malmö\",\"description\":\"Helles und geräumiges Apartment im Herzen von Malmö. Moderne Möbel und bequeme Betten. Ideal für Familien und Freunde. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Genießen Sie jeden Moment des schwedischen Stadtlebens von diesem komfortablen Apartment aus.\"}'),
(315, 'de', 71, 'accommodations', '{\"title\":\"Örebro Panorama Wohnung\",\"description\":\"Geräumige, sonnige Wohnung im Zentrum von Örebro. Moderne Möbel und bequeme Betten. Ideal für Familien und Paare. In der Nähe von Sehenswürdigkeiten und Restaurants. Genießen Sie den Komfort des schwedischen Stadtlebens in Ihrem eigenen Zuhause.\"}'),
(316, 'de', 24, 'accommodations', '{\"title\":\"Skandinavisches Studio\",\"description\":\"Skandinavisches Studio mit klarem Design. Moderne Ausstattung, komfortable Einrichtung. Ideal für Paare und Geschäftsreisende. In der Nähe der Sehenswürdigkeiten und Restaurants der Stadt. Praktische und stilvolle Wahl für einen kurzen Aufenthalt.\"}'),
(317, 'de', 69, 'accommodations', '{\"title\":\"Stockholm Design Wohnung\",\"description\":\"Moderne, helle Wohnung im Zentrum von Stockholm. Bequeme Betten, geräumiges Wohnzimmer und komplett ausgestattet. Ideal für Paare und Familien. In der Nähe von Cafés, Restaurants und Museen. Genießen Sie den Komfort und Stil des schwedischen Stadtlebens.\"}'),
(318, 'en', 64, 'experiences', '{\"title\":\"Malmö night tour\",\"description\":\"Discover Malmö\'s nightlife and sightseeing on an evening walk, where the city\'s modern buildings, lights and cafés offer a special atmosphere. During the night walk, the city\'s main square and parks are even more magical when lit up. Find local restaurants in this atmosphere. This is a pleasant evening programme for discovering the city\'s culture. \"}'),
(319, 'en', 43, 'experiences', '{\"title\":\"Malmö design walk\",\"description\":\"Discover Malmö\'s modern architecture and design district, where the city awaits you with its clean-cut style and creative spaces. During your walk, you will also find contemporary art installations and shops. The city\'s parks and squares are ideal places to spend a relaxing day. The local cafés offer unique flavours. This experience combines creativity and sightseeing. \"}'),
(320, 'en', 21, 'experiences', '{\"title\":\"Walking tour of Stockholm\'s Old Town\",\"description\":\"Discover Stockholm\'s historic old town, Gamla Stan, where narrow streets, colourful houses and cosy terraces await you. Museums and visitor centres are also included in the programme as you learn about the city\'s rich history. The coastal views and Scandinavian-style cafés add a special atmosphere to the experience. While walking around, it is worth sampling local handicrafts and specialities. Stockholm offers visitors both cultural and natural attractions.\"}'),
(321, 'en', 42, 'experiences', '{\"title\":\"Stockholm water tour\",\"description\":\"Visit Stockholm\'s famous waterways by boat, where the city\'s unique islands and buildings offer stunning views from the water. During the boat trip, historical and modern details combine to create an unforgettable panorama. The tour is ideal for families and friends alike. Restaurants and cafés along the harbours offer local delicacies. The water adventure is also an excellent addition to a full-day programme. \"}'),
(322, 'en', 63, 'experiences', '{\"title\":\"Stockholm museum tour\",\"description\":\"Discover Stockholm\'s cultural life on a museum and gallery tour, where modern and classical art await you. The city\'s museums contain extensive collections in a variety of styles. During the tour, you will have the opportunity to view interactive and historical exhibitions. The programme can also be combined with an ideal outdoor walk. The city\'s proximity to the coast adds a special atmosphere to the day-long programme. \"}'),
(323, 'en', 22, 'experiences', '{\"title\":\"Modern sightseeing in Malmö\",\"description\":\"Discover the modern face of Malmö, where urban maintenance and design solutions create a unique atmosphere. The city\'s green parks and innovative urban spaces are ideal for walking. The atmosphere of local street art and coffee houses offers a special experience. The city combines a youthful vibe with its proximity to the coast and harbours. Ideal for a multi-day city break or a relaxing programme.\"}'),
(324, 'en', 70, 'experiences', '{\"title\":\"Visit to Malmö\'s museums and historic castles\",\"description\":\"Discover Malmö\'s cultural side at Malmö Museum, whose exhibitions showcase the city\'s technical, historical and natural heritage. The museum\'s main venue is the historic Malmö Castle complex, which houses archaeological and maritime collections, among other things. In addition to the exhibitions, take a stroll through the landscaped castle gardens and learn about the city\'s history. Malmö is an exciting combination of past and present culture. :contentReference[oaicite:2]{index=2}\"}'),
(325, 'en', 69, 'experiences', '{\"title\":\"Stockholm Modern Museum Tour\",\"description\":\"Visit Stockholm\'s exciting modern museums, where contemporary art and technology exhibitions await you. The city\'s cultural offerings consist of numerous collections, including historical, modern and interactive exhibitions. A walk between museums can be easily combined with a panoramic tour of the harbour or a gastronomic tasting tour of the city. This programme is an ideal urban cultural adventure for everyone. \"}'),
(326, 'en', 61, 'experiences', '{\"title\":\"Athens Ancient Museum\",\"description\":\"Visit one of Athens\' most famous museums, where you can see a wealth of artefacts from ancient Greek culture. The exhibits provide a detailed insight into everyday life and art in ancient times. There are restaurants and cafés near the museum, so a visit can easily be combined with a longer walk. An ideal programme for those who want to learn something new. \"}'),
(327, 'en', 41, 'experiences', '{\"title\":\"Walking tour of Rhodes Old Town\",\"description\":\"Discover Rhodes\' old town, a UNESCO World Heritage Site with historic walls, narrow streets and rich museum exhibitions. During your walk, the medieval streetscape and the remains of the knight\'s castle create a special atmosphere. The surrounding parks and cafés are ideal for relaxing. The local markets offer unique local products. This experience is a great combination of history and relaxation. \"}'),
(328, 'en', 20, 'experiences', '{\"title\":\"Beach holiday in Rhodes\",\"description\":\"Enjoy the relaxing atmosphere of Rhodes\' sandy beaches and crystal clear waters. The beaches are ideal for swimming, sunbathing and water sports. Bars and restaurants in the area offer Mediterranean flavours and refreshing drinks. The view of the sunset over the sea is an unforgettable experience. This programme is the perfect choice for those looking for a summer holiday.\"}'),
(329, 'en', 68, 'experiences', '{\"title\":\"Walking tour of Stockholm\'s Gamla Stan old town\",\"description\":\"Explore Stockholm\'s historic old town, Gamla Stan, where winding cobbled streets and old buildings meet modern city life. The area has played a central role in the architecture and history of the Swedish capital since the 13th century and includes many iconic buildings such as the Nobel Museum and the Royal Palace. Stroll through the main square, Stortorget, admire the old arcaded houses, and then sample local Swedish specialities in one of the cosy cafés. This experience combines history, culture and urban atmosphere. :contentReference[oaicite:1]{index=1}\"}'),
(330, 'en', 62, 'experiences', '{\"title\":\"Rhodes Water Sports Day\",\"description\":\"Enjoy the thrills of water sports on the island of Rhodes, where jet skiing, surfing and other water activities await you. The crystal clear sea and proximity to the shore provide ideal conditions for all ages. Local instructors will help you participate safely during the programme. After water sports, you can relax on the beach or on the terrace of a local taverna. This day offers active relaxation with a seaside experience. \"}'),
(331, 'en', 40, 'experiences', '{\"title\":\"Ancient port and agora of Athens\",\"description\":\"Discover Athens\' ancient harbour and the agora, where the centres of ancient life took place. The site is full of historical ruins and brings the stories of Greek mythology to life. The agora\'s communal space was always bustling with trade and conversation. Today, museums and exhibitions complete the experience. The programme is ideal for those interested in history. \"}'),
(332, 'en', 19, 'experiences', '{\"title\":\"Visit to the Acropolis in Athens\",\"description\":\"Visit Athens\' ancient hill, where the Acropolis stands, and admire the impressive remains of the Parthenon. The site has thousands of years of history and offers unparalleled panoramic views of the city. The tour, filled with the great stories of Greek mythology, is particularly exciting. The area is full of museums and outdoor markets where you can sample local delicacies. The experience offers a full day\'s programme for lovers of art and history.\"}'),
(333, 'en', 13, 'experiences', '{\"title\":\"Visit to the Eiffel Tower\",\"description\":\"Visit Paris\' iconic Eiffel Tower and enjoy panoramic views of the city from every level. The tower has a history spanning more than 130 years and is known throughout the world. The nearby Champ de Mars park is ideal for picnics. There are numerous cafés and restaurants in the vicinity of the tower. Watching the sunset from the observation deck is a particularly impressive experience.\"}'),
(334, 'en', 1, 'experiences', '{\"title\":\"Hagymatikum Thermal Bath experience\",\"description\":\"Discover one of Makó\'s most famous tourist attractions, the Hagymatikum Thermal Bath. The unique Makovecz-style building is a sight to behold in itself. The thermal pools and wellness facilities offer a full day of relaxation for all ages. Enjoy the wellness services, sauna park and thermal baths. It is the perfect choice for families, couples and groups of friends alike.\"}'),
(335, 'en', 54, 'experiences', '{\"title\":\"Evening stroll through the Louvre & exhibition\",\"description\":\"Stroll around the world-famous Louvre Museum in Paris, where the museum building and gardens are works of art in themselves. One of the world\'s largest and richest art collections is housed here, including a multitude of paintings and sculptures. The evening lighting gives the area a special atmosphere. The surrounding cafés and terraces offer an ideal place to relax. The walk provides both a historical and cultural experience. \"}'),
(336, 'en', 55, 'experiences', '{\"title\":\"Montmartre art walk\",\"description\":\"Discover the artistic quarter of Montmartre hill, where painters, galleries and charming streets await visitors. The area has a unique bohemian atmosphere, and the Sacré-Cœur Basilica offers panoramic views of Paris. Restaurants, cafés and small boutiques complete the experience. During the walk, you can learn about the city\'s artistic history and current creative life. Ideal for a daytime or evening activity. \"}'),
(337, 'en', 14, 'experiences', '{\"title\":\"Romantic stroll along the Seine\",\"description\":\"Enjoy a stroll along the Seine River in the heart of Paris, lined with bridges and historic buildings. Cafés and small boutiques dot the route. During your walk, you can stop near the Louvre or Notre Dame. This is an ideal romantic activity to combine with dinner at the end of the day. The charm of this place can be felt in every season.\"}'),
(338, 'en', 8, 'experiences', '{\"title\":\"Budapest Parliament Tour\",\"description\":\"Discover Budapest\'s iconic Parliament building on an exciting guided tour. Its neo-Gothic interior impresses every visitor. You can see the coronation jewels and rare historical relics. During the tour, you will learn many interesting facts about Hungarian history. Due to high demand, advance booking is recommended.\"}'),
(339, 'en', 9, 'experiences', '{\"title\":\"Danube evening cruise\",\"description\":\"Experience Budapest\'s magical evening panorama on a boat trip on the Danube. The illuminated Chain Bridge, Parliament and Buda Castle offer a magnificent view. Food and drinks are available on board. The programme offers a romantic atmosphere for couples and groups of friends alike. Excellent photo opportunities in every direction.\"}'),
(340, 'en', 10, 'experiences', '{\"title\":\"Walking tour of the Buda Castle District\",\"description\":\"Stroll through the streets of the historic Buda Castle District, where medieval walls and ramparts tell tales of centuries past. The view of the city and the Danube is unique. Among the sights are the Fisherman\'s Bastion and Matthias Church. The area is full of museums and cosy cafés. Ideal for a cultural and relaxing day.\"}'),
(341, 'en', 11, 'experiences', '{\"title\":\"Walking tour of Szeged city centre\",\"description\":\"Discover Szeged\'s sunny city centre, famous Art Nouveau buildings and spacious squares. The spectacular cathedral on Dóm Square offers a unique photo opportunity. During your walk, you can discover local cafés, parks and cultural venues. The city\'s gastronomy is also worth trying, with its local specialities. The quiet streets are ideal for a pleasant afternoon outing.\"}'),
(342, 'en', 33, 'experiences', '{\"title\":\"Budapest sightseeing bike tour\",\"description\":\"Discover Budapest\'s sights on two wheels during a guided bike tour. The route includes the Parliament, Buda Castle, the Danube riverbank and several other iconic locations. During the tour, you will also hear local stories and interesting facts about the city\'s past. Cycling allows you to discover more sights in less time. The pace is comfortable, ideal for beginners and city explorers alike. \"}'),
(343, 'en', 12, 'experiences', '{\"title\":\"Visit to the Great Church of Debrecen\",\"description\":\"Discover Debrecen\'s historical gem, the Great Church, which is the symbol of the city. The interior of this enormous building is impressive and rich in religious heritage. The area around the church is ideal for walking and relaxing. Explore the local cultural quarter and cafés. The city also offers other attractions for visitors.\"}'),
(344, 'en', 32, 'experiences', '{\"title\":\"Széchenyi Thermal Bath and Wellness Centre\",\"description\":\"Experience the relaxing atmosphere of Budapest\'s famous thermal bath, the Széchenyi Bath, one of Europe\'s largest spa complexes. The neo-baroque building\'s medicinal pools and wellness services offer a whole day of relaxation. The bath also offers saunas, steam baths and massage services. The special atmosphere of the place is loved by locals and tourists alike. After bathing, it is worth trying a traditional Hungarian restaurant in the area. \"}'),
(345, 'en', 34, 'experiences', '{\"title\":\"Budapest food market tasting\",\"description\":\"Visit Budapest\'s famous Great Market Hall, where you\'ll find a wide variety of local products, cheeses and foods. There are also restaurants at the top of the market where you can sample traditional Hungarian dishes. Discover the local cuisine and traditional Hungarian flavours. Strolling around the market, you can discover other local restaurants and cafés. An ideal gastronomic experience after a day of sightseeing. \"}'),
(346, 'en', 47, 'experiences', '{\"title\":\"Evening stroll across the Chain Bridge in Budapest\",\"description\":\"Walk across the world-famous Széchenyi Chain Bridge, which connects the two banks of the Danube, Buda and Pest. It is one of Budapest\'s most famous icons, which is particularly atmospheric in the evening with the illuminated city and riverbank. The history of the bridge dates back to the 1840s, and today it serves as a symbol of the city. Walk across it while admiring the city\'s panorama and main attractions. The area is full of restaurants and cafés for a pleasant evening out. \"}'),
(347, 'en', 48, 'experiences', '{\"title\":\"Buda Castle and Royal Palace\",\"description\":\"Visit the historic Buda Castle, where the Royal Palace and the castle district offer a wealth of historical memories. The complex also includes the Hungarian National Gallery and the Budapest History Museum. The castle terraces offer wonderful views of the Danube and the Pest side of the city. The site is a UNESCO World Heritage Site, making it both a cultural and historical experience. Discover medieval and Baroque architecture and stroll along the castle walls. \"}'),
(348, 'en', 50, 'experiences', '{\"title\":\"Memento Park open-air museum\",\"description\":\"Discover one of Budapest\'s unique museums, Memento Park, where statues and monuments erected during the communist era await you in an open-air exhibition. The park evokes a historical period when memorabilia from the socialist system was collected here. Visit the imposing statues of Lenin and Marx, which highlight the power of the past and the importance of democracy. The site presents the social history of the past era in an interactive way. An ideal programme for those interested in history. :contentReference[oaicite:2]{index=2}\"}'),
(349, 'en', 49, 'experiences', '{\"title\":\"St. Stephen\'s Basilica & Lookout Tower\",\"description\":\"Discover Budapest\'s third largest church, St. Stephen\'s Basilica, which is also one of the most beautiful neoclassical buildings. Inside the basilica, you can see the right hand of St. Stephen, the first king of Hungary. The tower offers a 360° panoramic view of the city, which is particularly spectacular at sunset. The church regularly hosts organ concerts, which are well worth experiencing. This venue offers both a historical and spiritual experience. :contentReference[oaicite:1]{index=1}\"}'),
(350, 'en', 51, 'experiences', '{\"title\":\"Gellért Hill Cave & Viewpoint\",\"description\":\"Visit the Gellért Hill Cave, a natural cave system located at one of the most beautiful panoramic spots in the city. The history of the cave is linked to the legend of a hermit, where you can also learn about the healing power of nature. The top of the hill offers a magnificent view of the Danube and the city. In addition to the cave, the Gellért Baths and the surrounding area also offer excellent opportunities for relaxation. The excursion combines nature, history and city panoramas. :contentReference[oaicite:3]{index=3}\"}'),
(351, 'en', 52, 'experiences', '{\"title\":\"Szeged Cathedral Square concert & walk\",\"description\":\"Visit Szeged\'s Cathedral Square for an evening stroll and concert, where the city\'s famous main square offers a special atmosphere. The monumental cathedral and the architecture of the surrounding area offer a unique sight. Classical and light music evenings are often held in the square or on nearby stages. During the programme, you can enjoy the architectural beauty of the city and the local cultural life. There are also cosy cafés and restaurants along the square. \"}'),
(352, 'en', 7, 'experiences', '{\"title\":\"Walk along the Danube in Linz\",\"description\":\"Take a pleasant stroll along the banks of the Danube in Linz, where modern and historic architecture meet. Cafés and viewing points await visitors along the banks of the Danube. The riverside promenade is ideal for picnics or relaxation. The city\'s arts district is also worth a visit. During the walk, you can get to know the culture and atmosphere of Linz.\"}'),
(353, 'en', 6, 'experiences', '{\"title\":\"Schönbrunn Palace and Gardens\",\"description\":\"Discover the magnificent rooms of Schönbrunn Palace, reminiscent of the former residence of the Austrian imperial family. The Baroque gardens and parks are the perfect place for a relaxing stroll. Visit the palace zoo, one of the oldest in Europe. The panorama from the garden offers a wonderful view of Vienna. The programme includes photo stops and a guided tour.\"}'),
(354, 'en', 27, 'experiences', '{\"title\":\"Vienna Christmas Market\",\"description\":\"If you are visiting Vienna between late November and December, don\'t miss the famous Christmas markets, where dozens of craft stalls await you with traditional gifts and delicacies. At the market held at Rathausplatz, you can sample local foods, mulled wine and festive handicrafts. Live music, lights and family programmes make the atmosphere unforgettable. The markets can be found in several locations throughout the city, so they can easily be incorporated into a wider day of sightseeing. The Christmas hustle and bustle is one of the highlights of Vienna\'s cultural tradition. \"}'),
(355, 'en', 53, 'experiences', '{\"title\":\"Debrecen Nagyerdei Adventure Park\",\"description\":\"Discover the green heart of Debrecen, the Nagyerdő, where outdoor programmes and an adventure park await visitors. Walking in the park, you will find plenty of places to rest and cultural events to enjoy. Child-friendly games and sports facilities make this place special. The Great Forest often hosts music events and cultural fairs. It is an ideal place for relaxation with family or friends. \"}'),
(356, 'en', 5, 'experiences', '{\"title\":\"Viennese classical music evening\",\"description\":\"Immerse yourself in Vienna\'s world-famous music scene with a classical concert featuring works by Mozart, Strauss and other great artists. The wonderful acoustics and décor of the historic concert hall make for a memorable experience. Before the concert, take a stroll through the charming streets of the neighbourhood. Enjoy local pastries and coffees in the city\'s coffee houses. An ideal programme for lovers of culture and music.\"}'),
(357, 'en', 26, 'experiences', '{\"title\":\"Vienna Prater amusement park experience\",\"description\":\"The Vienna Prater amusement park is a legendary entertainment area in Vienna, where people of all ages can find attractions to suit their tastes. The park\'s iconic Ferris wheel, the Riesenrad, offers a unique panorama of the city that is not to be missed. The amusement park has numerous roller coasters, games and restaurants, offering visitors a whole day of entertainment. With a history dating back more than a century, it is not only a place of entertainment but also a historical experience. It is ideal for families and groups of friends alike, for daytime or evening activities.\"}'),
(358, 'en', 31, 'experiences', '{\"title\":\"Art galleries in Vienna\",\"description\":\"Vienna has a rich museum and gallery culture, where classical and modern art meet. Visit the city\'s famous museums, where paintings, sculptures and exhibitions await visitors. The Kunsthistorisches and Albertina collections are particularly exciting for those interested in the arts. Walking through the galleries, you can also learn about the art collection of the Habsburg rulers. The programme can be a full-day cultural addition to a city tour. \"}'),
(359, 'en', 46, 'experiences', '{\"title\":\"Warsaw Historical Museum\",\"description\":\"Visit Warsaw\'s historical museum, where you can learn about the rich history of the Polish capital and its surroundings. The exhibitions provide a detailed overview of the city\'s development from the Middle Ages to the present day. The museum\'s interior is modern and interactive. While walking around the area, you can easily visit other historical sites. The programme is ideal for those interested in history. \"}'),
(360, 'en', 44, 'experiences', '{\"title\":\"Oslo fjord sunset tour\",\"description\":\"Discover Oslo\'s famous fjord on a boat trip at sunset, where the meeting of the landscape and the sea gives the tour a special atmosphere. Along the fjord, you can enjoy the magnificent views of Norwegian nature, while also taking in the panorama of the city. The programme is ideal for a romantic evening or a family outing. Coffee and local snacks are available on board. It is an exciting combination of nature and city experiences. \"}'),
(361, 'en', 23, 'experiences', '{\"title\":\"Oslo fjord tour\",\"description\":\"Visit Oslo\'s famous fjord and enjoy the proximity of Norwegian nature in an urban environment. You can explore the fjord\'s panoramic views and unique bays on a boat trip. During tours along the fjord, visitors can also enjoy cafés and restaurants overlooking the water. The clean air and mountain views offer an unforgettable experience. The full-day programme is ideal for combining nature and city life.\"}'),
(362, 'en', 67, 'experiences', '{\"title\":\"Warsaw gastronomy & sightseeing\",\"description\":\"Discover Warsaw\'s historic centre with a gastronomic and sightseeing programme that combines local restaurants, food tastings and walks. You can also visit the city\'s historic squares and parks. During the programme, you will learn about the specialities of Polish cuisine and visit local markets. This experience is the ideal combination of culinary and urban exploration. \"}'),
(363, 'en', 76, 'experiences', '{\"title\":\"Warsaw Modern Art Gallery\",\"description\":\"Discover Warsaw\'s vibrant modern art scene with a visit to a gallery showcasing contemporary Polish and international works. The diversity and creative atmosphere of the exhibitions offer an inspiring experience for all art lovers. The restaurants and cafés in the neighbourhood provide further opportunities for cultural exploration. \"}'),
(364, 'en', 25, 'experiences', '{\"title\":\"Warsaw\'s historic centre\",\"description\":\"Explore Warsaw\'s historic city centre, where visitors can enjoy newly renovated old town squares and cafés. Local museums offer a wealth of information about the city\'s rich history. Take a stroll and discover the royal palace and the remains of the city walls. The flavours of Polish cuisine and local wines are the perfect complement to the programme. Ideal for a combination of sightseeing and relaxation.\"}'),
(365, 'en', 75, 'experiences', '{\"title\":\"Royal Castle and Park in Warsaw\",\"description\":\"Visit the Royal Castle in Warsaw, where fascinating reminders of Polish history and royal life await you. The palace\'s beautiful halls, ornate rooms and surrounding parks provide the ideal setting for a long city walk. There are plenty of restaurants and cafés in the area, so you can easily plan a whole day\'s programme. This experience adds a historical and cultural dimension to your city tour. \"}'),
(366, 'en', 65, 'experiences', '{\"title\":\"Oslo Opera House & fjord panorama\",\"description\":\"Visit Oslo\'s iconic Opera House, which impresses with its modern architecture and offers panoramic views of the fjord. Climb up to the roof terrace for a magnificent view of the fjord and the city. During the programme, take a stroll along the waterfront promenades. The areas in front of the opera house are perfect for a picnic or watching the sunset. This experience combines modern architecture with natural panoramas. \"}'),
(367, 'en', 71, 'experiences', '{\"title\":\"Oslo fjord area\",\"description\":\"Enjoy the peaceful atmosphere of the Oslo Fjord promenade, where the seaside meets modern city life. The promenade is the ideal place for a romantic evening or an outing with friends, while the city panorama and proximity to the water add a special atmosphere to your urban adventure. There are numerous restaurants and cafés in the area offering local specialities. This programme combines natural beauty with an urban experience. \"}'),
(368, 'en', 72, 'experiences', '{\"title\":\"Oslo Scandinavian gastro tour\",\"description\":\"Immerse yourself in Oslo\'s food culture on a city tour showcasing local flavours. Try Norwegian specialities, fresh fish dishes and traditional fare in restaurants along the fjord. The food tour will take you to local markets and modern bistros. This programme offers a unique combination of culinary experiences and urban exploration. \"}'),
(369, 'en', 15, 'experiences', '{\"title\":\"Berlin historical sightseeing\",\"description\":\"Discover Berlin\'s historic centre, which showcases both modern and historical landmarks. The Brandenburg Gate, the remains of the Berlin Wall and the Reichstag building are all significant attractions. The city\'s numerous museums and parks offer a full day\'s programme. The local cuisine reflects Berlin\'s unique character. An ideal city break for families and friends alike.\"}'),
(370, 'en', 36, 'experiences', '{\"title\":\"Berlin street art walk\",\"description\":\"Discover the alternative side of Berlin on a guided street art walk, where you can learn about the city\'s famous murals and graffiti culture. During the tour, you will gain an insight into contemporary Berlin culture through the works of local artists. The walk also takes you to districts where creative communities and cafés are located. The programme is an interactive and inspiring experience for anyone interested in art. After the tour, it\'s worth relaxing in a local café. \"}'),
(371, 'en', 35, 'experiences', '{\"title\":\"Berlin Museum Island Day\",\"description\":\"Berlin\'s famous Museum Island welcomes all art and history enthusiasts with its world-renowned collections. It includes several iconic museums housing works of art and historical exhibitions. The site is part of a UNESCO World Heritage Site, so a visit can be a full-day programme. The collections include both ancient and modern works. Together with the cafés and parks in the area, an excellent cultural experience awaits. \"}'),
(372, 'en', 56, 'experiences', '{\"title\":\"Berlin Brandenburg Gate evening photo shoot\",\"description\":\"Visit Berlin\'s famous Brandenburg Gate during an evening stroll, when the illuminated monument is particularly impressive. This gate is one of the city\'s most recognisable symbols, evoking important moments in German history. There are also numerous restaurants and bars in the area where you can relax. In addition to taking photos, you can also hear stories about the history of the place on a guided walk. Berlin\'s dynamic atmosphere can be felt at any time of year. \"}'),
(373, 'en', 57, 'experiences', '{\"title\":\"Berlin Panorama Lookout Tower\",\"description\":\"Discover Berlin\'s best panoramic view from a modern viewing terrace overlooking the entire city. The observation deck is famous for the unique light it casts over the cityscape at sunset. The programme combines sightseeing and photography, while allowing you to discover Berlin\'s diverse architecture. The area around the observation deck also offers visitors shops and cafés. Ideal for young people and families alike. \"}'),
(374, 'en', 16, 'experiences', '{\"title\":\"Munich beer culture tour\",\"description\":\"Discover Munich\'s famous beer culture with a visit to a traditional brewery and tasting. Bavarian beers are world-famous, and the authentic atmosphere is provided by the local beer gardens. During the tour, an expert guide will tell you about the history and traditions of beer brewing. You can discover even more sights as you walk through the city\'s historic squares and parks. An excellent experience for groups of friends or beer lovers.\"}'),
(375, 'en', 17, 'experiences', '{\"title\":\"Exploring the Roman Colosseum\",\"description\":\"Discover one of the most famous historical monuments of ancient Rome, the Colosseum. The huge amphitheatre evokes memories of gladiator games. During the guided tour, detailed stories will make the experience even more memorable. The nearby Roman Forum and Palatine Hill are also waiting to be explored. An ideal programme for those interested in history.\"}'),
(376, 'en', 18, 'experiences', '{\"title\":\"Walk through Milan\'s fashion district\",\"description\":\"Discover Milan\'s fashion district, dominated by global brands, where shops offering the latest trends line the streets. During your walk, you will also pass by Piazza del Duomo and elegant shopping streets. Local cafés and designer shops offer an excellent programme for shoppers and visitors alike. The city\'s cultural and historical sites are accessible on foot or by public transport. The unique blend of fashion and history will impress every visitor.\"}'),
(377, 'en', 37, 'experiences', '{\"title\":\"Roman Forum and Palatine Hill\",\"description\":\"Visit the heart of ancient Rome, where the ruins of the Forum and Palatine Hill await visitors. These sites were the centres of political and social life in ancient Rome. During the walks, you can learn about the fascinating details of ancient architecture and culture. The site also offers panoramic views of the city. A historical and cultural experience in one. \"}'),
(378, 'en', 58, 'experiences', '{\"title\":\"Visit to the Pantheon in Rome\",\"description\":\"Visit the Pantheon in Rome, one of the best-preserved works of ancient Roman architecture. The dome of the building offers unique acoustics and light effects. The interior also houses several historical tombs. The Pantheon is a monument to architectural excellence and ancient culture. The restaurants and cafés in the surrounding area complete the visit. \"}'),
(379, 'en', 39, 'experiences', '{\"title\":\"Milan Fashion Week\",\"description\":\"Visit Milan\'s famous fashion district, where global brands and elegant shops line the streets. This experience offers you the opportunity to gain insight into the world of fashion culture. The proximity of Piazza del Duomo and Galleria Vittorio Emanuele II complements the programme with iconic architectural sights. After the walk, an Italian café is the ideal place to relax. This day is the perfect programme for fashion lovers and stylish sightseers. \"}'),
(380, 'en', 38, 'experiences', '{\"title\":\"Naples beach evening programme\",\"description\":\"Enjoy the evening atmosphere of Naples\' seafront, where restaurants, bars and promenades await visitors. The seaside promenade adds a special Mediterranean atmosphere to sightseeing. The view of the sunset towards Vesuvius is breathtaking. The area is full of gelato bars and local pizzerias offering authentic pizza. This experience is ideal for a romantic dinner or an evening out with friends. \"}'),
(381, 'en', 59, 'experiences', '{\"title\":\"Naples & Vesuvius Panorama Tour\",\"description\":\"Discover the city of Naples and its surroundings on a panoramic tour, where you can also enjoy views of the famous Mount Vesuvius volcano. The Mediterranean atmosphere of the area and the proximity of the coast make this programme truly special. During the tour, visit historical sites and viewpoints. The view around Vesuvius is particularly impressive at sunset. The day can be rounded off with a tour and relaxation on the beach. \"}'),
(382, 'en', 60, 'experiences', '{\"title\":\"Milan Cathedral\",\"description\":\"Visit one of Milan\'s most famous landmarks, the Milan Cathedral, a huge Gothic-style cathedral. Climb up to the roof terrace for a fantastic view of the city and the surrounding countryside. The interior decoration and sculptures of the church are equally impressive. There are plenty of cafés and small shops in the area for visitors to enjoy. This is a memorable experience from both a historical and cultural point of view. \"}'),
(383, 'en', 29, 'experiences', '{\"title\":\"An evening at the Prague National Theatre\",\"description\":\"Enjoy classic Czech culture at one of the performances at Prague\'s National Theatre, where opera, ballet and drama await the audience. The ornate interiors and excellent acoustics of the historic building add to the experience. Performances by local artists and guest performers offer an unforgettable experience for locals and visitors alike. The programme is aimed at both those committed to the arts and those seeking new cultural experiences. Book your tickets in advance for the best seats. \"}'),
(384, 'en', 3, 'experiences', '{\"title\":\"Prague Castle and St. Vitus Cathedral\",\"description\":\"Visit Prague\'s most famous historical complex, where you can learn about centuries of history. The imposing Gothic architecture and detailed decoration of St. Vitus Cathedral are impressive. Walk along the castle walls and admire the panoramic view of the city. There are also museums and parks in the area. The experience is enriched by photo-friendly locations that make sightseeing even more enjoyable.\"}'),
(385, 'en', 2, 'experiences', '{\"title\":\"Sightseeing in Prague\'s Old Town\",\"description\":\"Discover Prague\'s historic Old Town on a detailed walking tour, where cobbled streets and historic buildings tell the story of the city\'s past. Visit Old Town Square, the Orloj astronomical clock and the nearby village-like alleyways. During the experience, you will learn about local stories and legends. Prague\'s unique atmosphere is made unforgettable by its cafés and puppeteers. At the end of the day, sample Czech cuisine specialities at a local restaurant.\"}'),
(386, 'en', 30, 'experiences', '{\"title\":\"Prague beer tasting tour\",\"description\":\"Discover Prague\'s beer culture on a guided beer tasting tour, where you will visit several local pubs. The Czech Republic is famous for its excellent beer, and this tour gives you the opportunity to taste several different styles in one evening. The guides will tell you about the history of beer brewing and local traditions. The tour is ideal for groups of friends or as a unique gastronomic experience. In addition to the walk, we also recommend sampling some local delicacies. \"}'),
(387, 'en', 4, 'experiences', '{\"title\":\"Vltava boat trip\",\"description\":\"Hop aboard a riverboat and enjoy the sights of Prague from the Vltava River. Charles Bridge, the city skyline and riverside buildings will reveal themselves from a whole new perspective. The on-board guide will regale you with interesting stories about the city. The sunset is particularly romantic from the deck. Combine the experience with dinner for a full day\'s programme.\"}'),
(388, 'en', 28, 'experiences', '{\"title\":\"Evening stroll across Charles Bridge in Prague\",\"description\":\"Walk across the historic Charles Bridge, built in the 14th century and now one of Prague\'s most famous landmarks. Even without a guided tour, the bridge offers beautiful views of the Vltava River and the city skyline, which are particularly impressive at sunset. Street artists and musicians along the bridge add to the authentic Prague atmosphere. The narrow streets and cosy cafés in the area are a great addition to an evening programme. This walk is the perfect start to exploring Prague\'s history. \"}'),
(389, 'en', 82, 'experiences', '{\"title\":\"Brno music & event evening\",\"description\":\"Take part in a local music night in Brno, where concerts and events by local performers await you in the city\'s cultural space. The combination of cosy venues and bars provides the ideal evening programme. This local experience offers an authentic insight into Brno\'s musical and cultural life and provides visitors with an unforgettable experience.\"}'),
(390, 'en', 45, 'experiences', '{\"title\":\"Helsinki Museum Day\",\"description\":\"Visit Helsinki\'s art and history museums, where a rich collection of Finnish culture and history awaits visitors. The museums are close to each other, so you can easily spend a whole day visiting them. The exhibitions include interactive elements and local historical details. You can round off your day at the museum with a walk along the seafront or a visit to one of the local cafés. This is an ideal activity even in bad weather. \"}'),
(391, 'en', 66, 'experiences', '{\"title\":\"Helsinki seaside walk\",\"description\":\"Explore Helsinki\'s seaside promenades, where the sea air and landscaped walking paths offer ideal conditions for relaxation and sightseeing. Along the waterfront promenade, you will find small restaurants and cafés where you can sample local specialities. This is a pleasant daytime activity that combines nature and the city experience. \"}'),
(392, 'en', 73, 'experiences', '{\"title\":\"Helsinki design walk\",\"description\":\"Helsinki is a stronghold of Nordic design and modern architecture, which is best explored on foot. The city\'s unique buildings and standard design examples showcase Scandinavian creativity. During your walks, you can visit local design museums, galleries and boutiques. This cultural experience combines creativity, city parks and seaside panoramas. \"}'),
(393, 'en', 80, 'experiences', '{\"title\":\"České Budějovice Iron Maiden Tower\",\"description\":\"Discover Iron Maiden Tower, a medieval prison and fortified section where historical weapons and exhibitions await you. The tower once served to defend the city, but today it offers visitors an exciting cultural programme. The surrounding old town and cafés are ideal for a long afternoon stroll. :contentReference[oaicite:5]{index=5}\"}'),
(394, 'en', 24, 'experiences', '{\"title\":\"Helsinki design sightseeing\",\"description\":\"Discover Helsinki\'s modern design culture, world-renowned for its architecture and creative spaces. The city\'s sleek buildings, galleries and museums offer an inspiring experience. While walking around, visit the local design shops and cafés. The seaside promenades and parks provide a peaceful atmosphere for relaxation. In Helsinki, culture and nature come together in harmony. \"}'),
(395, 'en', 81, 'experiences', '{\"title\":\"Brno gastronomy & sightseeing\",\"description\":\"Discover Brno\'s cosy restaurants and cafés on a local gastronomic tour while getting to know the historic centre of the city. During the walk, you can taste local specialities while admiring the city\'s historic squares and buildings. This experience is ideal for both gastronomic and urban exploration. \"}'),
(396, 'en', 79, 'experiences', '{\"title\":\"České Budějovice Black Tower kilátó\",\"description\":\"Visit the historic Black Tower lookout in České Budějovice, one of the city\'s most distinctive landmarks. The tower was built in the 16th century for defensive purposes and today offers panoramic views of the city. The nearby medieval buildings and charming streets provide the ideal setting for exploring the city. The lookout tower offers a breathtaking panorama from the top of the city. :contentReference[oaicite:4]{index=4}\"}'),
(397, 'en', 74, 'experiences', '{\"title\":\"Helsinki sunset boat trip\",\"description\":\"Discover Helsinki\'s coastal panorama on a sunset boat trip, where the view of the city from the water offers a unique experience. You can also sample local snacks in the on-board café while the setting sun illuminates the harbour and the city. This programme is ideal as both a romantic experience and a city break. \"}'),
(398, 'en', 77, 'experiences', '{\"title\":\"Historical walk through Bratislava\'s Old Town\",\"description\":\"Discover Bratislava\'s historic Old Town, where medieval streets, charming squares and a rich architectural heritage await you. The Main Square and the old town hall add a special atmosphere to your day-long walk. Learn about the history and legends of the city with a guided tour or on your own. The walk is an ideal programme for a longer city break. :contentReference[oaicite:3]{index=3}\"}'),
(399, 'en', 78, 'experiences', '{\"title\":\"Bratislava music evenings & cultural programme\",\"description\":\"Take part in a cultural evening in Bratislava, where you can enjoy a classical music concert or a local jazz evening. The programme combines performances by local musicians with the city\'s atmospheric ambience, making it ideal for an evening of relaxation. This experience can be easily combined with dinner or sightseeing. \"}'),
(400, 'ja', 37, 'experiences', '{\"title\":\"ローマフォーラムとパラティーノの丘\",\"description\":\"ローマ古代世界の中心地を訪れてみてください。フォロ・ロマーノとパラティーノの丘の遺跡が訪問者を待っています。これらの場所は、古代ローマの政治と社会生活の中心地でした。散策しながら、古代建築と文化の魅力的な詳細を知ることができます。 この場所からは、街のパノラマビューも楽しめます。歴史と文化の両方を体験できる場所です。\"}'),
(401, 'ja', 58, 'experiences', '{\"title\":\"ローマのパンテオン訪問\",\"description\":\"ローマにあるパンテオンを訪れてみてください。古代ローマ建築の中で最も保存状態の良い建築物の一つです。 この建物のドームは、独特の音響効果と光の演出を楽しめます。内部には、いくつかの歴史的な墓碑があります。パンテオンは、建築の卓越性と古代文化の記念碑です。周辺にはレストランやカフェもあり、訪問を充実させてくれます。\"}'),
(402, 'ja', 39, 'experiences', '{\"title\":\"ミラノ・ファッションウィーク\",\"description\":\"世界的なブランドやエレガントなショップが軒を連ねる、ミラノの有名なファッション地区を訪れてみてください。この体験は、世界のファッション文化を垣間見る機会となるでしょう。 ドゥオーモ広場とヴィットーリオ・エマヌエーレ2世ガレリアが近くにあるので、象徴的な建築物も楽しめるよ。散歩の後は、イタリアンカフェで休憩するのがベスト。この日は、ファッション好きやスタイリッシュな観光好きにぴったりのプランだね。\"}'),
(403, 'ja', 18, 'experiences', '{\"title\":\"ミラノのファッション地区を散策\",\"description\":\"ミラノの世界的なブランドがひしめくファッション地区を探索し、最新トレンドを取り入れたショップが軒を連ねる通りを散策しましょう。ドゥオーモ広場やエレガントなショッピングストリートも道中にあるでしょう。地元のカフェやデザイナーショップは、買い物客や観光客に素晴らしい体験を提供しています。 街の文化や歴史的なスポットは、徒歩や公共交通機関でアクセスできます。ファッションと歴史が融合したこの街は、訪れる人を魅了すること間違いなしです。\"}'),
(404, 'ja', 38, 'experiences', '{\"title\":\"ナポリの海岸での夜のプログラム\",\"description\":\"レストラン、バー、遊歩道が訪れる人々を待っているナポリの海岸の夜の雰囲気を楽しんでください。 海岸沿いの遊歩道は、街歩きに特別な地中海の雰囲気を与えてくれます。ヴェスヴィオ山に向かって沈む夕日は圧巻です。このエリアには、ジェラートバーや本格的なピザを提供する地元のピッツェリアがたくさんあります。この体験は、ロマンチックなディナーや友人との夜のプログラムに最適です。\"}'),
(405, 'ja', 17, 'experiences', '{\"title\":\"ローマのコロッセオの発見\",\"description\":\"古代ローマで最も有名な歴史的建造物の一つ、コロッセオを発見してください。この巨大な円形劇場は、剣闘士の試合の記憶を呼び起こします。ガイド付きツアーでは、詳細な物語が体験をさらに深めます。近くのフォロ・ロマーノとパラティーノの丘も発見を待っています。 歴史に興味のある方に理想的なプログラムです。\"}'),
(406, 'ja', 59, 'experiences', '{\"title\":\"ナポリ＆ベスビオ山パノラマツアー\",\"description\":\"ナポリの街とその周辺を、有名なヴェスヴィオ火山も眺められるパノラマツアーで探検しよう。この地域の地中海の雰囲気と海岸の近さが、このツアーを特別なものにしている。 ツアーでは、歴史的な場所や展望スポットも訪れます。ヴェスヴィオ山周辺の景色は、特に夕陽が沈む時間帯に素晴らしいです。このツアーは、日帰り旅行や海辺でのリラクゼーションと組み合わせることもできます。\"}'),
(407, 'ja', 60, 'experiences', '{\"title\":\"ミラノ大聖堂\",\"description\":\"ミラノで最も有名な観光名所の一つ、ミラノ大聖堂を訪れてみてください。この巨大なゴシック様式の大聖堂は、屋上テラスから街と周辺の風景を一望できる素晴らしい眺めを楽しめます。教会の内部装飾と彫像も同様に圧巻です。 周辺には、たくさんのカフェや小さなお店が訪れを待っています。この体験は、歴史的にも文化的にも、忘れられないものになるでしょう。\"}'),
(408, 'ja', 76, 'experiences', '{\"title\":\"ワルシャワ現代美術ギャラリー\",\"description\":\"ワルシャワの活気あふれる現代アートシーンを、ポーランドおよび国際的な現代作品が展示されているギャラリーで発見しましょう。多様性に富んだ創造的な展示は、アート愛好家すべてに刺激的な体験を提供します。周辺にあるレストランやカフェでは、さらなる文化的な発見を楽しむことができます。\"}'),
(409, 'ja', 67, 'experiences', '{\"title\":\"ワルシャワのグルメ＆観光\",\"description\":\"ワルシャワの歴史的中心部を、地元のレストラン、料理試食、散策が交互に繰り広げられるグルメ＆シティツアーで発見しましょう。 街の歴史的な広場や公園も訪れます。このプログラムでは、ポーランド料理の特色や地元の市場について知ることができます。これは、グルメと街探検を理想的に組み合わせた体験です。\"}'),
(410, 'ja', 19, 'experiences', '{\"title\":\"アテネのアクロポリス訪問\",\"description\":\"アクロポリスが立つアテネの古代の丘を訪れ、パルテノン神殿の印象的な遺跡を鑑賞してください。 この場所は数千年の歴史を秘めており、街を一望できるパノラマは他では味わえないものです。ギリシャ神話の素晴らしい物語に満ちたツアーは、特にエキサイティングです。周辺には博物館や屋外マーケットがたくさんあり、地元のグルメを味わうことができます。この体験は、芸術や歴史を愛する人たちに、1日楽しめるプログラムを提供しています。\"}'),
(411, 'ja', 46, 'experiences', '{\"title\":\"ワルシャワ歴史博物館\",\"description\":\"ワルシャワ歴史博物館を訪れて、ポーランドの首都とその周辺の豊かな歴史について学んでみて。 展示は、中世から現代までの都市の発展を詳しく紹介しています。博物館の内部はモダンでインタラクティブです。周辺を散策すると、その他の歴史的な場所も簡単に訪れることができます。このプログラムは、歴史に興味のある方に最適です。\"}'),
(412, 'ja', 25, 'experiences', '{\"title\":\"ワルシャワの歴史的中心部\",\"description\":\"ワルシャワの歴史的な中心街を探索しましょう。再建された旧市街の広場やカフェが訪問者をお待ちしています。 この街の豊かな歴史については、地元の博物館で多くの情報を見ることができます。散策しながら、王宮や城壁の遺跡を発見してください。ポーランド料理の味と地元のワインがこのプログラムを完璧に彩ります。観光とリラクゼーションの両方に理想的な場所です。\"}'),
(413, 'ja', 75, 'experiences', '{\"title\":\"ワルシャワ王宮と公園\",\"description\":\"ワルシャワの王宮を訪れて、ポーランドの歴史と王室生活の魅力的な思い出に触れてみて。 宮殿の美しいホール、豪華な部屋、そして周囲の公園は、長い街歩きに理想的な場所です。周辺にはレストランやカフェが数多くあり、1日かけてのプランも簡単に立てられます。この体験は、街歩きに歴史的、文化的な側面を加えてくれるでしょう。\"}'),
(414, 'ja', 20, 'experiences', '{\"title\":\"ロードス島の海辺での休暇\",\"description\":\"ロードス島で、砂浜のビーチのくつろいだ雰囲気と透き通った海をお楽しみください。ビーチは、水泳、日光浴、ウォータースポーツに最適です。 周辺には、地中海料理や冷たい飲み物を楽しめるバーやレストランがあります。海に沈む夕日は、忘れられない体験となるでしょう。このプログラムは、夏の休暇を過ごすのに最適な選択肢です。\"}'),
(415, 'ja', 61, 'experiences', '{\"title\":\"アテネ古代博物館\",\"description\":\"アテネで最も有名な博物館のひとつを訪れて、古代ギリシャ文化の豊かな遺物を鑑賞しましょう。 展示品は、古代の日常生活や芸術を詳しく紹介しています。博物館の近くにはレストランやカフェがあるので、長い散歩と組み合わせても楽しめます。教養を深めたい方にぴったりのプログラムです。\"}'),
(416, 'ja', 41, 'experiences', '{\"title\":\"ロードス旧市街の散策\",\"description\":\"ユネスコの世界遺産に登録されている、歴史的な城壁、狭い通り、そして豊富な博物館の展示品があるロードス旧市街を探索しましょう。散策中は、中世の街並みや騎士団の城跡が特別な雰囲気を醸し出しています。周辺の公園やカフェは、くつろぐのに最適です。 地元の市場では、特別な地元産品が販売されています。この体験は、歴史とリラクゼーションが見事に融合したものです。\"}'),
(417, 'ja', 40, 'experiences', '{\"title\":\"アテネの古代港とアゴラ\",\"description\":\"古代アテネの港と、古代の生活の中心地であったアゴラを探索しましょう。この場所は歴史的な遺跡でいっぱいで、ギリシャ神話の物語を生き生きと伝えています。アゴラの公共広場は、常に商売や会話で賑わっていました。今日では、博物館や展示が体験をさらに充実させています。 このプログラムは、歴史に興味のある方に最適です。\"}');
INSERT INTO `translations` (`id`, `language_short_name`, `item_id`, `item_name`, `item`) VALUES
(418, 'ja', 62, 'experiences', '{\"title\":\"ロードス島ウォータースポーツの日\",\"description\":\"ロードス島では、ジェットスキー、サーフィン、その他のウォータースポーツなど、ウォータースポーツのスリルをお楽しみいただけます。透き通った海と海岸の近さは、あらゆる年齢層の方に理想的な条件を提供しています。プログラムでは、地元のインストラクターが安全に参加できるようサポートします。 ウォータースポーツの後は、海岸や地元のタベルナのテラスでくつろぐことができます。この日は、海辺でのアクティブなリラクゼーションをお楽しみいただけます。\"}'),
(419, 'ja', 13, 'experiences', '{\"title\":\"エッフェル塔訪問\",\"description\":\"パリの象徴であるエッフェル塔を訪れ、各階から街のパノラマビューをお楽しみください。130年以上の歴史を持つこの塔は世界的に有名です。近くのシャン・ド・マルス公園はピクニックに最適です。塔の周辺には、数多くのカフェやレストランがあります。 展望台からの夕日は、特に素晴らしい体験です。\"}'),
(420, 'ja', 14, 'experiences', '{\"title\":\"セーヌ川沿いのロマンチックな散歩\",\"description\":\"パリの中心部、橋や歴史的建造物が立ち並ぶセーヌ川沿いの散歩をお楽しみください。カフェや小さなブティックが道沿いに点在しています。散歩の途中で、ルーブル美術館やノートルダム大聖堂の近くで立ち寄ることもできます。夕方のディナーと組み合わせれば、理想的なロマンチックなプログラムになります。この場所の魅力は、どの季節でも感じることができます。\"}'),
(421, 'ja', 54, 'experiences', '{\"title\":\"ルーブル美術館の夜の散歩＆展示会\",\"description\":\"世界的に有名なルーブル美術館の周辺をパリで散策しましょう。美術館の建物と庭園はそれ自体が芸術作品です。世界最大かつ最も豊富な美術コレクションがここにあり、数多くの絵画や彫刻が収蔵されています。 夕方のイルミネーションは、この周辺に特別な雰囲気を醸し出しています。周辺のカフェやテラスは、くつろぐのに理想的な場所です。この散歩は、歴史と文化の両方を体験できるものです。\"}'),
(422, 'ja', 1, 'experiences', '{\"title\":\"ハギマティクム温泉体験\",\"description\":\"マコで最も有名な観光名所の一つ、ハギマティクム温泉を発見してください。マコヴェッツ様式のユニークな建物は、それ自体が特別な光景を提供しています。 温泉プールとウェルネスエリアでは、あらゆる年齢層の方々に一日中リラックスしていただけます。ウェルネスサービス、サウナパーク、温泉浴場をお楽しみください。ご家族、カップル、ご友人同士に最適な場所です。\"}'),
(423, 'ja', 8, 'experiences', '{\"title\":\"ブダペスト議会ツアー\",\"description\":\"エキサイティングなガイドツアーで、ブダペストの象徴的な国会議事堂を見学しましょう。ネオゴシック様式の内部は、訪れる人を皆魅了します。戴冠式の宝石や貴重な歴史的遺物もご覧いただけます。ツアーでは、ハンガリーの歴史について多くの興味深い事実を知ることができます。人気が高いため、事前予約をお勧めします。\"}'),
(424, 'ja', 55, 'experiences', '{\"title\":\"モンマルトルの芸術散歩\",\"description\":\"モンマルトルの丘にある芸術地区を探索しましょう。画家、ギャラリー、そして雰囲気のある通りが訪問者を待っています。 この場所は、独特のボヘミアンな雰囲気を醸し出しており、サクレ・クール寺院からはパリのパノラマビューを楽しめます。レストラン、カフェ、小さなブティックが、この体験をさらに充実させてくれます。散策しながら、この街のアートの歴史と現在のクリエイティブな生活を知ることができます。昼も夜も楽しめる、理想的なアクティビティです。\"}'),
(425, 'ja', 9, 'experiences', '{\"title\":\"ドナウ川夕暮れクルーズ\",\"description\":\"ドナウ川クルーズで、ブダペストの魅惑的な夜のパノラマをお楽しみください。ライトアップされた鎖橋、国会議事堂、ブダ城の壮大な景色をご覧いただけます。船上では、お食事やお飲み物もご用意しております。カップルにも、ご友人同士にも、ロマンチックな雰囲気をお楽しみいただけるプログラムです。あらゆる方向から素晴らしい写真スポットが広がっています。\"}'),
(426, 'ja', 10, 'experiences', '{\"title\":\"ブダ城地区散策\",\"description\":\"歴史あるブダ城地区の通りを散策し、中世の城壁や城郭が過去数世紀の物語を語る様子をご覧ください。 街とドナウ川の眺めは、他に類を見ないほど素晴らしいものです。 観光名所としては、漁師の砦やマティアス教会などがあります。 この周辺には、博物館や雰囲気のあるカフェがたくさんあります。 文化とリラクゼーションに満ちた1日を過ごすのに理想的な場所です。\"}'),
(427, 'ja', 11, 'experiences', '{\"title\":\"セゲド市内中心部の散策\",\"description\":\"セゲドの陽光あふれるダウンタウン、有名なアールヌーボー様式の建物、広々とした広場を探索しましょう。 ドーム広場の壮大な大聖堂は、特別な写真撮影スポットです。散策しながら、地元のカフェ、公園、文化施設を発見することができます。この街の美食も、地元の特産品で試してみる価値があります。静かな通りは、楽しい午後のプログラムに最適です。\"}'),
(428, 'ja', 12, 'experiences', '{\"title\":\"デブレツェン大聖堂訪問\",\"description\":\"デブレツェンの歴史的建造物、街のシンボルである大聖堂をご覧ください。この巨大な建物の内部は印象的で、豊かな宗教的遺産を伝えています。聖堂周辺は散歩や休憩に最適です。地元の文化地区やカフェを探索してみてください。この街には他にも見どころがたくさんあります。\"}'),
(429, 'ja', 33, 'experiences', '{\"title\":\"ブダペスト市内観光サイクリングツアー\",\"description\":\"ガイド付き自転車ツアーで、ブダペストの観光スポットを2輪で巡ろう。ルートには、国会議事堂、ブダ城、ドナウ川沿い、その他いくつかの象徴的なスポットが含まれています。 ツアーでは、この街の歴史に関する地元の逸話や興味深い話も聞くことができます。自転車なら、より短い時間でより多くの観光スポットを巡ることができます。快適なペースで、初心者にも街を探索する方にも最適です。\"}'),
(430, 'ja', 34, 'experiences', '{\"title\":\"ブダペストのグルメマーケット試食会\",\"description\":\"ブダペストの有名な大市場を訪れて、地元の食材、チーズ、食品の品揃えの豊富さを体験しよう。 市場の上階にはレストランもあり、伝統的なハンガリー料理を味わうことができます。地元の料理と伝統的なハンガリーの味をお楽しみください。市場周辺を散策すると、さらに多くの地元のレストランやカフェを見つけることができます。観光の1日の終わりに、理想的なグルメ体験をお楽しみください。\"}'),
(431, 'ja', 32, 'experiences', '{\"title\":\"セーチェーニ温泉とウェルネス\",\"description\":\"ブダペストの有名な温泉、セーチェーニ温泉でリラックスしたひとときを過ごしてみて。ここはヨーロッパ最大級の温泉施設なんだ。ネオバロック様式の建物には、温泉プールやウェルネスサービスがそろっていて、一日中ゆっくり過ごせるよ。サウナ、スチームバス、マッサージサービスも利用できる。 この場所の特別な雰囲気は、地元の人も観光客もみんな気に入っているよ。入浴後は、この周辺にある伝統的なハンガリー料理レストランもぜひ試してみてね。\"}'),
(432, 'ja', 47, 'experiences', '{\"title\":\"ブダペストの鎖橋の夜の散歩\",\"description\":\"世界的に有名なセーチェーニ鎖橋を渡って、ドナウ川の両岸、ブダとペストをつないでみて。これはブダペストで最も有名なアイコンのひとつで、ライトアップされた街と川岸が特に素敵な雰囲気を醸し出してるよ。 橋の歴史は1840年代にまでさかのぼり、現在では街のシンボルとなっています。街のパノラマと主要な観光スポットを眺めながら、橋を歩いて渡ってみてください。周辺にはレストランやカフェがたくさんあり、楽しい夜のプログラムにぴったりです。\"}'),
(433, 'ja', 48, 'experiences', '{\"title\":\"ブダ城と王宮\",\"description\":\"歴史的なブダ城を訪れてみてください。王宮と城地区は、豊かな歴史的遺産を誇っています。この複合施設には、ハンガリー国立美術館とブダペスト歴史博物館も含まれています。 城のテラスからは、ドナウ川とペスト地区の見事な景色を眺めることができます。この場所はユネスコの世界遺産に登録されており、文化的、歴史的体験の両方を楽しむことができます。中世およびバロック時代の建築を探索し、城壁沿いを散策してください。\"}'),
(434, 'ja', 30, 'experiences', '{\"title\":\"プラハのビールテイスティングツアー\",\"description\":\"ガイド付きビールテイスティングツアーで、プラハのビール文化を発見しましょう。このツアーでは、複数の地元のビールバーを訪れます。チェコは優れたビールで有名であり、このツアーでは、一晩でさまざまなスタイルのビールを味わうことができます。 ガイドが、ビール醸造の歴史や地元の伝統について解説します。友人グループや、ユニークなグルメプログラムとしても最適です。散策の合間に、地元の軽食もぜひお試しください。\"}'),
(435, 'ja', 2, 'experiences', '{\"title\":\"プラハ旧市街観光\",\"description\":\"石畳の通りや歴史的な建物が街の歴史を物語る、プラハの歴史的な旧市街を詳しく散策しながら発見しましょう。旧市街広場、天文時計、そして近くの田舎風の路地を訪れてみてください。 この体験では、地元の物語や伝説について知ることができます。プラハの特別な雰囲気は、カフェや人形遣いによって忘れられないものとなっています。一日の終わりには、地元のレストランでチェコ料理の特選料理をお楽しみください。\"}'),
(436, 'ja', 29, 'experiences', '{\"title\":\"プラハ国立劇場の夕べ\",\"description\":\"プラハの国立劇場での公演で、オペラ、バレエ、演劇など、クラシックなチェコ文化をお楽しみください。歴史的な建物の豪華な内装と優れた音響効果も、この体験に一役買っています。 地元のアーティストやゲスト出演者による公演は、地元の人だけでなく、観光客にも忘れられない体験を提供します。このプログラムは、芸術に熱心な人も、新しい文化体験を求めている人も、どちらも楽しめるものとなっています。最高の席を事前に予約しましょう。\"}'),
(437, 'ja', 4, 'experiences', '{\"title\":\"ヴルタヴァ川クルーズ\",\"description\":\"川船に乗って、プラハのヴルタヴァ川の景色をお楽しみください。カレル橋、街のパノラマ、川岸の建物がまったく新しい視点からご覧いただけます。船上のガイドが、この街に関する興味深いお話をしてくれます。船上から眺める夕日は特にロマンチックです。 この体験を夕食と組み合わせて、1日まるまる楽しめるプランにするのもおすすめです。\"}'),
(438, 'ja', 3, 'experiences', '{\"title\":\"プラハ城と聖ヴィート大聖堂\",\"description\":\"プラハで最も有名な歴史的建造物群を訪れ、何世紀にもわたる歴史を学ぼう。聖ヴィート大聖堂の印象的なゴシック建築と精巧な装飾は圧巻だ。城壁を歩きながら、街のパノラマビューを堪能しよう。 周辺には博物館や公園もあります。この体験は、特に写真撮影に最適なスポットが豊富な、街歩きをさらに充実させてくれます。\"}'),
(439, 'ja', 28, 'experiences', '{\"title\":\"プラハのカレル橋の夕方の散歩\",\"description\":\"14世紀に建設され、今日ではプラハの最も有名な観光名所の一つとなっている歴史的なカレル橋を歩いて渡ってみてください。橋の上からは、ガイドなしででもヴルタヴァ川と街の景色を望むことができ、特に夕焼けの時間帯は息をのむほど美しいです。 橋沿いでは、ストリートアーティストや楽器奏者たちが、プラハの雰囲気を醸し出しています。この周辺の狭い通りや雰囲気のあるカフェは、夜のプログラムにぴったりです。この散歩は、プラハの歴史を探求する旅の完璧なスタートとなるでしょう。\"}'),
(440, 'ja', 5, 'experiences', '{\"title\":\"ウィーンクラシック音楽の夕べ\",\"description\":\"モーツァルト、シュトラウス、その他の偉大な芸術家たちの作品が演奏されるクラシックコンサートで、ウィーンの世界的に有名な音楽の世界に浸ってみては。歴史あるコンサートホールの素晴らしい音響と装飾が、思い出に残る体験をお届けします。コンサートの前には、この地域の魅力的な通りを散策してみては。 街のカフェでは、地元のケーキやコーヒーを楽しむことができます。文化や音楽好きの方に理想的なプログラムです。\"}'),
(441, 'ja', 82, 'experiences', '{\"title\":\"ブルノ音楽＆イベントナイト\",\"description\":\"ブルノの地元の音楽イベントに参加してみませんか？この街では、地元のアーティストによるコンサートやイベントが、街中の文化スペースで開催されています。雰囲気のある会場とバーが組み合わさって、理想的な夜のプログラムを提供しています。この地元の体験は、ブルノの音楽と文化の生活を垣間見ることができ、訪問者に忘れられない思い出を届けてくれます。\"}'),
(442, 'ja', 7, 'experiences', '{\"title\":\"リンツのドナウ川沿いの散歩\",\"description\":\"リンツのドナウ川沿いを散策しながら、モダンと歴史的な建築が融合した街並みを楽しみましょう。ドナウ川沿いにはカフェや展望スポットが点在しています。 川沿いの遊歩道は、ピクニックや休憩に最適です。 街のアート地区もぜひ訪れてみてください。散歩しながら、リンツの文化と雰囲気を知ることができます。\"}'),
(443, 'ja', 26, 'experiences', '{\"title\":\"ウィーン・プラーター遊園地の体験\",\"description\":\"ウィーンのプラーター遊園地は、ウィーンにある伝説的な娯楽施設で、あらゆる年齢層の人々が楽しめるアトラクションが揃っています。公園の象徴である大観覧車「リーゼンラート」からは、街の素晴らしいパノラマ景色を眺めることができ、必見です。 遊園地には、数多くのジェットコースター、ゲーム、レストランがあり、一日中楽しむことができます。100年以上の歴史を持つこの場所は、娯楽だけでなく、歴史的な体験も提供してくれます。家族連れや友人グループに、昼も夜も理想的な場所です。\"}'),
(444, 'ja', 81, 'experiences', '{\"title\":\"ブルノのグルメ＆観光\",\"description\":\"ブルノの雰囲気あるレストランやカフェを、地元のグルメツアーで発見しながら、街の歴史的な中心部も知ることができます。散策中は、街の歴史的な広場や建物を眺めながら、地元の特産品を味わうことができます。この体験は、美食と街探訪の両方に理想的です。\"}'),
(445, 'ja', 6, 'experiences', '{\"title\":\"シェーンブルン宮殿と庭園\",\"description\":\"オーストリア皇帝一家がかつて住んでいた、シェーンブルン宮殿の豪華な部屋を探検してみよう。 バロック様式の庭園や公園は、リラックスした散歩に最適な場所です。ヨーロッパで最も古い動物園のひとつである、宮殿の動物園もぜひご覧ください。庭園からはウィーンの素晴らしい景色を一望できます。このプログラムには、写真撮影の休憩やガイドツアーも含まれています。\"}'),
(446, 'ja', 80, 'experiences', '{\"title\":\"チェスキー・ブジェヨヴィツェのアイアン・メイデン・タワー\",\"description\":\"中世の刑務所や要塞だったアイアン・メイデン・タワーを探索して、歴史的な武器や展示品を見てみよう。この塔はかつて街を守る役割を担っていたけど、今は訪問者にエキサイティングな文化プログラムを提供しているよ。 周辺の旧市街やカフェは、午後の長い散歩にぴったりの場所です。:contentReference[oaicite:5]{index=5}\"}'),
(447, 'ja', 79, 'experiences', '{\"title\":\"チェスキー・ブジェヨヴィツェ ブラックタワーキロタ\",\"description\":\"チェスケー・ブジェヨヴィツェの歴史的なブラックタワー展望台を訪れてみてください。この塔は、16 世紀に防衛目的で建設され、現在では街のパノラマビューを楽しめる展望台となっています。近くにある中世の建物や風情ある通りは、街を探索するのに理想的な環境です。 展望台からは、街を見渡す素晴らしいパノラマが広がっています。:contentReference[oaicite:4]{index=4}\"}'),
(448, 'ja', 27, 'experiences', '{\"title\":\"ウィーンのクリスマスマーケット\",\"description\":\"11月末から12月にかけてウィーンを訪れるなら、何十もの手工芸品店が伝統的なギフトやグルメを販売する有名なクリスマスマーケットをお見逃しなく。ラートハウス広場で開催されるマーケットでは、地元の料理、ホットワイン、お祝いの手工芸品を味わうことができます。 生演奏、イルミネーション、家族向けのプログラムが、このイベントを忘れられないものにしてくれます。マーケットは市内の複数の場所で開催されているため、観光の合間に気軽に立ち寄ることができます。クリスマスシーズンの賑わいは、ウィーンの文化の伝統のハイライトのひとつです。\"}'),
(449, 'ja', 31, 'experiences', '{\"title\":\"ウィーンの美術館\",\"description\":\"ウィーンは、古典芸術と現代芸術が融合した、豊かな博物館やギャラリー文化を誇っています。絵画、彫刻、展示など、さまざまな見どころがある、この街で有名な博物館を訪ねてみてください。 クンストヒストリシェス美術館とアルベルティーナ美術館のコレクションは、芸術に興味のある方にとって特に興味深いものです。ギャラリーを歩きながら、ハプスブルク家の芸術品コレクションもご覧いただけます。このプログラムは、1日かけての観光の文化的な補完として最適です。\"}'),
(450, 'ja', 43, 'experiences', '{\"title\":\"マルメのデザイン散策\",\"description\":\"マルメのモダンな建築とデザイン地区を探索しましょう。この地区では、洗練されたスタイルの広場やクリエイティブな空間があなたをお待ちしています。 散策の途中には、現代アートの施設やショップも見つかるよ。 都市公園や広場は、リラックスした一日を過ごすのに理想的な場所だ。地元のカフェでは、特別な味を楽しめる。この体験は、創造性と観光を融合したものだ。\"}'),
(451, 'ja', 21, 'experiences', '{\"title\":\"ストックホルム旧市街の散策\",\"description\":\"ストックホルムの歴史的な旧市街、ガムラスタンを探索しましょう。狭い通り、カラフルな家々、そして居心地の良いテラスがあなたをお待ちしています。この街の豊かな歴史を知るために、博物館やビジターセンターもプログラムに含まれています。 海岸の景色とスカンジナビアスタイルのカフェが、この体験に特別な雰囲気を添えています。散策の途中、地元の工芸品や特産品を味わうのもおすすめです。ストックホルムは、訪問者に文化と自然の両方の価値を提供しています。\"}'),
(452, 'ja', 22, 'experiences', '{\"title\":\"マルメのモダンな街歩き\",\"description\":\"都市維持とデザインソリューションが独特の雰囲気を醸し出す、マルメのモダンな一面をご覧ください。 緑豊かな公園や革新的な都市空間は、散策に最適です。 地元のストリートアートやカフェの雰囲気は、特別な体験を提供してくれます。 海岸や港に近く、若々しい生活感にあふれた街です。 数日間の観光やリラックスしたプログラムに最適です。\"}'),
(453, 'ja', 42, 'experiences', '{\"title\":\"ストックホルム水上ツアー\",\"description\":\"ストックホルムの有名な水路を船で巡って、街の特徴的な島々や建物が水から見るのも素晴らしい景色を楽しもう。船旅では、歴史的なものと現代的なものが一緒になって、忘れられないパノラマを作り出してるよ。このツアーは、家族連れにも友達同士にもぴったりだよ。 港沿いには、地元のグルメを楽しめるレストランやカフェが並んでいます。この水上アドベンチャーは、1日かけて楽しむプログラムにもぴったりです。\"}'),
(454, 'ja', 63, 'experiences', '{\"title\":\"ストックホルム博物館ツアー\",\"description\":\"ストックホルムの文化を、現代美術と古典美術の両方が楽しめる美術館やギャラリー巡りで発見しよう。 この街にある美術館は、さまざまなスタイルの幅広いコレクションを所蔵しています。ツアーでは、インタラクティブな展示や歴史的な展示を見学することができます。このプログラムは、屋外での散歩と組み合わせるのも理想的です。街が海岸に近く、1日を通して特別な雰囲気を味わうことができます。\"}'),
(455, 'ja', 64, 'experiences', '{\"title\":\"マルメのナイトツアー\",\"description\":\"マルメのナイトライフと観光を、夜の散歩で発見しましょう。街のモダンな建物、イルミネーション、カフェが特別な雰囲気を醸し出しています。 夜の散歩では、街の中心部や公園がライトアップされて、さらに幻想的な雰囲気になります。この雰囲気の中で、地元のレストランを見つけてみてください。街の文化を発見できる、楽しい夜のプログラムです。\"}'),
(456, 'ja', 78, 'experiences', '{\"title\":\"ポズナン音楽の夕べ＆文化プログラム\",\"description\":\"ブラチスラバでクラシック音楽コンサートや地元のジャズナイトが楽しめる文化の夕べに参加してみませんか。地元のミュージシャンによる演奏と街の魅力的な雰囲気が融合したこのプログラムは、夜のレジャーにぴったりです。ディナーや街歩きと組み合わせても素晴らしい体験になるでしょう。\"}'),
(457, 'ja', 69, 'experiences', '{\"title\":\"ストックホルム近代美術館ツアー\",\"description\":\"ストックホルムのエキサイティングな現代美術館を訪れて、現代アートや技術に関する展示を見てみよう。 この街の文化施設は、歴史、現代、インタラクティブな展示など、さまざまなコレクションで構成されています。美術館巡りは、港のパノラマツアーや街中のグルメツアーと組み合わせるのも良いでしょう。このプログラムは、誰にとっても理想的な都市文化の冒険となるでしょう。\"}'),
(458, 'ja', 68, 'experiences', '{\"title\":\"ストックホルム旧市街、ガムラスタン散策\",\"description\":\"ストックホルムの歴史的な旧市街、ガムラスタンを探索しましょう。曲がりくねった石畳の通りや古い建物が、現代的な都市生活と調和しています。この地域は 13 世紀以来、スウェーデンの首都の建築と歴史において中心的な役割を果たしており、ノーベル博物館や王宮など、数多くの象徴的な建物があります。 ストートーゲト広場を散策し、古いアーケードのある家々を見学した後、居心地の良いカフェで地元のスウェーデン料理を味わってみてください。この体験は、歴史、文化、そして都市の雰囲気をすべて兼ね備えています。:contentReference[oaicite:1]{index=1}\"}'),
(459, 'ja', 70, 'experiences', '{\"title\":\"マルメの博物館と歴史的な城の訪問\",\"description\":\"マルメ博物館でマルメの文化的な側面を発見しましょう。この博物館の展示は、この都市の技術、歴史、自然の遺産を紹介しています。博物館のメイン会場は、歴史的なマルメ城の複合施設で、考古学や海洋関連のコレクションなども展示されています。 展示を見学したら、公園のような城の庭園を散策して、この街の歴史に触れてみてね。マルメは、過去と現在の文化がエキサイティングに融合した街なんだ。:contentReference[oaicite:2]{index=2}\"}'),
(460, 'ja', 77, 'experiences', '{\"title\":\"ブラチスラバ旧市街の歴史散歩\",\"description\":\"中世の街並み、雰囲気のある広場、豊かな建築遺産が待つ、ブラチスラバの歴史的な旧市街を探索しましょう。 メイン広場と旧市庁舎は、一日中散策するのに特別な雰囲気を醸し出しています。ガイド付きツアーや個人旅行で、この街の歴史と伝説について学びましょう。この散策は、長い都市旅行に理想的なプログラムです。:contentReference[oaicite:3]{index=3}\"}'),
(461, 'ja', 15, 'experiences', '{\"title\":\"ベルリンの歴史的観光\",\"description\":\"ベルリンの歴史的中心部を探索し、現代と過去の両方の記憶に触れてみましょう。ブランデンブルク門、ベルリンの壁の残骸、ライヒスタッグの建物は、いずれも重要な観光名所です。 街には数多くの博物館や公園があり、1日かけて楽しむことができます。地元のグルメは、ベルリンの個性を反映しています。家族や友人との観光に理想的な街です。\"}'),
(462, 'ja', 35, 'experiences', '{\"title\":\"ベルリン博物館島の日\",\"description\":\"ベルリンの有名な博物館島は、芸術や歴史に興味のある人なら誰でも楽しめる、世界的に有名なコレクションがそろっているよ。いくつかの象徴的な博物館があり、美術品や歴史的な展示品を見ることができるんだ。 この場所はユネスコの世界遺産に登録されているため、1日かけて見学することも可能です。コレクションには古代から現代までの作品が含まれています。周辺にはカフェや公園もあり、素晴らしい文化体験が待っています。\"}'),
(463, 'ja', 36, 'experiences', '{\"title\":\"ベルリンのストリートアート散策\",\"description\":\"ガイド付きストリートアートツアーで、ベルリンのもうひとつの顔を見つけよう。この街で有名な壁画やグラフィティ文化を知ることができるよ。ツアーでは、地元のアーティストたちの作品を通して、現代ベルリンの文化を垣間見ることができる。 このツアーでは、クリエイティブなコミュニティやカフェが点在する地区も訪れます。このプログラムは、芸術に興味のあるすべての人にとって、インタラクティブで刺激的な体験となるでしょう。ツアーの後は、地元のカフェでくつろぐのもおすすめです。\"}'),
(464, 'ja', 16, 'experiences', '{\"title\":\"ミュンヘンのビール文化ツアー\",\"description\":\"伝統的な醸造所を見学して試飲しながら、ミュンヘンの有名なビール文化について学びましょう。 バイエルン州のビールは世界的に有名で、地元のビアガーデンでは本格的な雰囲気を味わうことができます。ツアーでは、専門ガイドがビール醸造の歴史と伝統について解説します。街の歴史的な広場や公園を歩きながら、さらに多くの見どころを発見することができます。友人グループやビール好きの方に最適な体験です。\"}'),
(465, 'ja', 56, 'experiences', '{\"title\":\"ベルリンのブランデンブルク門の夜の写真撮影\",\"description\":\"ベルリンの有名なブランデンブルク門を、ライトアップされた記念碑が特に印象的な夜の散歩で訪れてみてください。この門は、ドイツの歴史の重要な出来事を思い起こさせる、街で最も有名なシンボルの一つです。周辺には、くつろげるレストランやバーも数多くあります。 写真撮影だけでなく、ガイド付きウォーキングツアーで、この場所の歴史について話を聞くこともできます。ベルリンのダイナミックな雰囲気は、どの季節でも感じることができます。\"}'),
(466, 'ja', 57, 'experiences', '{\"title\":\"ベルリンのパノラマ展望台\",\"description\":\"モダンな展望テラスから、街全体を見渡せるベルリンの最高のパノラマを発見しよう。 この展望台は、夕陽の時間帯に街並みに特別な光をもたらすことで有名です。このプログラムでは、ベルリンの多彩な建築様式に触れながら、街の観光と写真撮影を組み合わせることができます。展望台の周辺には、ショップやカフェも多数あり、若者にもご家族にも理想的なスポットです。\"}'),
(467, 'ja', 50, 'experiences', '{\"title\":\"メメント公園野外博物館\",\"description\":\"ブダペストのユニークな博物館、メメント公園を訪れてみてください。ここでは、共産主義時代に建てられた彫像や記念碑が野外展示されています。この公園は、社会主義体制の記念碑がここに集められた歴史的な時代を彷彿とさせます。 過去の力と民主主義の重要性を強調する、印象的なレーニンとマルクスの像もぜひご覧ください。この場所は、過去の時代の社会史をインタラクティブに紹介しています。歴史に興味のある方に理想的なプログラムです。:contentReference[oaicite:2]{index=2}\"}'),
(468, 'ja', 53, 'experiences', '{\"title\":\"デブレツェン・ナジエルデイ体験公園\",\"description\":\"デブレツェンの緑の心臓部、ナジエルド（Nagyerdő）を発見してください。ここでは、野外プログラムや体験型公園が訪問者を待っています。 公園を散策しながら、数多くの休憩所や文化イベントを楽しむことができます。子供向けの遊び場やスポーツ施設も整備されており、この場所を特別なものにしています。ナジエルドでは、音楽イベントや文化フェアも頻繁に開催されています。ご家族やご友人とのレジャーに理想的な場所です。\"}'),
(469, 'ja', 52, 'experiences', '{\"title\":\"セゲド大聖堂広場コンサート＆散策\",\"description\":\"夕方の散歩やコンサートのために、セゲドのドーム広場を訪れてみてください。この街で有名なメイン広場は、特別な雰囲気を醸し出しています。 記念碑的な大聖堂と周辺の建築は、他に類を見ない光景を演出しています。広場や近くのステージでは、クラシックやポピュラー音楽の夕べが頻繁に開催されています。このプログラムでは、街の建築美と地元の文化を満喫することができます。広場沿いには、雰囲気のあるカフェやレストランも並んでいます。\"}'),
(470, 'ja', 49, 'experiences', '{\"title\":\"聖イシュトヴァーン大聖堂＆展望台\",\"description\":\"ブダペストで3番目に大きい教会、聖イシュトヴァーン大聖堂は、最も美しい新古典主義建築のひとつでもあります。大聖堂の内部には、ハンガリー初代国王、聖イシュトヴァーンの右手が展示されています。 塔の展望台からは、街を360°見渡せるパノラマが広がり、特に夕焼けは圧巻です。教会では定期的にオルガンコンサートが開催されており、その雰囲気はぜひ体験する価値があります。この場所は、歴史的、そして精神的な体験の両方を提供してくれる場所です。:contentReference[oaicite:1]{index=1}\"}'),
(471, 'ja', 51, 'experiences', '{\"title\":\"ゲッレールト山洞窟＆展望台\",\"description\":\"ゲッレールト山の洞窟を訪れてみてください。この洞窟は、街で最も美しいパノラマを望む場所にある天然の洞窟群です。洞窟の歴史は、自然の癒しの力を知ることのできる、ある隠者の伝説と結びついています。山の頂上からは、ドナウ川と街の見事な眺めを楽しむことができます。 洞窟のほかに、ゲッレールト温泉や山の周辺も、リラックスするのに最適な場所です。この小旅行では、自然、歴史、街のパノラマを同時に楽しむことができます。:contentReference[oaicite:3]{index=3}\"}'),
(472, 'ja', 72, 'experiences', '{\"title\":\"オスロのスカンジナビア料理ツアー\",\"description\":\"オスロの食文化を、地元の味を紹介する市内ツアーで満喫しよう。フィヨルド沿いのレストランで、ノルウェーの特産品、新鮮な魚料理、伝統的な料理を味わってみて。 グルメツアーでは、地元の市場やモダンなビストロも訪れます。このプログラムは、食体験と街探検を特別に組み合わせたものです。\"}'),
(473, 'ja', 23, 'experiences', '{\"title\":\"オスロフィヨルドツアー\",\"description\":\"オスロの有名なフィヨルドを訪れ、都市環境の中でノルウェーの自然を間近に感じてください。ボートツアーでは、フィヨルドのパノラマと特別な入り江を発見することができます。フィヨルド沿いのツアーでは、水辺のカフェやレストランも訪問者をお待ちしています。 澄んだ空気と山々の景色は、忘れられない体験となるでしょう。この終日プログラムでは、自然と都市生活を組み合わせることができます。\"}'),
(474, 'ja', 24, 'experiences', '{\"title\":\"ヘルシンキのデザイン観光\",\"description\":\"建築とクリエイティブな空間で世界的に有名なヘルシンキのモダンなデザイン文化を発見しよう。 この街の洗練された建物、ギャラリー、美術館は、刺激的な体験を提供してくれます。散策しながら、地元のデザインショップやカフェに立ち寄ってみてください。海辺の遊歩道や公園は、リラックスできる落ち着いた雰囲気です。ヘルシンキでは、文化と自然が調和して融合しています。\"}'),
(475, 'ja', 44, 'experiences', '{\"title\":\"オスロフィヨルドの夕日ツアー\",\"description\":\"オスロの有名なフィヨルドを、夕陽の時間帯のクルーズで発見しましょう。景色と海が出会うこのツアーは、特別な雰囲気を醸し出しています。 フィヨルド沿いには、ノルウェーの素晴らしい自然が広がり、街のパノラマも一望できます。このツアーは、ロマンチックな夜のプログラムや家族での小旅行に最適です。船上では、コーヒーや地元の軽食も楽しめます。自然と都市の体験が融合した、エキサイティングなツアーです。\"}'),
(476, 'ja', 71, 'experiences', '{\"title\":\"オスロ・フィヨルド地区の設置\",\"description\":\"オスロフィヨルド沿いの遊歩道の穏やかな雰囲気を楽しみましょう。ここでは、海岸とモダンな都市生活が融合しています。 遊歩道は、ロマンチックな夜や友人たちとの集まりに最適な場所であり、街のパノラマと水辺の近さが、都会の冒険に特別な雰囲気を添えています。周辺には、地元の特産品を提供するレストランやカフェが数多くあります。このプログラムは、自然の美しさと都会の体験を融合したものです。\"}'),
(477, 'ja', 65, 'experiences', '{\"title\":\"オスロ・オペラハウスとフィヨルドのパノラマ\",\"description\":\"オスロの象徴的なオペラハウスを訪れてみてください。そのモダンな建築は人々を魅了し、フィヨルドのパノラマビューも楽しめます。 屋上に上がると、フィヨルドと街の見事な景色が広がっています。プログラムでは、ウォーターフロントの遊歩道も散策しましょう。オペラ座前のエリアは、ピクニックや夕日を眺めるのに最適です。この体験は、モダンな建築と自然のパノラマを融合したものです。\"}'),
(478, 'ja', 45, 'experiences', '{\"title\":\"ヘルシンキ博物館の日\",\"description\":\"ヘルシンキの芸術博物館や歴史博物館を訪れて、フィンランドの文化や歴史に関する豊富なコレクションを見てみよう。 博物館は互いに近接しているため、1日かけてゆっくり見学することができます。展示には、インタラクティブな要素や地域の歴史に関する詳細情報も含まれています。博物館巡りの後は、海辺の散歩や地元のカフェを訪れてみてはいかがでしょうか。悪天候時にも最適なアクティビティです。\"}'),
(479, 'ja', 66, 'experiences', '{\"title\":\"ヘルシンキの海岸沿いの散歩\",\"description\":\"ヘルシンキの海岸沿いの遊歩道を散策しましょう。海風と緑豊かな遊歩道は、リラックスして景色を楽しむのに理想的な環境です。 ウォーターフロントの遊歩道沿いには、地元の特産品を味わえる小さなレストランやカフェが並んでいます。自然と都市の体験を組み合わせた、楽しい日中のアクティビティです。\"}'),
(480, 'ja', 73, 'experiences', '{\"title\":\"ヘルシンキデザイン散策\",\"description\":\"ヘルシンキは、北欧のデザインとモダンな建築の拠点であり、徒歩で探索する価値があります。この街の特徴的な建物や標準的なデザイン例は、スカンジナビアの創造性を示しています。 散策しながら、地元のデザイン博物館、ギャラリー、ブティックを訪ねてみましょう。この文化体験は、創造性、都市公園、そして海辺のパノラマを融合したものです。\"}'),
(481, 'ja', 74, 'experiences', '{\"title\":\"ヘルシンキの夕焼けクルーズ\",\"description\":\"サンセットクルーズでヘルシンキの海岸のパノラマを満喫しよう。水上から眺める街の景色は特別な体験になるよ。船上のカフェでは、地元の軽食も味わえるし、沈みゆく太陽が港や街を照らす様子も楽しめる。 このプログラムは、ロマンチックな体験としても、街への小旅行としても理想的です。\"}'),
(482, 'ja', 6, 'accommodations', '{\"title\":\"パルツアパートメント\",\"description\":\"セゲドのダウンタウンと市場に近い、改装済みアパート。広くて明るい部屋、モダンな設備。家族連れや短期滞在に最適。周辺にはレストランや文化施設がたくさん。快適でアットホームな雰囲気でお客様をお迎えします。\"}'),
(483, 'ja', 9, 'accommodations', '{\"title\":\"モダンなスタジオ\",\"description\":\"ブダペスト中心部にある明るくモダンなスタジオ。快適な家具、実用的なレイアウト、必要な設備がすべて揃っています。カップルやビジネス旅行者に最適です。市内の観光スポットやレストランは徒歩圏内にあります。快適さと都会的な生活の完璧な組み合わせです。\"}'),
(484, 'ja', 8, 'accommodations', '{\"title\":\"都心のアパート\",\"description\":\"ブダペストの中心部にある、居心地の良いアパートメント。モダンな家具と実用的なレイアウトが、あらゆるニーズを満たします。ご家族やご友人グループに最適です。近くのレストラン、ショップ、観光スポットへも簡単にアクセスできます。都市体験とリラクゼーションに最適な場所です。\"}'),
(485, 'ja', 31, 'accommodations', '{\"title\":\"ハギマティクム付近\",\"description\":\"マコンにある快適なアパートメントで、ハグミティクム温泉の近くにあります。広々として明るく、モダンな家具が備わっています。ご家族やカップルに最適です。周辺にはレストランや観光スポットがたくさんあります。リラックスしてくつろぐのに最適な場所です。\"}'),
(486, 'ja', 7, 'accommodations', '{\"title\":\"ブダペスト市内、Szabadság Rezidencia\",\"description\":\"ブダペスト中心部にあるモダンなアパートメントで、絶好のロケーションです。明るく設備の整ったこのアパートメントは、カップルやビジネス旅行者に最適です。周辺にはレストラン、カフェ、観光スポットがたくさんあります。公共交通機関へのアクセスも便利です。観光やリラックスに最適な選択肢です。\"}'),
(487, 'ja', 10, 'accommodations', '{\"title\":\"パノラマビューのアパート\",\"description\":\"広々としたアパートで、美しい景色が楽しめ、家族連れに最適です。モダンな設備と快適な家具が、あらゆるニーズを満たします。街の中心部や観光スポットにも近いです。周辺は静かで、落ち着いた休息が楽しめます。一日中、パノラマの景色をお楽しみください。\"}'),
(488, 'ja', 36, 'accommodations', '{\"title\":\"セゲド市内中心部のアパート\",\"description\":\"セゲド中心部にある明るく快適なアパートメント。モダンな家具と実用的な間取り。市場、レストラン、文化施設が近くにあります。ご家族やご友人との滞在に最適です。リラックスや街の体験にぴったりの場所です。\"}'),
(489, 'ja', 35, 'accommodations', '{\"title\":\"ブダペストの豪華なアパート\",\"description\":\"ブダペスト中心部にある広々としたモダンなアパート。エレガントな家具、設備の整ったキッチン、快適なベッドルーム。ご家族やご友人グループに最適です。観光スポットやレストランも近く、首都の活気ある生活をいつでもお楽しみいただけます。\"}'),
(490, 'ja', 85, 'accommodations', '{\"title\":\"メルボルンデザインアパートメント\",\"description\":\"メルボルンの中心部にあるスタイリッシュでモダンなアパートメント。明るい空間と快適なベッド。カップルやビジネス旅行者に最適です。カフェ、レストラン、アートスポットも近くにあります。自分のアパートメントで、この街のクリエイティブな雰囲気をお楽しみください。\"}'),
(491, 'ja', 84, 'accommodations', '{\"title\":\"シドニー・ハーバー・アパートメント\",\"description\":\"シドニー中心部にある、港を見渡せる美しいモダンなアパートメント。広々としたリビングルーム、快適なベッドルーム。ご家族やカップルに最適です。レストランや観光スポットも近くにあります。オーストラリアの都市生活を存分にお楽しみください。\"}'),
(492, 'ja', 100, 'accommodations', '{\"title\":\"ポルトデザインアパートメント\",\"description\":\"ポルト中心部にあるスタイリッシュでモダンなアパートメント。快適なベッド、設備完備。カップルやビジネス旅行者に最適です。観光スポットやレストランも近くにあります。快適な環境でポルトガルの都市生活をお楽しみください。\"}'),
(493, 'ja', 99, 'accommodations', '{\"title\":\"リスボン・サンシャイン・アパートメント\",\"description\":\"リスボンの歴史的中心部にある、明るく広々としたアパートメント。モダンな家具、快適なベッド。ご家族やカップルに最適です。観光名所やレストランにも近い。ポルトガルの都市生活を存分に満喫してください。\"}'),
(494, 'ja', 37, 'accommodations', '{\"title\":\"デブレツェン・パノラマ・アパートメント\",\"description\":\"デブレツェン中心部にある広々としたモダンなアパート。明るいリビングルームと快適なベッドルーム。設備が整っていて、家族やカップルに最適。レストランやショッピング施設まで歩いて行ける距離。デブレツェンの街での生活を存分に楽しんでください。\"}'),
(495, 'ja', 29, 'accommodations', '{\"title\":\"歴史的な住居\",\"description\":\"歴史的な雰囲気のあるギリシャのアパート。クラシックな内装で、明るく広々としています。ご家族やご友人グループに最適です。地元の観光スポットやレストランにも近いです。伝統的なギリシャの環境を快適に楽しんでください。\"}'),
